bool win = false;

int dfs(int now, int past){
    int x = 2;
    if (past != -1 && e[now].size() == 1) return p[now] = 1;
    int even = 0, odd = 0;
    for (auto next : e[now]){
        if (next == past) continue;
        int y = dfs(next, now);
        if (x == 2) x = y;
        else if (x != y) x = 0;
        if (y == 1) even++;
        if (y == -1) odd++;
    }
    if (even >= 2) win = true;
    return p[now] = -x;
}

