int want[500000];

int main()
{
    cin >> n;
    if (n % 2 == 1)
    {
        cout << "First";
        return 0;
    }
    for (int i = 0; i < n - 1; i++)
    {
        int v, u;
        cin >> v >> u;
        graph[v].push_back(u);
        graph[u].push_back(v);
        into[v]++;
        into[u]++;
    }
    vector<int> q;
    for (int i = 1; i <= n; i++)
    {
        if (graph[i].size() == 1)
        {
            q.push_back(i);
            col[i] = {{q.size(), 1}, 0};
            want[i] = 1;
        }
    }
    for (int i = 0; i < q.size(); i++)
    {
        int u = q[i];
        //cout << u << " ";
        for (int j = 0; j < graph[u].size(); j++)
        {
            int v = graph[u][j];
            into[v]--;
            if (col[u].first == col[v].first) continue;
            if (col[v].first.first == 0 && col[u].second == 0)
            {
                q.push_back(v);
                col[v].first = col[u].first;
                col[v].second = 1;
                want[u] = 0;
                continue;
            }
            if (col[v].first.first == 0 && col[u].second == 1 && into[v] == 1)
            {
                q.push_back(v);
                col[v].first = {q.size(), col[u].first.second + 1};
                col[v].second = 0;
                want[v] = 1;
                continue;
            }
        }
    }
    if (q.size() != n)
    {
        cout << 1 / 0;
        return 0;
    }
    for (int i = 1; i <= n; i++)
    {
        if (want[i] == 1 && col[i].second == 0)
        {
            cout << "First";
            return 0;
        }
    }
    cout << "Second";
}

