#include <stdio.h>
#include <vector>
#include <functional>

int main() {
    int n; scanf("%d", &n);
    std::vector<std::vector<int>> g(n);
    for(int i = 0; i < n - 1; i++) {
        int a, b; scanf("%d%d", &a, &b);

        g[a - 1].push_back(b - 1);
        g[b - 1].push_back(a - 1);
    }

    bool ans = true;
    std::vector<bool> used(n, false);
    std::function<void (int, int, int)> dfs = [&](int v, int par, int turn) {
        int A = v, B = -1;
        for(auto e: g[v]) {
           if(e == par or used[e]) continue;
           B = e;
        }

        if(turn == 1) {
            if(B == -1) {
                ans = false;
                return;
            }
            used[A] = used[B] = true;
            dfs(B, v, 2);
        } else {
            if(B == -1) return;
            dfs(B, v, 1);
        }
    };
    for(int i = 0; i < n; i++) {
        if(g[i].size() != 1 or used[i]) continue;
        dfs(i, -1, 1);
    }

    if(!ans) printf("First\n");
    else printf("Second\n");
    return 0;
}

