using namespace std;

string solve(){
    int N;
    cin >> N;
    vector<vector<int> > g(N, vector<int>());
    REP(i, N-1){
        int a, b;
        cin >> a >> b;
        a--;b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> parent(N, -1);
    parent[0] = -2;
    queue<int> que;
    que.push(0);
    while(!que.empty()){
        int n = que.front();que.pop();
        REP(i, g[n].size()){
            int u = g[n][i];
            if(parent[u]!=-1)continue;
            parent[u] = n;
            que.push(u);
        }
    }
    REP(i, N){
        if(i==0 || g[i].size()>1)continue;
        que.push(i);
    }
    vector<int> used(N, 0);
    while(!que.empty()){
        int n = que.front();que.pop();
        int p = parent[n];
        if(p==-2)return "First";
        if(used[n]==1 && used[p]==2)continue;
        if(used[n] || used[p])return "First";
        used[n] = 1;
        used[p] = 2;
        n = parent[p];
        if(n==-2)continue;
        que.push(n);
    }
    return "Second";
}

int main(){
    string res = solve();
    cout << res << endl;
    return 0;
}

