using namespace std;
typedef long long ll;
int n;
vector<vector<int> > g;
bool leaf[100000];
void DFS(int u, int p) {
	if (g[u].size() == 1) {
		leaf[u] = true;
		return;
	}
	for (int i = 0; i < g[u].size(); ++i)
		if (g[u][i] != p)
			DFS(g[u][i], u);
}
pair<int, int> dp[100000];
int root;
pair<bool, bool> calc(int u, int p) {
	if (g[u].size() == 1 && u != root)
		return dp[u] = make_pair(true, false);
	pair<bool, bool> ret(false,false);
	for (int i = 0; i < g[u].size(); ++i) {
		if (g[u][i] == p)
			continue;
		pair<bool, bool> cur = calc(g[u][i], u);
		swap(cur.first, cur.second);
		ret.first |= cur.first;
		ret.second |= cur.second;
	}
	return dp[u] = ret;
}
void go(int u, int p, bool e, bool o) {
	int oc = 0, ec = leaf[u];
	for (int i = 0; i < g[u].size(); ++i) {
		if (g[u][i] == p)
			continue;
		if (dp[g[u][i]].first)
			++oc;
		if (dp[g[u][i]].second)
			++ec;
	}
	if (!leaf[u] && o && g[u].size() == 2) {
		for (int i = 0; i < g[u].size(); ++i) {
			if (g[u][i] == p || leaf[g[u][i]] || g[g[u][i]].size() != 2)
				continue;
			if (dp[g[u][i]].second) {
				puts("First");
				exit(0);
			}
		}
	}
	for (int i = 0; i<g[u].size(); ++i)
		if (g[u][i] != p) {
			int coc = oc + e;
			int cec = ec + o;
			if (dp[g[u][i]].first)
				--coc;
			if (dp[g[u][i]].second)
				--cec;
			go(g[u][i], u, coc, cec);
		}
}
int main()
{
	scanf("%d", &n);
	g.resize(n);
	for (int i = 1, a, b; i < n; ++i) {
		scanf("%d%d", &a, &b);
		--a; --b;
		g[a].push_back(b);
		swap(a, b);
		g[a].push_back(b);
	}
	if (n == 2) {
		puts("Second");
		return 0;
	}
	for (int i = 0; i < n; ++i)
		if (g[i].size() > 1) {
			DFS(i, -1);
			root = i;
			break;
		}
	for (int i = 0; i < n; ++i) {
		int c = 0;
		for (int j = 0; j < g[i].size(); ++j)
			if (leaf[g[i][j]])
				++c;
		if (c >= 2) {
			puts("First");
			return 0;
		}
	}
	for(int i=0;i<n;++i)
		if (g[i].size() == 1) {
			root = i;
			break;
		}
	calc(root, -1);
	go(root, -1, false, false);
	puts("Second");
	return 0;
}

