bool search_leaf(int parent, int elem) {
	for (int i = 0; i < connect[elem].size(); i++) {
		int child = connect[elem].at(i);
		if (child == parent) continue;

		bool find_leaf = search_leaf(elem, child);
		if (find_leaf) {
			if (used[elem]) {
				// out
				used[elem] = false;
				return false;
			} else {
				used[elem] = true;
			}
		}
	}

	if (!used[elem]) {
		used[elem] = true;
		return true;
	}
	else return false;
}

