        cout << "Second" << endl;
        return 0;
    }

    int root = 0;
    while (SZ(g[root]) == 1) root++;

    int winner = 1;
    auto dfs = [&](auto f, int v, int p) -> bool {
        if (SZ(g[v]) == 1) {
            return true;
        }
        int cnt = 0;
        FORE(w, g[v]) {
            if (w == p) continue;
            if (f(f, w, v)) cnt++;
        }
        if (cnt >= 2) {
            winner = 0;
        }
        return false;
    };
    dfs(dfs, root, -1);

    cout << (winner ? "Second" : "First") << endl;
    return (0^_^0);
}

