{
	cnt[u]=0;
	for(node *p=Adj[u];p!=NULL;p=p->nxt)
	{
		int v=p->to;
		if(v==fa)
			continue;
		if(DFS(v,u)==true)
			return true;
		if(cnt[v]==0)
			cnt[u]++;
	}
	if(cnt[u]>=2)
		return true;
	return false;
}
