bool cmp(int x, int y) {
    return deg[x] > deg[y];
}

int cou(int u) {
    int res = 0;
    for (int i = 0; i < a[u].size(); i++) {
        int v = a[u][i];
        if (a[v].size() == 1) res++;
    }
    return res;
}

int dfs(int u) {
    vis[u] = true;
    cnt++;
    for (int i = 0; i < a[u].size(); i++) {
        int v = a[u][i];
        if (!vis[v]) dfs(v);
    }
}

