        if (cou(i) >= 2) {
            cout << "First" << endl;
            return 0;
        }
    }
    if (n & 1) {
        cout << "First" << endl;
        return 0;
    }
    int b[N];
    for (int i = 1; i <= n; i++) {
        b[i] = i;
    }
    sort(b + 1, b + n + 1, cmp);
    int dem = 0;
    for (int i = 1; i <= n; i++) {
        dem += n;
        memset(vis, false, sizeof(vis));
