namespace G{
	int cnt,fir[N];
	bool linked[N];
	struct edge{
		int to,nx;
	}eg[N<<1];

	inline void add(const int a,const int b){
		eg[++cnt]=(edge){b,fir[a]};
		fir[a]=cnt;
	}

	void dfs(const int x,const int fa){
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa) continue;
			dfs(y,x);
			if(!linked[y]){
				if(linked[x]) return;
				linked[x]=linked[y]=1;
			}
		}
	}

	bool link(){
		for(int i=1; i<=n; ++i){
			if(!linked[i]) return 0;
		}
		return 1;
	}
}

