void addedge(int u,int v)
{
	d[u]++;
	d[v]++;
	e[m]=edge(v,head[u]);head[u]=m++;
	e[m]=edge(u,head[v]);head[v]=m++;
}
int dfs(int fa,int u)
{
	int cnt[3];
	memset(cnt,0,sizeof(cnt));
	bool leaf=1;
	for(int p=head[u];p!=-1;p=e[p].nxt)
	{
		int v=e[p].to;
		if(v==fa) continue;
		int tp=dfs(u,v);
		cnt[tp]++;
		leaf=0;
	}
	if(leaf) return 1;
	if(cnt[2]>=1||cnt[1]>=2) return 2;
	return 0;
}
