using namespace std;

const int MaxN = 2e5, MaxM = 4e5;
int n, all, deg[MaxN + 5];
int pre[MaxM + 5], last[MaxN + 5], other[MaxM + 5];
bool flag, even[MaxN + 5], odd[MaxN + 5], full[MaxN + 5];

void Build(int x, int y)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	deg[x]++;
}

void Init()
{
	all = -1; memset(last, -1, sizeof(last));
	memset(deg, 0, sizeof(deg));
	for (int i = 1; i <= n - 1; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		Build(u, v); Build(v, u);
	}
}

void Dfs(int orig, int x, int fa, int dep)
{
	int ed = last[x], dr, cnt = 0;
	if (deg[x] == 1) odd[x] = true;
	if (deg[x] != 1) full[x] = true;
	while (ed != -1) {
		dr = other[ed];
		if (dr != fa) {
			Dfs(orig, dr, x, dep + 1);
			full[x] &= odd[dr];
			even[x] |= odd[dr];
			odd[x] |= even[dr];
		}
		ed = pre[ed];
	}
	if (!(dep & 1) && full[x]) flag = true;
}

void Solve()
{
	flag = false;
	for (int i = 1; i <= n; i++) 
		if (deg[i] == 1) {
			Dfs(i, i, 0, 1);
			break;
		}
	if (flag) printf("First\n");
		else printf("Second\n");
}

int main()
{
	while (~scanf("%d", &n)) {
		Init();
		Solve();
	}
	return 0;
}

