/*
	首先发现一些性质
	如果一个点接了 ≥ 2 个度数为 1 的点, 那么先手赢
	那么 dfs 的时候, 就会把连在一起的
	一个度数为 1, 一个度数不为 1 的结点 (叶子和上面的那个)
	的两个点去掉不看(先手填叶子上面的), 变成一个子问题
*/
#include <iostream>
