const int dy[4] = {0, 1, 0, -1};
const double pi = 3.141592653589793;

int n;
vector<vector<int>> g(100000+5);
vector<vector<pair<bool,bool>>> eo(100000+5,vector<pair<bool,bool>>(1,make_pair(false,false)));


pair<bool,bool> dfs1(int now,int par){
    for (auto to: g[now]){
        if (to==par) continue;
        pair<bool, bool> oe=dfs1(to,now);
        if (oe.se) eo[now][0].fi=true;
        if (oe.fi) eo[now][0].se=true;
    }
    //cout << eo[now][0].fi << eo[now][0].se << true<<endl;
    if (g[now].size()==1 && par==g[now][0]){
        eo[now][0].fi=true;
        eo[now][0].se=false;
    }
    return make_pair(eo[now][0].fi,eo[now][0].se);
}

bool dfs2(int now,int par,bool even,bool odd){
    int cntodd=0;
    int cnteven=0;
    for (auto to: g[now]){
        if (to==par){
            if (even) cnteven+=1;
            if (odd) cntodd+=1;
        }
        else{
            if (eo[to][0].fi) cntodd+=1;
            if (eo[to][0].se) cnteven+=1;
        }
    }
    //cout << now <<":"<< cnteven << cntodd << endl;
    if (cntodd>=2 && cnteven==0) return true;
    for (auto to: g[now]){
        if (to==par) continue;
        bool to_even,to_odd;
        if (cnteven-(int)eo[to][0].se>=1) to_odd=true;
        if (cntodd-(int)eo[to][0].fi>=1) to_even=true;
        if (dfs2(to,now,to_even,to_odd)) return true;
    }
    return false;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    if (n==2) cout << "Second" << endl;
    int cnt[n]={};
    rep(i,n-1){
        int a,b;
        cin >> a >> b;
        a--;b--;
        cnt[a]+=1;cnt[b]+=1;
        g[a].pb(b);
        g[b].pb(a);
    }
    int root=0;
    rep(i,n){
        if (cnt[i]>=2){
            root=i;
            break;
        }
    }
    dfs1(root,-1);
    if (dfs2(root,-1,false,false)) cout << "First" << endl;
    else cout << "Second" << endl;
    return 0;
}

