inline void push(int i, int j)
{ edge[++top] = (node){j, head[i]}, head[i] = top; }

int n, u, v, d[MAXN];
int vis[MAXN];
queue<int> que;

#define NEW 0
#define LEAF 1
#define DEL 2
#define CHO 3

int main()
{
	ios::sync_with_stdio(false);
	cin >> n;
	if (n == 1) {
		puts("First");
		return 0;
	}
