	}
	for (int i = 1; i <= n; i++)
		if (d[i] == 1)
			vis[i] = LEAF, que.push(i);
	while (!que.empty()) {
		int nd = que.front(); que.pop();
		if (vis[nd] == LEAF) {
			vis[nd] = DEL;
			int flag = 1;
			for (int i = head[nd]; i; i = edge[i].next) {
				int to = edge[i].to;
				if (vis[to] == CHO) {
					puts("First");
					return 0;
				} else if (vis[to] == LEAF) vis[to] = DEL;
				else if (vis[to] == NEW) {
