#include<bits/stdc++.h>
using namespace std;

const int maxn=2e5+10;

int n,deg[maxn];
int tote,FIR[maxn],TO[maxn],NEXT[maxn];
bool vis[maxn];
queue<int> q;

void addedge(int u,int v)
{
	TO[++tote]=v;
	NEXT[tote]=FIR[u];
	FIR[u]=tote;
}

int dfs(int u,int F)
{
	int cnt=0;
	for (int p=FIR[u];p;p=NEXT[p])
	{
		int v=TO[p];
		if (v==F) continue;
		int tmp=dfs(v,u);
		if (tmp==2) return 2;
		cnt+=tmp==0;
	}
	if (cnt>=2) return 2;
	return cnt;
}

void solve()
{
	memset(FIR,0,sizeof(FIR));
	memset(vis,0,sizeof(vis));
	tote=0;
	while (!q.empty()) q.pop();
	int i,u,v;
	if (n&1) {puts("First"); return;}
	for (i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		addedge(u,v);
		addedge(v,u);
	}
	puts(dfs(1,0)==1?"Second":"First");
}

