	那么 dfs 的时候, 就会把连在一起的
	一个度数为 1, 一个度数不为 1 的结点 (叶子和上面的那个)
	的两个点去掉不看(先手填叶子上面的), 变成一个子问题
*/
#include <iostream>
#include <cstdio>
#define N 100005

using namespace std;

int n;
int head[N], nex[N << 1], to[N << 1], te;
int deg[N], fa[N], f[N];

inline void read(int &x) {
	x = 0; char ch = getchar();
	while(!isdigit(ch)) ch = getchar();
	while(isdigit(ch)) x = x * 10 + ch - '0', ch = getchar();
}
inline void ade(int u, int v) { 
	nex[++te] = head[u], head[u] = te;
	to[te] = v, ++deg[v];
}

void dfs(int u) {
	for(int i = head[u]; i; i = nex[i]) {
		int v = to[i];
		if(v == fa[u]) continue;
		fa[v] = u, dfs(v);
	}
	if(f[u] >= 2) {
		puts("First");
		exit(0);
	} if(deg[u] == 1) {
		++f[fa[u]];
		--deg[fa[fa[u]]];
	}
}

int main() {
	read(n);
	for(int i = 1, u, v; i < n; ++i) {
		read(u), read(v);
		ade(u, v), ade(v, u);
	}
	if(n == 2) return puts("Second"), 0;
	for(int i = 1; i <= n; ++i) 
	for(int i = 1; i <= n; ++i) {
		if(deg[i] == 1) continue;
		dfs(i);
		return puts("Second"), 0;
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N=100010;

struct E{
	int t,xt;
}e[N<<1];

int h[N],cnt;

void adge(int f,int t){
	e[++cnt]=(E){t,h[f]};h[f]=cnt;
}

int dp[N][2],dan[N];

void dfs1(int u,int fa){

	for(int i=h[u];~i;i=e[i].xt) if(e[i].t!=fa){
		dfs1(e[i].t,u);
	//	printf("u=%d e[i].t=%d\n",u,e[i].t);

		if(dan[e[i].t]) dp[u][1]++;
		else dp[u][0]++;
	}
	if(dp[u][1]+dp[u][0]==0){
		dan[u]=1;
	}
	else if(dp[u][1]>1){
			puts("First");
			exit(0);
	}
	else if(dp[u][1]==1){
		dan[u]=0;
	}
	else if(dp[u][1]==0){
		dan[u]=1;
	}
}

void dfs2(int u,int fa){
	if(dp[u][1]!=1){
	//	printf("dp(%d,1)=%d\n",u,1);
		puts("First");
		exit(0);
	}
	for(int i=h[u];~i;i=e[i].xt) if(e[i].t!=fa){
		int t[2];
		t[0]=dp[u][0]-(!dan[e[i].t]);
		t[1]=dp[u][1]-dan[e[i].t];
		if(t[1]+t[0]==0){
			dp[e[i].t][1]++;
		}
		else if(t[1]==1){
			dp[e[i].t][0]++;
		}
		else if(t[1]==0){
			dp[e[i].t][1]++;
		}
		dfs2(e[i].t,u);	
	}
}

int main(){
	memset(h,cnt=-1,sizeof(h));
	int n;
	scanf("%d",&n);
	for(int i=1;i<n;i++){
		int a,b;
		scanf("%d%d",&a,&b);
		adge(a,b);
		adge(b,a);
	}
	dfs1(1,1);

//	for(int i=1;i<=n;i++) printf("dp(%d)= %d %d\n",i,dp[i][1],dp[i][0]);cout<<endl;

	dfs2(1,1);

//	for(int i=1;i<=n;i++)  printf("dp(%d)= %d %d\n",i,dp[i][1],dp[i][0]);cout<<endl;

	puts("Second");
	return 0;
}

