#define SIZE 100010

vector<int> way[SIZE];

pair<int,int> dfs(int now, int back=-1){
  int t = 0;
  int s = 0;

  for(int i=0;i<way[now].size();i++){
    if(way[now][i] == back) continue;
    pair<int,int> p = dfs(way[now][i],now);

    t += p.first;
    s += p.second;    
  }

  //(0,1) => (1,0) , (1,1) => (0,1) , (1,0) => (0,0), (0,0) => (1,0)
  if(s <= 1 && t <= 1){
    return {1-t, s};
  }

  //(2,0) => (1,1)
  if(s == 0 && t == 2){
    return {0,1};
  }

  return {INF,INF};
}

