int main(const int argc, char * argv [])
{
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  size_t n;
  cin >> n;
  vector<vector<size_t>> adj(n);
  vector<size_t> deg(n);

  for(size_t i = 0, u, v; i + 1 < n; ++i)
  {
    cin >> u >> v;
    --u; --v;
    adj[u].push_back(v);
    adj[v].push_back(u);
    ++ deg[v];
    ++ deg[u];
  }

  if(n == 2)
  {
    cout << "Second";
    return 0;
  }

  vector<size_t> cnt(n);  // number of leaves connected
  vector<bool> tag(n, false);  // removed nodes!
  vector<bool> w(n, false);

  for(size_t i = 0; i < n; ++i)
    if(deg[i] == 1)
    {
      tag[i] = true;
      if(1 < ++ cnt[adj[i].front()])
      {
        cout << "First";
        return 0;
      }
    }

  // paint all nodes connected to only one leaf white
  // and remove them
  vector<size_t> idx;

  for(size_t i = 0; i < n; ++ i)
    if(cnt[i] == 1)
      idx.push_back(i);

  while(!idx.empty())
  {
    for(const auto u: idx) // color them white
    {
      tag[u] = true;
      w[u] = true;
    }

    for(const auto u: idx)
      for(const auto i: adj[u])
      {
        if(1 < ++ cnt[i] && !tag[i])
        {
          cout << "First";
          return 0;
        }
      }

    vector<size_t> buf;

    for(const auto u: idx)
      for(const auto i: adj[u])
        if(!tag[i] && cnt[i] == 1)
          buf.push_back(i);

    sort(begin(buf), end(buf));
    buf.erase(unique(begin(buf), end(buf)), end(buf));
    idx.swap(buf);
  }

  for(size_t u = 0; u < n; ++u)
  {
    bool all = w[u];
    for(const auto i: adj[u])
      all = all && w[i];

    if(all)
    {
      cout << "First";
      return 0;
    }
  }

  cout << "Second";

  return EXIT_SUCCESS;
}

