int main() {
    int n; cin >> n;
    vector<vector<int>> g(n);
    vector<int> deg(n);
    for(int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
        deg[a] += 1;
        deg[b] += 1;
    }

    vector<int> bque, wque;
    for(int i = 0; i < n; ++i) {
        bool check = false;
        for(auto to : g[i]) {
            check |= g[to].size() == 1u;
        }
        if(check) {
            wque.push_back(i);
        }
    }

    bool ans = false;
    vector<bool> used(n);
    vector<int> wdeg(n);
    for(int i = 0; i < (n + 1) / 2; ++i) {
        if(!bque.empty()) {
            ans = true;
            break;
        }
        if(wque.empty()) break;
        const int v = wque.back();
        wque.pop_back();
        used[v] = true;
        for(auto to : g[v]) {
            if(used[to]) continue;
            wdeg[to] += 1;
            if(wdeg[to] == deg[to]) {
                bque.push_back(to);
            }
            if(wdeg[to] + 1 == deg[to]) {
                for(auto to2 : g[to]) {
                    if(used[to2]) continue;
                    wque.push_back(to2);
                }
            }
        }

        // second turn
        if(!bque.empty()) {
            const int b = bque.back();
            bque.pop_back();
            used[b] = true;
        }
    }

    cout << (ans ? "First" : "Second") << endl;
}

