    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  std::vector<bool> matching(n,false);

  auto f=[&](auto f,ll now,ll par)->void{
    for(ll e:graph[now]){
      if(e==par)continue;
      directed[now].push_back(e);
      f(f,e,now);
    }
  };

  f(f,0,-1);

  std::vector<ll> topo=topo_sort(directed);

  for(ll i=n-1;i>=0;i--){
    ll now=topo[i];
    for(ll next:directed[now]){
      if(!matching[next]){
        matching[now]=true;
