    D[0] = 0b01; Stk.push(0);
    while(not Stk.empty()){
        const unsigned int v = Stk.top(); Stk.pop();
        const char t = 0b11 ^ D[v];
        for(const unsigned int u : e[v]){
            if(D[u] == 0b11){ D[u] = t; Stk.push(u); continue; }
            if(D[u] != t) return false;
        }
    }
    unsigned int cnt = 0;
    for(unsigned int i = 0; i < n; ++i) if(D[i] == 0b01) ++cnt;
    return (cnt << 1) == n;
}

