void dfs(int v, int par)
{
	mark[v] = true;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (!mark[u])
		{
			dfs(u, v);
		}
	}
	if (deg[v] == 1)
	{
		dp[v][0] = true;
		dp[v][1] = false;
		return;
	}
	dp[v][0] = true;
	vector<int> vec;
	for (int i = 0; i < graph[v].size(); i++)
	{	
		int u = graph[v][i];
		if (u != par)
		{
			dp[v][0] = dp[v][0] & dp[u][1];
		}
		if (dp[u][1] == false && u != par)
		{
			vec.push_back(u);
		}
	}
	if (vec.size() > 1)
	{
		dp[v][1] = false;
		return;
	}
	if (vec.size() == 1)
	{
		if (dp[vec[0]][0])
		{
			dp[v][1] = true;
		}
		else
		{
			dp[v][1] = false;
		}
		return;
	}
	dp[v][1] = false;
	if (!vec.size())
	{
		for (int i = 0; i < graph[v].size(); i++)
		{
			int u = graph[v][i];
			if (dp[u][0])
			{
				dp[v][1] = true;
			}
		}
	}
}

