void make_normal(ll vsize, bool hascost, ll costmax){
	std::random_device rand_device;
	std::mt19937 mt(rand_device());
	std::uniform_int_distribution<ll> rand(0, vsize-1);
	ll root = rand(mt);

	vector<pair<ll,ll>> a;
	vector<ll> selected(vsize,0);
	selected[root]=1;

	for(ll nokori=vsize-1; nokori>0; nokori--){
		std::uniform_int_distribution<ll> rand1(1, nokori);
		std::uniform_int_distribution<ll> rand2(1, vsize-nokori);
		ll r[2];
		r[0] = rand1(mt);
		r[1] = rand2(mt);
		ll vt[2];
		for(ll i=0;i<2;i++){
			ll c=0;
			for(ll j=0;c<r[i];j++){
				if(selected[j]==i)c++;
				if(r[i]==c){
					vt[i]=j;
					break;
				}
			}
		}

		selected[vt[0]]=1;
		a.push_back({vt[0],vt[1]});
	}
	shuffle(a);

	std::uniform_int_distribution<ll> rand0(0, 1);
	std::uniform_int_distribution<ll> costrand(1, costmax);
	cout << vsize << endl;
	dosomething(vsize, vsize-1);
	for(pair<ll,ll> v:a){
		if(rand0(mt))swap(v.first,v.second);
		if(hascost) cout << 1+v.first << ' ' << 1+v.second << ' ' << costrand(mt) << endl;
		else cout << 1+v.first << ' ' << 1+v.second << endl;
	}
}


