int n;
vector<vector<int>> g;

void solve() {
	cin >> n;
    g.assign(n, vector<int>());
    vector<int> deg(n, 0);
    vector<bool> seen(n, 0);
    rep(i, n - 1) {
        int a, b; cin >> a >> b;
        -- a, -- b;
        g[a].pb(b);
        g[b].pb(a);
        deg[a] ++, deg[b] ++;
    }
    bool res = 1;
    queue<int> que;
    rep(i, n) if(deg[i] == 1) que.push(i);
    while(!que.empty()) {
        int v = que.front(); que.pop();
        if(seen[v]) continue;
        seen[v] = 1;

        int k = -1;
        for(int nv: g[v]) if(!seen[nv]) k = nv;
        if(k == -1) {
            res = 0;
            break;
        }
        seen[k] = 1;
        for(int j: g[k]) {
            if(seen[j]) continue;
            deg[j] --;
            if(deg[j] == 1) que.push(j);
        }
    }
    cout << (res ? "Second" : "First") << endl;
}

