int dfs(int v,int p){
	if (v==N){
		return 1;
	}
	if (dp[v]!=-1){
		return dp[v];
	}
	if (leaf.find(v)!=leaf.end()){
		return dp[v]=0;
	}
	int c=0;
	REP(i,(int)G[v].size()){
		if (G[v][i]!=p){
			if (!dfs(G[v][i],v)){
				c++;
			}
		}
	}
	if (c>=2 || c==0){
		return dp[v]=0;
	}
	int flg=1;
	REP(i,(int)G[v].size()){
		if (G[v][i]!=p){
			if (!dp[G[v][i]]){
				int v2=G[v][i];
				REP(j,(int)G[v2].size()){
					if (G[v2][j]!=v){
						if (!dfs(G[v2][j],v2)){
							flg=0;
						}
					}
				}
			}
		}
	}
	return dp[v]=flg;
}

