ll dfs(vector<vector<ll>> &g, ll v, ll p) {
	if(g[v].size()==1)return 1;

	ll odd=0;
	ll even=0;
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		ll s=dfs(g, nextv, v);
		if(s%2)odd++;
		else even++;
	}

	if(odd>1){
		cout<<"First"<<endl;exit(0);
	}else if(even>2 && odd==0){
		cout<<"First"<<endl;exit(0);
	}
	return (odd+1)%2;

}

