void dfs(int v, int p)
{
	int s = 0;
	int c = 0;
	int codd = 0;
	int ceven = 0;
	bool only_path = 1;

	for (int to : g[v]) {
		if (to != p) {
			dfs(to, v);

			if (st[to] == 0) {
				++codd;
			} else if (st[to] == 1) {
				++ceven;
			} else {
				only_path = 0;
			}

			if (c) {
				s = -1;
			} else {
				if (st[to] == -1) {
					s = -1;
				} else {
					s = (st[to] ^ 1);
				}
			}

			++c;
		}
	}

	st[v] = s;

	if (codd >= 2 || (onlypath && ceven > 0 && codd == 0)) {
		ok = 1;
	}
	//cout<<v<<" " << st[v] << endl;
}

