int N, M;
int Sum[100005], Leaf[100005];
vector <int> G[100005];
queue <int> Q, Q2;
bool Use[100005];
int Grade[100005];
void Read()
{
    cin >> N;
    for(int i = 1; i <= N - 1; i++)
    {
        int a, b;
        cin >> a >> b;
        ++Grade[a];
        ++Grade[b];
        G[a].push_back(b);
        G[b].push_back(a);
    }
    //int cnt = 0;
    for(int i = 1; i <= N; i++)
        if(G[i].size() == 1)
        {
            Q.push(i);

        }
    int cnt = 0;
    while(cnt < N)
    {
        while(!Q.empty())
        {
        int node = Q.front();
        ++cnt;
        Q.pop();
        if(Grade[node] == 0)
            continue;
        Use[node] = 1;
        while(G[node].size() > 0 && Use[G[node].back()] == 1)
            G[node].pop_back();
        int neighb = G[node].back();
        --Grade[neighb];
        Sum[neighb]++;
        if(Sum[neighb] >= 2)
        {
            cout << "First\n";
            return;
        }
        if(Grade[neighb] == 1)
            Q2.push(neighb);

        }
        while(!Q2.empty())
        {
            int node = Q2.front();
            ++cnt;
            Q2.pop();
            Use[node] = 1;
             while(G[node].size() > 0 && Use[G[node].back()] == 1)
            G[node].pop_back();
        int neighb = G[node].back();
        --Grade[neighb];
        if(Grade[neighb] == 1)
            Q.push(neighb);
        }
    }

    cout << "Second\n";
}
