bool mark[N];

void dfs(int v)
{
	mark[v] = true;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (deg[u] == 1)
		{
			dp[v]++;
		}
		if (!mark[u])
		{
			dfs(u);
		}
	}
	if (deg[v] == 1)
	{
		leaf[v] = 1;
	}
	dp2[v] = 1;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		leaf[v] += leaf[u];
		dp2[v] += dp2[u];
	}

}

