	sz[u] = 1;
	for(auto v : vec[u]){
		if(v == fa) continue;
		f[v] = u;
		dep[v] = dep[u] + 1;
		dfs(v, u);
		sz[u] += sz[v];
		if(sz[v] == 1){
			lfson[u] ++;
			pq.push(v);
		}
	}
}

