    for(int i = 1; i < n; i++){
        int x = read(), y = read();
        add(x, y); add(y, x);
        deg[x]++; deg[y]++;
    } 
    for(int i = 1; i <= n; i++) {
        if(deg[i] == 1) Q.push(i); 
    }
    while(!Q.empty()){
        int x = Q.front(); Q.pop(); vis[x] = 1;
        for(int i = fi[x]; i; i = nt[i]){
            int v = go[i];  if(vis[v]) continue; 
            vis[v] = 1; deg[v]--; 
