        if(g[i].size() == 1)
            continue;
        ll con = 0;
        for(auto e : g[i]) {
            if(g[e.to].size() == 1)
                con++;
        }
        if(con >= 2) {
            cout << "First" << en;
            return;
        }
    }
    cout << "Second" << en;
}

