void solve(){
	queue<int>q;
	for(int i=0;i<n;i++){
		cnt[i]=v[i].size();
		if(cnt[i]==1){
			q.push(i);
			chi[v[i][0]]++;
		}
	}
	for(int i=0;i<n;i++){
		if(chi[i]>=2){
			cout<<"First"<<endl;
			return;
		}
	}
	while(!q.empty()){
		int p=q.front();
		q.pop();
