			return;
		}
		if(cnt[p]==0){
			cout<<"First"<<endl;
			return;
		}
		vis[p]=2;
		cnt[p]--;
		c--;
		for(int u:v[p]){
			if(vis[u]==1){
				cout<<"First"<<endl;
				return;
			}
			if(vis[u])continue;
			vis[u]=1;
			cnt[u]--;
			c--;
			if(cnt[u]==1){
				for(int l:v[u]){
					if(!vis[l]){
						q.push(l);
					}
				}
			}
		}
	}
	for(int i=0;i<n;i++){
		if(vis[i]==2){
			for(int u:v[i]){
				if(vis[u]==1)vis[u]=3;
			}
		}
	}
	for(int i=0;i<n;i++){
		if(vis[i]==1){
			cout<<"First"<<endl;
			return;
		}
	}
	cout<<"Second"<<endl;
	return;
}

