using namespace std;

class Tree {
    public:
        vector<int> edges;
        bool isLeaf() { return edges.size() == 1; }
        bool isBrunch() { return edges.size() == 2; }
        int brunchNextNode(int exept) {
            if (!isBrunch()) { return -1;}
            return edges[0] != exept ? edges[0] : edges[1];
        }
        void setEdge(int n) { edges.push_back(n); }
};

int main() {
    int N; cin >> N;
    vector<Tree> nodes(N+1);

    int a, b;
    for (int i=0; i<N-1; i++) {
        cin >> a >> b;
        nodes[a].setEdge(b);
        nodes[b].setEdge(a);
    }

    for (int i=1; i<=N; i++) {
        int tmp = 0;
        for (int j : nodes[i].edges) {
            if (nodes[j].isLeaf()) {
                tmp += 1;
            } else if (nodes[j].isBrunch()) {
                while (nodes[j].isBrunch()) {
                    int k = nodes[j].brunchNextNode(i);
                    j = nodes[k].brunchNextNode(j);

                    if (j == -1) {
                        break;
                    }
                    if (nodes[j].isLeaf()) {
                        tmp += 1;
                        break;
                    }
                }

            }
        }
        if (tmp >= 2) {
            cout << "First" << endl;
            return 0;
        }
    }

    cout << "Second" << endl;
    return 0;
}

