vector<int> edges[111111];

map<pair<int,int>,bool> hashed;

bool GetBool(int nc,int ne) {
    bool retval=false;
    if (ne == 0)
        retval=true;
    else
        retval |= (nc>=2);
    return retval;
}

int ncs[111111];

bool CanWin(int par, int u) {

    if (hashed.find(make_pair(par,u)) != hashed.end())
        return hashed[make_pair(par,u)];

    if (ncs[u]!=-1 && hashed.find(make_pair(u,par)) != hashed.end())
        return GetBool(ncs[u]-hashed[make_pair(u,par)], edges[u].size()-1);


    int nc=0;
    int ne=0;
    for(int j=0;j<edges[u].size();j++) {
        int v=edges[u][j];
        if (v == par)
            continue;
        ne++;
        nc += CanWin(u,v);
    }

    if (par == -1)
        ncs[u]=nc;

    return hashed[make_pair(par,u)]=GetBool(nc,ne);


}


int main() {
