        edges[v].push_back(u);
    }

    vector<pair<int,int> > deg_verts;
    for(int i=1;i<=N;i++) {
        deg_verts.push_back(make_pair(edges[i].size(),i));
        ncs[i]=-1;
    }

    sort(deg_verts.begin(),deg_verts.end());

    bool can=false;
    for(int j=deg_verts.size()-1;j>=0;j--) {
        int u=deg_verts[j].second;
