int main() {
	cin >> N;
	REP(i, N - 1) {
		int a, b;
		scanf("%d %d", &a, &b);
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	bool ans = false;
	queue<int> que;
	REP(i, N) if (g[i].size() == 1) {
		que.push(i);
		root[i] = true;
	}

	while (!que.empty()) {
		int u = que.front(); que.pop();
		if (cut[u]) continue;

		int next = -1;
		REP(i, g[u].size()) {
			int v = g[u][i];
			if (cut[v]) continue;
			next = v;
		}
		if (next == -1) continue;

		u = next;
		int cnt = 0;

		REP(i, g[u].size()) {
			int v = g[u][i];
			if (cut[v]) continue;

			if (root[v]) {
				cut[v] = true;
				cnt++;
			}
			else {
				int c = 0;
				REP(j, g[v].size()) {
					int p = g[v][j];
					if (p == v || cut[p]) continue;
					c++;
				}
				if (c < 2) {
					root[v] = true;
					que.push(v);
				}
			}
		}
		if (cnt >= 2) ans = true;
		cut[u] = true;
	}

	puts(ans ? "First" : "Second");
	return 0;
