	if(sz(e[u]) == 1) l[u] = 1;
	int cnt = 0;
	rep(i, 0, sz(e[u])){
		int to = e[u][i];
		if(to == p) continue;
		cnt += dfs(to, u);
	}
	if(cnt > 1) print(F);
	return l[u];
}

void dfs2(int u, int p){
	if(l[u]){
		return;
	}
	int cntOne = 0;
	int cntTwo = 0;
	int cntL = 0;
	rep(i, 0, sz(e[u])){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs2(to, u);
		if(l[to]){
			++cntL;
		}else if(d[to] == 1){
			++cntOne;
		}else if(d[to] == 2){
			++cntTwo;
		}
	}
	if(cntTwo > 1) print(F);
	if(cntTwo > 0){
		if(cntL > 0){
