struct Node {
	std::vector<int> edgeTo;
	int deadEndNum = 0;
};

int main() {
	int n;
	std::cin >> n;

	std::vector<Node> nodes(n);

	for (int i = 0; i < n - 1; ++i) {
		int a, b;
		std::cin >> a >> b;
		--a, --b;

		nodes[a].edgeTo.push_back(b);
		nodes[b].edgeTo.push_back(a);
	}

	for (auto&& node : nodes)
		if (node.edgeTo.size() == 1)
			++nodes[node.edgeTo.front()].deadEndNum;

	for (int i = 0; i < n; ++i) {
		if (nodes[i].deadEndNum >= 2) {
			std::cout << "First" << std::endl;
			return 0;
		}

		if (nodes[i].edgeTo.size() == 1) {
			int prevD = i;
			int d = nodes[i].edgeTo.front();

			for (int j = 0; j < 2; ++j) {
				const auto& to = nodes[d].edgeTo;

				if (to.size() == 2) {
					int tmp = prevD;
					prevD = d;
					d = (to[0] == tmp ? to[1] : to[0]);
				}
				else {
					d = -1;
					break;
				}
			}
			if (d != -1 && nodes[d].edgeTo.size() >= 2) {
				std::cout << "First" << std::endl;
				return 0;
			}
		}
	}

	std::cout << "Second" << std::endl;
}

