inline bool kek(int x, int pr) {
    if (used[x]) {
        return keks[x];
    }
    used[x] = 1;
    bool ok = 0;
    int cnt = 0;
    for (auto h: v[x]) {
        if (h == pr) {
            continue;
        }
        if (sz(v[h]) == 1) {
            ok = 1;
        } else {
            if (!kek(h, x)) {
                cnt++;
                break;
            }
        }
    }
    keks[x] = ok && (cnt == 0);
    return keks[x];
}


