namespace TreeMatching{
    vector<vector<int>> g;
    vector<bool> matched;

    bool dfs(int cur,int pre){
        if(g[cur].size()==1 && pre!=-1){
            if(matched[pre]) return false;
            else{
                matched[pre] = matched[cur] = true;
                return true;
            }
        }

        for(int v : g[cur]) if(v != pre){
            if(!dfs(v,cur)) return false;
        }

        if(!matched[cur]){
            if(pre==-1 or matched[pre]) return false;
            else{
                matched[cur] = matched[pre] = true;
                return true;
            }
        }
        return true;
    }

    bool isPerfectMatching(const vector<vector<int>>& g_,int root=0){
        g = g_;
        matched = vector<bool>(g_.size());
        if(dfs(root,-1)){
            return true;
        }else{
            return false;
        }
    }
