const int N = 1e5 + 10;

vi g[N];
bool rem[N], cool[N];
int cnt[N];

void dfs(int v, int par) {
    cool[v] = true;
    cnt[v] = 1;
    rem[v] = false;

    for (int to : g[v]) {
        if (to == par)
            continue;
        dfs(to, v);
        cnt[v] += cnt[to];
        cool[v] &= rem[to];
        rem[v] |= cool[to];
    }
    if (!(cnt[v] & 1)) {
        rem[v] = true;
    }
}

int n;
void dfs2(int v, int par, bool up_cool, int up_rem) {
    int cnt_cool = up_cool;
    int cnt_notrem = !up_rem;
    for (int to : g[v]) {
        if (to == par)
            continue;
        cnt_cool += cool[to];
        cnt_notrem += !rem[to];
    }
    if (!cnt_notrem) {
        cout << "First";
//        watch(v);
        exit(0);
    }
    for (int to : g[v]) {
        if (to == par)
            continue;
        cnt_cool -= cool[to];
        cnt_notrem -= !rem[to];
        bool cl = cnt_notrem == 0;
        bool rm = cnt_cool || !((n - cnt[to]) & 1);
        dfs2(to, v, cl, rm);
        cnt_cool += cool[to];
        cnt_notrem += !rem[to];
    }
}

