		int N;cin >> N;
		Graph<ll> g(N);
		for(int i:range(N-1)){
			int a,b;cin >> a >> b;a--;b--;
			g[a].push_back({b,1});
			g[b].push_back({a,1});
		}

		vector<vector<int>> ps(N,vector<int>(2));
		vector<bool> passed(N);
		queue<int> que;
		for(int i:range(N))if(g[i].size()==1){
			ps[i][0] = 1,ps[i][1] = 0;
			passed[i] = true;
			que.push(i);
		}

		vector<int> inc(N);
		while(!que.empty()){
			int i = que.front();que.pop();
			for(auto e:g[i])if(!passed[e.to]){
				ps[e.to][1] += ps[i][0], ps[e.to][0] += ps[i][1];
				inc[e.to]++;
				if(inc[e.to] == g[e.to].size()-1){
					passed[e.to] = true;
					que.push(e.to);
				}
			}
		}
		// cerr << ps << endl;

		bool ok = false;
		for(int i:range(N))if(ps[i][1] >=2){
			ok = true;
		}
		if(ok){
			cout << "First" << endl;
		}else{
			cout << "Second" << endl;
		}
	}
};

