        void setEdge(int n) { edges.push_back(n); }
};

int main() {
    int N; cin >> N;
    vector<Tree> nodes(N+1);

    int a, b;
    for (int i=0; i<N-1; i++) {
        cin >> a >> b;
        nodes[a].setEdge(b);
        nodes[b].setEdge(a);
    }

    for (int i=0; i<N; i++) {
        int tmp = 0;
        for (int j : nodes[i].edges) {
            tmp += nodes[j].isLeaf() ? 1 : 0;
        }
        if (tmp >= 2) {
            cout << "First" << endl;
            return 0;
        }

        tmp = 0;
        if (nodes[i].edges.size() == 2) {
            for (int j : nodes[i].edges) {
                for (int k : nodes[j].edges) {
                    tmp += nodes[k].isLeaf() ? 1 : 0;
                }
            }
        }
        if (tmp >= 2) {
            cout << "First" << endl;
            return 0;
        }
    }

    cout << "Second" << endl;
    return 0;
}

