	reverse(b.begin(),b.end());
	for (int i=0;i<a.length();i++){
		for (int j=0;j<b.length();j++){
			res[i+j]+=(a[i]-'0')*(b[j]-'0');
		}
	}
	for (int i=0;i<Maxk;i++){
		if (res[i]>=10) {
			res[i+1]+=(res[i]/10);
			res[i]%=10;
		}
	}
	string ret;
	bool flag=false;
	for (int i=Maxk-1;i>=0;i--){
		if (flag || res[i]){
			flag=true;
			ret=ret+(char)(res[i]+'0');
		}
	}
	if (ret=="") ret="0";
	return ret;
}
string add(string a,string b){
	if (a.length()<b.length()) swap(a,b);
	while (a.length()!=b.length()){
		b='0'+b;
	}
	for (int i=a.length()-1;i>=0;i--){
		a[i]+=(b[i]-'0');
		if (a[i]>'9' && i){
			a[i]-=10;
			a[i-1]++;
		}
	}
	if (a[0]>'9'){
		a[0]-=10;
		a='1'+a;
	}
	return a;
}
const int Maxn=200005;
int deg[Maxn];
vector<int> G[Maxn];
bool canpick(int pa,int u){
	for (int i=0;i<G[u].size();i++){
		if (G[u][i]==pa) continue;
		if (deg[G[u][i]]==1){
			return true;
		}
	}
	bool ans=true;
	for (int i=0;i<G[u].size();i++){
		if (G[u][i]==pa) continue;
		int v=G[u][i];
		for (int j=0;j<G[v].size();j++){
			if (G[v][i]==u) continue;
			ans|=canpick(v,G[v][i]);
		}
	}
	return ans;
}
