		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	for (int i = 1; i <= N; i++) {
		que_t.push(P(tree[i].size(), i));
		que_a.push(P(tree[i].size(), i));
	}

	bool takahashi = true;
	int count = 0;
	while (!que_t.empty() && !que_a.empty()) {
		if (takahashi) {
			while (!que_t.empty() && color[que_t.top().second] != 0) {
				que_t.pop();
			}
			int ii = que_t.top().second; que_t.pop();
			color[ii] = 1;
		}
		else {
