				que_a.pop();
			}
			int ii = que_a.top().second; que_a.pop();
			color[ii] = -1;
		}

		takahashi = !takahashi;
		if (++count >= N) break;
	}

	if (win_takahashi())
		cout << "First" << endl;
	else
		cout << "Second" << endl;

}

