int N;
int root;
vector<int> G[100005];
bool A[100005];
bool B[100005];
bool ans=false;

void solve(int pos,int prev){
  if(prev!=-1 && G[pos].size() == 1){
    B[pos]=true;
    return;
  }

  int a=0,b=0;
  for(int to:G[pos]){
    if(to==prev)continue;
    solve(to,pos);
    if(A[to])a++;
    if(B[to])b++;
  }

  if(b>1)ans=true;
  if(b>0)A[pos]=true;
  if(b>1)B[pos]=true;
}

