  cin>>N;
  for(int i=0;i<N-1;i++){
    int a,b;
    cin>>a>>b;
    a--,b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  if(N==2){
    cout<<"Second"<<endl;
    return 0;
  }
  for(int i=0;i<N;i++)
    if(G[i].size()>1)root=i;
  solve(root,-1);
  cout<< ( ans ? "First":"Second" ) <<endl;
  return 0;
}

