// 1 = even
// 2 = odd

int calc(int u, int v) {
    if (parity[u].count(v))
        return parity[u][v];
    if (adj[v].size() == 1)
        return parity[u][v] = 1;

    int cnt1 = 0, cnt2 = 0;
    for (int w : adj[v]) {
        if (w == u)
            continue;
        int p = calc(v, w);
        if (p == 1)
            cnt1++;
        if (p == 2)
            cnt2++;
    }
    if (cnt1 >= 2) {
        cout << "First" << endl;
        exit(0);
    }
    if (cnt1 == 0)
        return parity[u][v] = 1;
    return parity[u][v] = 2;
}

