#include<bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
bool dp[N][2][2], L[N][2], R[N][2];
int n, par[N], deg[N];
vector<int> adj[N];

void dfs1(int u) {
	for (auto v: adj[u])
		if (v ^ par[u]) {
			deg[par[v] = u]++, dfs1(v);
			for (int i = 0; i < 2; i++)
				dp[u][0][i] &= dp[v][0][!i];
		}
	if (!deg[u])
		dp[u][0][0] = dp[u][0][1] = true;
}

void dfs2(int u) {
	for (int i = 0; i <= deg[u]; i++)
		for (int j = 0; j < 2; j++)
			L[i][j] = R[i][j] = true;
	for (int i = 0; i <= deg[u]; i++)
		for (int j = 0; j < 2; j++)
			if (adj[u][i] ^ par[u])
				L[i + 1][j] = (L[i][j] && dp[adj[u][i]][0][!j]);
	for (int i = deg[u]; ~i; i--)
		for (int j = 0; j < 2; j++)
			if (adj[u][i] ^ par[u])
				R[i - 1][j] = (R[i][j] && dp[adj[u][i]][0][!j]);
	for (int i = 0; i <= deg[u]; i++)
		if (adj[u][i] ^ par[u])
			for (int j = 0; j < 2; j++)
				dp[adj[u][i]][1][j] = (L[i][!j] && R[i][!j] && dp[u][1][!j]);
	for (auto v: adj[u])
		if (v ^ par[u])
			dfs2(v);
}

