		bool ok = dp[u][1][0];
		for (auto v: adj[u])
			if (v ^ par[u])
				ok &= dp[u][0][1];
		if (ok) {
			cout << "First\n";
			exit(0);
		}
	}
	cout << "Second\n";
}

