void add_edge(int u, int v){
    G[u].pb(v); G[v].pb(u);
}

bool dfs(int v){
    used[v]=true;
    for(int &to : G[v]){
        int w=match[to];
        if(w<0||!used[w]&&dfs(w)){
            match[v]=to;
            match[to]=v;
            return true;
        }
    }
    return false;
}

int bipartite_matching(){
    int res=0;
    memset(match, -1, sizeof(match));
    rep(v,0,V){
        if(match[v]<0){
            memset(used, 0, sizeof(used));
            if(dfs(v)){
                res++;
            }
        }
    }
    return res;
}
