#include <bits/stdc++.h>

using namespace std;

vector<int> g[100005];
bool dp[100005]={}; 
int sz[100005]={};

void pre(int u, int par){
	sz[u]=1;
	int c;
	for(auto v:g[u]){
		if(v!=par){
			pre(v,u);
			sz[u]+=sz[v];
			c=v;
		}
	}
	if(g[u].size()==1){
		dp[u]=1;
	}
	if(g[u].size()==2){
		dp[u]=dp[c];
	}
}

void dfs(int u, int par, int up, int upsz){
	int paths=0;
	int ind=0;
	for(auto v:g[u]){
		if(v!=par){
			if(par)
				dfs(v,u,(up&&(g[u].size()==2)),upsz+1);

			else
				dfs(v,u,(g[u].size()==2)&&dp[g[u][1-ind]],
						sz[g[u][1-ind]]+1);
			paths+=dp[v]&&(sz[v]&1);
			ind=1-ind;
		}
	}
	paths+=up&&(upsz&1);

	if(paths>=2){
		cout << "First" << endl;
		exit(0);
	}
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;
	for(int i=0;i<n-1;i++){
		int u,v; cin >> u >> v;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	if(n==2){
		cout << "Second" << endl;
		return 0;
	}
	int root;
	for(int i=1;i<=n;i++){
		if(g[i].size()>1){
			root=i;
			break;
		}
	}

	pre(root,0);
	dfs(root,0,1,0);

	cout << "Second" << endl;
	return 0;
}

