#define INF 123456789

vector<int> vec[100000];
int memo[100000];

int dfs(int d, int from){
  int ret = 0;
  for(auto to : vec[d]) if(to!=from){
    ret = dfs(to, d);
  }
  if(vec[d].size()==1) return memo[d]=1;
  if(vec[d].size()==2) return memo[d]=ret+1;
  else return INF;
}

bool solve(){
  int n;
  cin>>n;
  rep(i,n-1){
    int a,b;
    cin>>a>>b;
    a--;b--;
    vec[a].pb(b);
    vec[b].pb(a);
  }

  fill(memo, memo+100000, INF);
  int from=0;
  rep(i,n) if(vec[i].size()==1){
    from=i;
    break;
  }
  memo[from]=1;
  int to=vec[from][0];
  while(vec[to].size()==2){
    memo[to] = memo[from]+1;
    rep(i,2) if(vec[to][i]!=from){
      from = to;
      to = vec[to][i];
    }
  }

  if(vec[to].size()==1){
    if(memo[from]%2==1) return false;
    else return true;
  }

  dfs(to,from);

  rep(i,n){
    int cnt=0;
    for(auto d : vec[i]) if(memo[d]<INF && memo[d]%2==1) cnt++;
    if(cnt>1) return true;
  }
  return false;
}

int main(){
  if(solve()) cout << "First" << endl;
  else cout << "Second" << endl;
  return 0;
}

