void dfs(ll cur, ll pre, const VV<ll> &edges, V<ll> &pars) {
    pars[cur] = pre;
    for(ll nxt : edges[cur]) if(nxt != pre) dfs(nxt, cur, edges, pars);
}

bool solve() {
    ll N;
    cin >> N;
    VV<ll> edges(N);
    V<ll> digits(N);
    for(ll i = 0; i < N - 1; i++) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
        digits[a]++;
        digits[b]++;
    }

    V<ll> parents(N);
    for(ll i = 0; i < N; i++) if(digits[i] != 1) {
        dfs(i, -1, edges, parents);
        break;
    }

    set<ll> leaves;
    for(ll i = 0; i < N; i++) if(digits[i] == 1) leaves.insert(i);
    V<ll> cnts(N);

    while(leaves.size()) {
        set<ll> st;
        for(ll leaf : leaves) {
            ll par = parents[leaf];
            if(par == -1) continue;
            cnts[par]++;
            if(2 <= cnts[par]) return true;
            st.insert(par);
        }
        leaves.clear();
        for(auto &&ele : st) {
            ll par = parents[ele];
            if(par != -1) leaves.insert(par);
        }
    }

    return false;
}

int main() {
    cout << (solve() ? "First" : "Second") << endl;
    return 0;
}

