int WhoWin(){
  vector<int> judge(N, kWhite);

  for(int i=0; i<N; i++){
	if(nodes[i].color == kBlack){
	  judge[i] = kBlack;
	  for(auto s : nodes[i].next){
		judge[s] = kBlack;
	  }
	}
  }

  for(int i=0; i<N; i++){
	if(judge[i] == kWhite){
	  return kWhite;
	}
  }
  return kBlack;
}

int OrSearch(int turn){
  if(turn == N){
	return WhoWin();
  }

  for(int i=0; i<N; i++){
	if(nodes[i].color == kBlank){
	  nodes[i].color = kWhite;
	  int result = AndSearch(turn + 1);
	  nodes[i].color = kBlank;
	  if(result == kWhite){
		return kWhite;
	  }
	}
  }
  return kBlack;
}

