bool solve() {
    ll N;
    cin >> N;
    VV<ll> edges(N);
    for(ll i = 1; i < N; i++) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    bool leaves[N] = {};
    for(ll i = 0; i < N; i++) if(edges[i].size() == 1) leaves[i] = true;

    for(ll i = 0; i < N; i++) {
        ll cnt = 0;
        for(ll nxt : edges[i]) if(leaves[nxt]) cnt++;
        if(2 <= cnt) return true;
    }

    return (N & 1);
}

