const int MR = 1e5 + 10;

vector < int > g[MR];

queue<int> q[2];	//q[0] - liscie, q[1] - rodzice

bool done[MR];

bool go(int N)
{
	REP(i, N)
		if (g[i].size() == 1)
		{
			q[0].push(i);
			done[i] = 1;
			if (done[g[i].front()])
				return 0;
			q[1].push(g[i].front());
			done[g[i].front()] = 1;
		}

	N -= q[0].size() + q[1].size();

	// wyczysc liscie
	while (!q[0].empty())
		q[0].pop();

	while (N)
	{
		// przetwarzaj rodzicow i wyznacz nowe liscie
		while (!q[1].empty())
		{
			int akt = q[1].front(); q[1].pop();
			for(auto v : g[akt])
				if (!done[v])
				{
					q[0].push(v);
					done[v] = 1;
					N--;
					break;
				}
		}

		int ileL = q[0].size();

		// wyznacz nowych rodzicow
		while (!q[0].empty())
		{
			int akt = q[0].front(); q[0].pop();
			for (auto v : g[akt])
				if (!done[v])
				{
					q[1].push(v);
					done[v] = 1;
					N--;
					break;
				}
		}

		if (q[1].size() < ileL)
			return 0;
	}

	return 1;
}

