	read(n);
	for(int i = 1, u, v; i < n; ++i) {
		read(u), read(v);
		ade(u, v), ade(v, u);
	}
	if(n == 2) return puts("Second"), 0;
	for(int i = 1; i <= n; ++i) 
	for(int i = 1; i <= n; ++i) {
		if(deg[i] == 1) continue;
		dfs(i);
		return puts("Second"), 0;
	}
	return 0;
}

