#include<bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
bool dp[N], up[N], child[N], L[N], R[N];
vector<int> adj[N];
int n, par[N];

inline void fill_dp(int u) {
	L[0] = R[adj[u].size() - 1] = true;
	for (int i = 0; i < adj[u].size(); i++)
		L[i + 1] = R[i - 1] = (adj[u][i] != par[u] && dp[adj[u][i]]);
	for (int i = 1; i < adj[u].size(); i++)
		L[i] &= L[i - 1], R[adj[u].size() - i - 1] &= R[adj[u].size() - i];
}

void dfs1(int u) {
	child[u] = true;
	for (auto v: adj[u])
		if (v ^ par[u]) {
			par[v] = u, dfs1(v);
			child[u] &= dp[v];
		}
	fill_dp(u);
	for (int i = 0; i < adj[u].size(); i++)
		dp[u] |= (adj[u][i] != par[u] && L[i] && R[i] && child[adj[u][i]]);
}

void dfs2(int u) {
	fill_dp(u);
	for (int i = 0; i < adj[u].size(); i++)
		if (adj[u][i] ^ par[u])
			up[adj[u][i]] = ((par[u] == u || up[par[u]]) && L[i] && R[i]);
	for (auto v: adj[u])
		if (v ^ par[u])
			dfs2(v);
}

inline void readInput() {
	cin >> n;
	for (int i = 1; i < n; i++) {
		int u, v;
		cin >> u >> v;

		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

inline void solve() {
	dfs1(0), dfs2(0);
	for (int i = 0; i < n; i++) {
		bool ok = (par[i] == i || up[par[i]]);
		for (auto u: adj[i])
			if (u ^ par[i])
				ok &= dp[u];
		if (ok) {
			cout << "First\n";
			exit(0);
		}
	}
	cout << "Second\n";
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	readInput(), solve();
	return 0;
}

