void who_win(int v, int p = -1, int depth = 1) {
    if (p != -1 && g[v].size() == 2 && depth == 2) {
        is_first = true;
    }
    is_leaf[v] = true;
    int cnt = 0;
    for (auto to : g[v]) {
        if (to != p) {
            is_leaf[v] = false;
            who_win(to, v, depth + 1);
            cnt += is_leaf[to];
        }
    }
    if (cnt > 1) {
