		return 0;
	}

	REP(i, N - 1)
	{
		int a, b;
		scanf("%d%d", &a, &b); a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	if (go(N))
		printf("Second\n");
	else
		printf("First\n");

	return 0;
}

