const int maxn = 1e5 + 55;//, mod = 1e9 + 7;
int n, p[maxn], rem[maxn], deg[maxn], h[maxn];
vi g[maxn], ord;
void dfs(int v, int pr = -1) {
	p[v] = pr;
	for(auto i : g[v])
		if(i!=pr) h[i] = h[v] + 1, dfs(i, v), deg[v]++;
	ord.pb(v);
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
