		cin >> f >> t;
		g[f].pb(t);
		g[t].pb(f);
	}
	int r = 0;
	for(int i = 1; i <= n; i++) if(g[i].size()==1) {dfs(i);r=i;break;};
	sort(all(ord), [&](const int &i, const int &j) {
		return h[i] > h[j];
	});
	int lft = 0;
	for(auto i : ord) {
		if(rem[i]) continue;
		if(deg[i] ==0 && deg[p[i]]==1) {
			rem[i] = rem[p[i]] = 1;
			p[p[i]]!=-1?deg[p[p[i]]]--:0;
		} else lft++;
	}
	lft += 1^rem[r];
	cout << (lft==0?"Second":"First");
}

