const int N = 1e5 + 10;
set<int> a[N];
bool leaf[N];
bool visit[N];

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x; --y;
    a[x].insert(y);
    a[y].insert(x);
  }
  vector<int> Q;
  for (int i = 0; i < n; ++i) {
    if (a[i].size() == 1) {
      Q.push_back(i);
      leaf[i] = true;
    }
  }
  bool found = false;
  while (!found && !Q.empty()) {
    set<int> nxt;
    for (auto& u : Q) {
      int v = *a[u].begin();
      if (nxt.find(v) == nxt.end()) {
        nxt.insert(v);
      } else {
        found = true;
        break;
      }
    }
    // trace(found);
    for (auto& u : nxt) {
      // trace(u);
      visit[u] = true;
    }
    Q.clear();
    for (auto& u : nxt) {
      for (auto& v : a[u]) {
        if (leaf[v] || visit[v]) continue;
        a[v].erase(u);
        if (a[v].size() == 1) {
          leaf[v] = true;
          Q.push_back(v);
        }
      }
    }
  }
  puts(found ? "First" : "Second");
  return 0;
}

