    REP(i,n-1){
        int u, v;
        scanf("%d %d", &u, &v);
        u--;
        v--;
        e[u].push_back(v);
        e[v].push_back(u);
    }

    int root = 0;
    REP(i,n) if (e[i].size() > 1) root = i;

    int s = dfs(root,-1);

    if (e[0].size() == 1){
        win = (s == 1);
    }else{
        win = (abs(s) == 1);
    }

    REP(i,n){
        int x = 0;
        for (auto nei : e[i]){
            if (e[nei].size() == 1) x++;
        }
        if (x >= 2) win = true;
    }

    // REP(i,n) cout << p[i] << endl;

    cout << (win ? "First" : "Second") << endl;

    return 0;
}

