class agcD {
private:
    void dfs(int u, int par, const vector<vector<int>>& g, vector<int>& fin) {
        for (int v : g[u]) {
            if (v != par && !fin[v]) {
                dfs(v, u, g, fin);
            }
        }

        for (int v : g[u]) {
            if (v != par && !fin[v]) {
                fin[v] = fin[u] = 1;
            }
        }
    }
public:
    void solve(istream& in, ostream& out) {
        int N;
        in >> N;
        vector<vector<int>> g(N);
        for (int i = 0; i + 1 < N; ++i) {
            int a, b;
            in >> a >> b;
            g[a-1].push_back(b-1);
            g[b-1].push_back(a-1);
        }

        vector<int> fin(N, 0);
        dfs(0, -1, g, fin);

        for (int u = 0; u < N; ++u) {
            if (!fin[u]) {
                out << "First\n";
                return;
            }
        }
        out << "Second\n";
    }
};


