void solve(int pos,int prev){
  if(prev!=-1 && G[pos].size() == 1){
    A[prev]=true;
    C[pos]=true;
    return;
  }

  int a=0,b=0,c=0;
  for(int to:G[pos]){
    if(to==prev)continue;
    solve(to,pos);
    if(A[to])a++;
    if(B[to])b++;
    if(C[to])c++;
  }
  if(c>1)ans=true;
  if(b>1)ans=true;
  if(b>0)A[pos]=true;
  if(b>1)B[pos]=true;
}

