	for (int i = 0; i < n - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		graph[u - 1].push_back(v - 1);
		graph[v - 1].push_back(u - 1);
		deg[u - 1]++;
		deg[v - 1]++;
	}
	int root = 0;
	for (int i = 0; i < n; i++)
	{
		if (deg[i] > 1)
		{
			root = i;
		}
	}
	dfs(root, -1);
	/*
	for (int i = 0; i < n; i++)
	{
		cout << dp[i][0] << " " << dp[i][1] << endl;
	}
	*/
	if (n == 2)
	{
		cout << "Second";
		exit(0);
	}
	if (dp[root][1])
	{
		cout << "Second";
	}
	else
	{
		cout << "First";
	}
}

