                node_info[to] = 1;
            }
        }
    }

    queue<int> q;
    REP(i,N){ 
        if(node_info[i]==0) q.push(i);
        if(node_info[i]==1) node_info[i]=-1;
    }

    bool win_2 = true;
    while(not q.empty()){
        int v = q.front(); q.pop();
        int binary_ = node_info[v] ^ 1;
        for(auto to:edge[v]){
            if(node_info[to]==-1){
                node_info[to] = binary_;
                q.push(to);
            }else{
                if(node_info[to]!=binary_){
                    win_2 = false;
                }
            }
        }
    }

    if(win_1 or win_2) cout << "First" << bn;
    else cout << "Second" << bn;
}

