void dfs(int curr,int prev)
{
	dp [curr] = 0;
	for(const auto& it : edge [curr]) if(it != prev){
		dfs(it,curr);
		par [it] = curr;
		if(dp [it] == 0){
			dp [curr] = 1;
		}
	}
}

void dfs2(int curr,int prev,int val)
{
	dp2 [curr] = val;
	int sum = 0;
	if(prev != -1){
		sum += dp2 [curr] == 0;
	}
	for(const auto& it : edge [curr]) if(it != prev){
		sum += dp [it] == 0;
	}
	for(const auto& it : edge [curr]) if(it != prev){
		if(sum - (dp [it] == 0) > 0){
			dfs2(it,curr,1);
		}
		else{
			dfs2(it,curr,0);
		}
	}
}

