string solve1(VVI& g) {
	while(1) {
		REP(i, N) {
			int cnt=0;
			for(int j : g[i]) {
				if(g[j].size()==1) cnt++;
			}
			if(cnt>=2) {
				return "First";
			}
		}

		// i - adj - X =... -> X =...
		bool ch=false;
		REP(i, N) {
			if(g[i].size()==1) {
				int adj = g[i][0];
				if(g[adj].size()==2) {
					int X = g[adj][0]==i ? g[adj][1] : g[adj][0];
					{
						auto en = remove_if(ALL(g[X]), [=](int a) { return adj==a; });
						g[X].erase(en, g[X].end());
					}
					g[adj].clear();
					g[i].clear();
					ch=true;
				}
			}
		}
		if(!ch) break;
	}
	return "Second";
}

// return: このノード以下で完全マッチの相手を探している個数
ll dfs(int u, int p, VVI& g) {
	ll x = 0;
	for(int v: g[u]) if(v!=p) x += dfs(v, u, g);
	if(x==0) return 1; // need to match ... 子が全部マッチしてるので
	if(x==1) return 0; // matched
	return INF;
}

string solve2(VVI& g) {
	ll rest = dfs(0, -1, g);
	string ans = rest ? "First" : "Second";
	return ans;
}

