#define END {cout << "First\n"; return 0;}

int main() {
    int N, a, b, i;
    int conLeave[100000] = {};
    vector<set<int> > g(100000);
    cin >> N;
    set<int>::iterator it;

    for (i = 0; i < N-1; i++) {
        cin >> a >> b;
        a--, b--;
        g[a].insert(b);
        g[b].insert(a);
    }

    // get a list of leaves and where they connect to
    vector<int> leaves;
    for (i = 0; i < N; i++) {
        if (g[i].size() == 1) {
            if (conLeave[*g[i].begin()]) END; 
            conLeave[*g[i].begin()]++;
            leaves.push_back(i);
        }
    }


    // Continually choose leaves
    for (i = 0; i < leaves.size(); i++) {
        int leaf = leaves[i];
        if (g[leaf].size() <= 0) continue;
        int conn = *g[leaf].begin();
        // everything that was connected has one less edge
        for (it = g[conn].begin(); it != g[conn].end(); ++it) {
            g[*it].erase(conn);
            if (g[*it].size() == 1) {
                int newLeaf = *g[*it].begin();
                if (conLeave[newLeaf]) END;
                conLeave[newLeaf]++;
                leaves.push_back(newLeaf);
            }
        }
    }

    cout << "Second\n";
}

