        return parity[u][v] = 1;

    int mask = 0;
    for (int w : adj[v]) {
        if (w == u)
            continue;
        int p = calc(v, w);
        if (p == 1)
            mask |= 2;
        if (p == 2)
            mask |= 1;
    }
    return parity[u][v] = mask;
}

int main() {
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (int i = 0; i < n; i++) {
        int cnt = 0;
        for (int j : adj[i]) {
            int p = calc(i, j);
            if (p == 2)
                cnt++;
        }
        if (cnt == adj[i].size()) {
            //cout << "CHOSE: " << i+1 << " " << adj[i].size() << endl;
            cout << "First" << endl;
