int n;
vector<int> g[111111];

P dfs(int v,int pre){
  if(g[v].size()==1&&g[v][0]==pre){
    //他につながっている頂点が先につながっていると評価されたもの以外無ければsecondがfalseであると返す
    return P(true,false);
  }
  int cnt = 0;
  for(int nv:g[v]){
    //ループ防止の為
    if(nv!=pre){
      P tmp = dfs(nv,v);
      if(!tmp.fi) return P(false,false);
      if(!tmp.se) cnt++;
    }
  }
  return P(cnt <=1,cnt == 1);
}

void solve(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin>>n;
  rep(i,n-1){
    int a,b;
    cin>>a>>b;
    a--;
    b--;
    g[a].pb(b);
    g[b].pb(a);
  }
  P res=dfs(0,-1):
  if(res.fi&&res.se) cout<<"Second"<<endl;
  else cout<<"First"<<endl;

}
int main(){
  solve();
  return 0;
}

