#define N 100003

vector<int> edge[N];
bool vis[N];
int paired[N];

void dfs(int s)
{
	vis[s] = true;

	int nn = -1;

	for(auto it : edge[s])
	{
		if(!vis[it])
		{
			paired[s] = paired[it] = true;
			vis[it] = true;
			nn = it;
			break;
		}
	}

	for(auto it : edge[s])
		if(!vis[it])
			dfs(it);

	if(nn==-1) return;

	for(auto it : edge[nn])
		if(!vis[it])
			dfs(it);
}

