vector<ll> G[100010];
ll col[100010];

ll dfs1(ll x, ll p){
  ll c = 0;
  ll len = 0;
  ll od = 0;
  YYS(w, G[x]){
    if(w == p){
      continue;
    }
    len = dfs1(w, x) + 1;
    if(col[w] == 0){
      col[x] = 1;
    }
    c++;
    if(len >= 0 && len % 2 == 1){
      od++;
    }
  }
  if(od >= 2){
    puts("First");
    exit(0);
  }
  if(c <= 1){
    return len;
  }
  return -INFLL;
}

void dfs2(ll x, ll p, ll up){
  ll c = up;
  YYS(w, G[x]){
    if(w == p){
      continue;
    }
    c += 1 - col[w];
  }
  if(c == 0){
    // cout << x << endl;
    puts("First");
    exit(0);
  }
  YYS(w, G[x]){
    if(w == p){
      continue;
    }
    ll nc = c - (1 - col[w]);
    ll nup = 0;
    if(nc == 0){
      nup = 1;
    }
    dfs2(w, x, nup);
  }
}

