  vector<vector<int>> G(n);
  vector<vector<int>> sub(n);
  for(int i=0; i<n-1; i++){
    int a,b;
    cin >> a,b;
    a--; b--;

    G[a].push_back( b );
    G[b].push_back( a );

    sub[a].push_back( -1 );
    sub[b].push_back( -1 );
  }

  function<int(int, int)> dfs = [&](int pos, int last){
    int ret = 1;
    for(int i=0; i<G[pos].size(); i++){
      int next = G[pos][i];
      if(next == last) continue;
      int sub_size = dfs(next, pos);
      sub[pos][i] = sub_size;
      ret += sub_size;
    }
    return ret;
  };

  dfs(0, -1);
  for(int i=0; i<n; i++){
    int sum = 0;
    int ee = -1;
    for(int j=0; j<G[i].size(); j++){
      if( sub[i][j] == -1 ){
        ee = j;
      }else{
        sum += sub[i][j];
      }
    }

    if( ee != -1){
      sub[i][ee] = n - 1 - sum;
    }
  }

  for(int i=0; i<n; i++){
    int one = 0;
    for(int j=0; j<sub[i].size(); j++){
      if( sub[i][j] == 1 || sub[i][j] == 3 ){
        one++;
      }
    }
    if( one > 1 ){
      println("First");
      return 0;
    }
  }
  println("Second");

  return 0;
}

