int dfs(int node,int p) {
  int ret = 0;
  int sz = adj[node].size(),ch;
  int sum = 0;// matched
  //one unmatch  + match
  int maxi = -2;
  for(int i=0;i<sz;++i) {
    ch = adj[node][i];
    if(ch!=p) {
      dfs(ch,node);
      sum += dp[ch][1];
      maxi = max(maxi,-dp[ch][1] +dp[ch][0]);
    }
  }
  dp[node][0] = sum;
  dp[node][1] = sum + maxi + 1;
  return max(dp[node][0],dp[node][1]);
}
