int main() {
	cin >> n;
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		g[a].insert(b);
		g[b].insert(a);
	}

	for (int i = 0; i < n; i++) 
		heap.insert(i);

	while (!heap.empty()) {
		int v = *heap.begin();
		heap.erase(heap.begin());

		if (mark[v])
			continue;
		mark[v] = true;

		// cerr << "V: " << v + 1 << endl;; 
