bool solve(){
	if(rest==1)return true;
	memset(cnt,0,sizeof(cnt));
	for(int i=0;i<n;i++){
		if(e[i]==1 && !used2[i]){
			cnt[G[i][0]]++;
		}
	}
	for(int i=0;i<n;i++){
		if(cnt[i]>=2){
			return true;
		}
	}
	int on=0,se=0;
	bool flag=true;
	for(int i=0;i<n;i++){
		if(e[i]==1 && !used2[i]){
			on++;
		}
		if(e[i]==2 && !used2[i]){
			se++;
		}
		if(e[i]>2 && !used2[i]){
			flag=false;
		}
	}
	if(flag && on==2 && se==n-2){
		return (n%2==1);
	}
