	for (auto v: g[u]) if (v != far) {
		red[v] = red[u] ^ true;
		dfs(v, u); } }

static bool pairup(int u) {
	if (f[u]) return false;
	f[u] = true;

	for (auto v: g[u]) if (!dr[v]) {
		st[u] = v;
		dr[v] = u; 
		return true; }

	for (auto v: g[u]) if (pairup(dr[v])) {
		st[u] = v;
		dr[v] = u;
		return true; }

	return false; }


