void BFS(){
    while(!Q.empty()){
        int a=Q.front();Q.pop();
        for(int i=0;i<G[a].size();i++){
            int b=G[a][i];
            if(used[b]) continue;
            used[b]=1;
            for(int j=0;j<G[b].size();j++){
                int c=G[b][j];
                if(!used[c]){
                    used[c]=1;
                    Q.push(c);
