using namespace std;

vector<int> g[100005];
bool dp[100005]={}; 
int sz[100005]={};

void pre(int u, int par){
	sz[u]=1;
	int c;
	for(auto v:g[u]){
		if(v!=par){
			pre(v,u);
			sz[u]+=sz[v];
			c=v;
		}
	}
	if(g[u].size()==1){
		dp[u]=1;
	}
	if(g[u].size()==2){
		dp[u]=dp[c];
	}
}

void dfs(int u, int par, int up, int upsz){
	int paths=0;
	for(auto v:g[u]){
		if(v!=par){
			dfs(v,u,(up&&(g[u].size()==2)),upsz+sz[u]-sz[v]);
			paths+=dp[v]&&(sz[v]&1);
		}
	}
	if(par)
		paths+=up&&(upsz&1);

	if(paths>=2){
		cout << "First" << endl;
		exit(0);
	}
}

