  rep(i, n)if(sz(edge[i]) == 1)st.push(i);
  vector<bool> used(n, false);
  while(!st.empty()){
    auto p = st.top(); st.pop();
    if(used[p])continue;
    used[p] = true;
    bool ok = false;
    for(auto e: edge[p]){
      if(!used[e]){
        used[e] = true;
        for(auto ce: edge[e]){
          if(used[ce])continue;
          sz[ce]--;
          if(sz[ce] <= 1)st.push(ce);
        }
        ok = true;
        break;
      }
    }
    if(!ok){
      cout << "First" << endl;
      return 0;
    }
  }
  cout << "Second" << endl;
  return 0;
}

