#include <bits/stdc++.h>
using namespace std;

int main()
{
    int N; cin >> N;

    auto neighbors = vector<set<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        neighbors[a].insert(b);
        neighbors[b].insert(a);
    }

    auto leaves = vector<int>();
    auto parents = set<int>();
    for (auto v = 0; v < N; v++) if (neighbors[v].size() == 1)
    {
        leaves.push_back(v);
        const auto parent = *begin(neighbors[v]);
        if (parents.count(parent))
        {
            cout << "First" << endl;
            return 0;
        }
        else parents.insert(parent);
    }

    auto removed = set<int>();
    while (N - int(removed.size()) >= 3)
    {
        const auto leaf = leaves.back(); leaves.pop_back();
        const auto parent = *begin(neighbors[leaf]);
        parents.erase(parent);

        removed.insert(leaf);
        removed.insert(parent);
        N -= 2;

        for (const auto v : neighbors[parent]) if (!removed.count(v))
        {
            neighbors[v].erase(parent);
            if (neighbors[v].size() == 1)
            {
                leaves.push_back(v);
                const auto parent2 = *begin(neighbors[v]);
                if (parents.count(parent2))
                {
                    cout << "First" << endl;
                    return 0;
                }
                else parents.insert(parent2);
            }
        }
    }

    cout << (N - int(removed.size()) == 1 ? "First" : "Second") << endl;
}

