vector<int> dp1;
bool two_any_path_any(int v, int p) {
    dump(v, p);
    int &res = dp1[v];
    if (res != -1) return res;

    res = false;
    for (auto &c : g[v]) {
        if (c == p) continue;
        if (deg[c] == 2) {
            res |= two_any_path_two(c, v);
        }
    }
    return res;
}

vector<int> dp2;
bool two_any_path_two(int v, int p) {
    dump(v, p);
    int &res = dp2[v];
    if (res != -1) return res;

    res = false;
    if (deg[v] == 1) res = true;
    for (auto &c : g[v]) {
        if (c == p) continue;
        res |= two_any_path_any(c, v);
    }
    return res;
}

bool dfs(int v, int p) {
    dump(v, p);
    int cnt = 0;
    for (auto &c : g[v]) {
        if (c == p) continue;
        if (two_any_path_two(c, v)) ++cnt;
        if (dfs(c, v)) return true;
    }
    return cnt >= 2;
}

