map<int, bool> dp[112345];
int cnt[112345];

bool dfs(int u, int prev) {
	if (dp[u].find(prev) != dp[u].end()) return dp[u][prev];

	if (g[u].size() == 1) return dp[u][prev] = true;

	int cnt = 0;
	REP(i, g[u].size()) {
		int v = g[u][i];
		if (v == prev) continue;

		if (dfs(v, u)) cnt++;

		if (cnt >= 2) return dp[u][prev] = true;;
	}
	return dp[u][prev] = false;
}

