		int a, b;
		scanf("%d %d", &a, &b);
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);

		cnt[a]++;
		cnt[b]++;
	}

	bool ans = true;
	REP(i, N) if (!dfs(i, -1)) ans = false;

	if (!ans) {
		REP(i, N) {
			int c = 0, c2 = 0;
			REP(j, g[i].size()) {
				if (cnt[ g[i][j] ] == 1) c++;
				if (cnt[ g[i][j] ] >= 2) c2++;
			}

			if (c >= 2) ans = true;
			if (c2 >= 3) ans = true;
		}
	}

	if (ans) puts("First");
	else puts("Second");

	return 0;
}

