struct bipartite_matching {
	VVI g;
	VI match;
	VI used;

	bipartite_matching(int N) {
		g = VVI(N);
	}

	int dfs(int v) {
		used[v]=1;
		for(int i=0;i<(int)g[v].size();i++) {
			int u=g[v][i], w=match[u];
			if(w<0 || (!used[w] && dfs(w))) {
				match[v]=u;
				match[u]=v;
				return 1;
			}
		}
		return 0;
	}

	int run() {
		int res=0;
		match=VI(g.size(), -1);
		for(int v=0;v<(int)g.size();v++){
			if(match[v]<0) {
				used=VI(g.size());
				if(dfs(v)) res++;
			}
		}
		return res;
	}

	void add_edge(int u, int v){
		g[u].push_back(v);
		g[v].push_back(u);
	}
};


