int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x; --y;
    a[x].insert(y);
    a[y].insert(x);
  }
  set<int> Q;
  for (int i = 0; i < n; ++i) {
    if (a[i].size() == 1) {
      Q.insert(i);
    }
