struct HopcroftKarp {
    vector<vector<int>> g;
    vector<int> d, mch;
    vector<bool> vv, used;

    HopcroftKarp(int n, int m) : g(n), mch(m, -1), used(n) {}

    void add_edge(int u, int v) {
      g[u].push_back(v);
    }

    void bfs() {
      d.assign(g.size(), -1);
      queue<int> que;
      for (int i = 0; i < (int)(g.size()); i++) {
        if (!used[i]) {
          que.emplace(i);
          d[i] = 0;
        }
      }

      while (!que.empty()) {
        int a = que.front();
        que.pop();
        for (auto &b : g[a]) {
          int c = mch[b];
          if (c >= 0 && d[c] == -1) {
            d[c] = d[a] + 1;
            que.emplace(c);
          }
        }
      }
    }

    bool dfs(int a) {
      vv[a] = true;
      for (auto &b : g[a]) {
        int c = mch[b];
        if (c < 0 || (!vv[c] && d[c] == d[a] + 1 && dfs(c))) {
          mch[b] = a;
          used[a] = true;
          return true;
        }
      }
      return false;
    }

    int bipartite_matching() {
      int ret = 0;
      while (true) {
        bfs();
        vv.assign(g.size(), false);
        int flow = 0;
        for (int i = 0; i < g.size(); i++) {
          if (!used[i] && dfs(i)) ++flow;
        }
        if (flow == 0) return ret;
        ret += flow;
      }
    }
};

int id1 = 0, id2 = 0;
vi v;

void dfs(int now, int prev, bool parity, const vvi &tr) {
  if(!parity) {
    v[now] = id1;
    id1++;
  } else {
    v[now] = id2;
    id2++;
  };

  for(int k=0;k<SZ(tr[now]);++k) {
    int nxt = tr[now][k];
    if(nxt == prev)continue;
    dfs(nxt, now, !parity, tr);
  }
}

void dfs2(int now, int prev, bool parity, const vvi &tr, HopcroftKarp &match) {
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    if(parity) {
      match.add_edge(v[now], v[nxt]);
    } else {
      match.add_edge(v[nxt], v[now]);
    }
    dfs2(nxt, now, !parity, tr, match);
  }
}

