        int x, y;
        cin >> x >> y;
        g[x].emplace_back(y);
        g[y].emplace_back(x);
    }
    vector<int> l(n + 1);
    for (int i = 1; i <= n; i++) {
        if (g[i].size() == 1) {
            l[g[i][0]]++;
        }
    }
    if (n == 2) {
        cout << "Second" << '\n';
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        if (l[i] > 1) {
            cout << "First" << '\n';
            return 0;
        }
    }
    vector<int> sz(n + 1, 1);
    vector<int> depth(n + 1, -1);
    depth[1] = 0;
    function<void(int, int)> dfs = [&](int v, int p) {
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            depth[to] = depth[v] + 1;
            dfs(to, v);
            sz[v] += sz[to];
        }
    };
    dfs(1, -1);
    for (int i = 0; i < n; i++) {
        if ((n - sz[i]) % 2 == 1) {
            continue;
        }
        bool ok = true;
        for (int j : g[i]) {
            if (sz[j] > sz[i]) {
                continue;
            }
            if (sz[j] % 2) {
                ok = false;
            }
        }
        if (ok) {
