            g[0].emplace_back(i);
            g[i].emplace_back(0);
        }
    }
    queue<int> que;
    que.emplace(0);
    vector<int> cnt(n + 1);
    cnt[0] = 1;
    depth[0] = 0;
    while (!que.empty()) {
        for (int i = que.size(); i > 0; i--) {
            int v = que.front();
            que.pop();
            for (int to : g[v]) {
                if (depth[to] != -1) {
                    continue;
                }
                depth[to] = depth[v] + 1;
                que.emplace(to);
                cnt[depth[to]]++;
            }
        }
    }
    for (int i = 1; i < n; i += 2) {
        if (cnt[i] == 0) {
            cout << "Second" << '\n';
            break;
        }
        if (cnt[i + 1] == 0) {
            if (cnt[i] == 1) {
                cout << "First" << '\n';
            } else {
                cout << "Second" << '\n';
            }
            break;
        }
        if (cnt[i] > cnt[i + 1]) {
            cout << "First" << '\n';
            break;
        }
    }
    return 0;
}

