void dfs(Graph& graph, Vvec<int>& dp, int tmp, int from){
    if(from != -1 && graph[tmp].size() == 1){
        dp[tmp][0] = 1;
        dp[tmp][1] = 0;
        return;
    }

    vector<ll> bs(graph[tmp].size()+1);
    int j = 0;
    for(auto& to: graph[tmp]){
        if(to != from){
            dfs(graph, dp, to, tmp);
            bs[j++] = dp[to][1];
        }
    }
    bs[j] = true;
    // cout << j <<" " << bs.size() << endl;
    while(j>0){
        bs[j-1] = bs[j-1] & bs[j];
        j--;
    }

    dp[tmp][0] = bs[0];
    bool b = true;
    for(auto& to: graph[tmp]){
        if(to != from){
            dp[tmp][1] |= b & dp[to][0] & bs[++j];
            b &= dp[to][1];
        }
    }
}

