int dp [100001] [2],dp2 [100001] [2];

void dfs(int curr,int prev)
{
	bool leaf = true;
	for(const auto& it : edge [curr]) if(it != prev){
		dfs(it,curr);
		dp [curr] [0] += dp [it] [1];
		dp [curr] [1] += dp [it] [0];
		leaf = false;
	}
	if(leaf){
		dp [curr] [0] = 1;
	}
}

void dfs2(int curr,int prev)
{
	if(prev != -1){
		dp2 [curr] [0] += dp [prev] [1] + dp2 [prev] [1];
		dp2 [curr] [1] += dp [prev] [0] + dp2 [prev] [0];
		dp2 [curr] [0] -= dp [curr] [0];
		dp2 [curr] [1] -= dp [curr] [1];
	}
	else{
		if(edge [curr].size() == 1){
			dp2 [curr] [0]++;
		}
	}
	for(const auto& it : edge [curr]) if(it != prev){
		dfs2(it,curr);
	}
}

