const int MAX_N = 1e5;
const int MAX_V = MAX_N;

int N;
vector<int> g[MAX_V];
int match[MAX_V];
bool used[MAX_V];

bool dfs(int v) {
    used[v] = true;
    for (int u : g[v]) {
        int w = match[u];
        if (w < 0 || (!used[w] && dfs(w))) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching(int V) {
    int cnt = 0;
    memset(match, -1, sizeof(match));
    for (int v = 0; v < V; v++) {
        if (match[v] < 0) {
            memset(used, 0, sizeof(used));
            if (dfs(v)) {
                cnt++;
            }
        }
    }

    return cnt;
}

bool solve() { return (bipartite_matching(N) * 2 < N); }

