template<class T> struct edge_ {    int f, t;    T c;    edge_(int f, int t, T c = 1) : f(f), t(t), c(c) {}    bool operator<(const edge_ &b) const { return c < b.c; }    bool operator>(const edge_ &b) const { return c > b.c; }};
