template<class T> int krus(undigraph<T> &g) {    int res = 0;    unionfind uf(g.n);    if (sz(g.edges) == 0)g.set_edges();    int i = 0;    auto E = g.edges;    sort(E);    fora(e, E) { if (uf.unite(e.f, e.t)) { res += e.c; }}    return res;}
template<class T> vector<edge_<T>> krus_ed(undigraph<T> &g) {    unionfind uf(g.n);    if (sz(g.edges) == 0)g.set_edges();    int i = 0;    auto E = g.edges;    sort(E);    vector<edge_<T>> res;    fora(e, E) { if (uf.unite(e.f, e.t)) { res.push_back(e); }}    return res;}
template<class T> tree<T> krus_tr(undigraph<T> &g) {    tree<T> res(g.n);    unionfind uf(g.n);    if (sz(g.edges) == 0)g.set_edges();    int i = 0;    auto E = g.edges;    sort(E);    fora(e, E) { if (uf.unite(e.f, e.t)) { res.add(e.f, e.t); }}    return res;}
template<class T> int krus( vector<edge_<T>> &g) {int n=0;    fora(e,g){chma(n,max(e.f,e.t)+1);};    int res = 0;    unionfind uf(n);    auto E = g;    sort(E);    fora(e, E) { if (uf.unite(e.f, e.t)) { res += e.c; }}    return res;}
template<class T> vector<edge_<T>> krus_ed( vector<edge_<T>> &g) {    int n=0;    fora(e,g){chma(n,max(e.f,e.t)+1);};    vector<edge_<T>> res;    unionfind uf(n);    auto E = g;    sort(E);    fora(e, E) { if (uf.unite(e.f, e.t)) { res += e; }}    return res;};
template<class T> vi krus_i( vector<edge_<T>> &g) {    int n=0;    fora(e,g){chma(n,max(e.f,e.t)+1);};    vi res;    unionfind uf(n);    auto E = g;    sort(E);    int i = 0;    fora(e, E) {        if (uf.unite(e.f, e.t)) { res += i; }        i++;    }    return res;}
