int main( void ) {

    int n;
    cin >> n;

    for( int i = 2; i <= n; i ++ ) {
        int x, y;
        cin >> x >> y;

        edg[x].insert( y );
        edg[y].insert( x );
    }

    for( int i = 1; i <= n; i ++ ) {
        if( edg[i].size() == 1 )
            que.push_back( i );
    }

    int val = n;
    for( ; que.empty() == false; que.pop_front() ) {
        int x = que.front();

        if( oki[x] == true )
            continue;

        int y = *edg[x].begin();

        if( oki[y] == true )
            continue;

        if( edg[y].size() == 2 ) {
            int z = *edg[y].begin();

            if( z == x )
