            edg[z].erase( edg[z].find( y ) );
            if( edg[z].size() == 1 )
                que.push_back( z );

            val -= 2;
            oki[x] = oki[y] = true;
        }
    }

    for( int i = 1; i <= n; i ++ ) {
        if( edg[i].size() == 1 )
            deg[*edg[i].begin()] ++;
    }

    bool ok = ( val != 2 );

