signed main() {
	INIT;
	VAR(int, n);
	VEC_ROW(int, n-1, a, b);
	std::vector<std::vector<int>> g(n);
	REP(i, n - 1) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}
	std::vector<int> cnt(n);
	std::stack<int> st;
	REP(i, n) {
		cnt[i] = g[i].size();
		if (cnt[i] == 1) st.push(i);
	}
	std::vector<bool> used(n, false);
	while (!st.empty()) {
		int now = st.top(); st.pop();
		if (cnt[now] == 0) {
			OUT("First")BR;
			return 0;
		}
		if (used[now]) continue;
		int v = g[now][0];
		used[now] = true;
		used[v] = true;
		for (auto& to : g[v]) {
			if (used[to]) continue;
			--cnt[to];
			g[to].erase(std::find(ALL(g[to]), v));
			if (cnt[to] == 1) {
				st.push(to);
			}
			else if (cnt[to] == 0) {
				OUT("First")BR;
				return 0;
			}
		}
	}
	OUT("Second")BR;
	return 0;
}

