using namespace std;
int N;

vector<int> g[100005];
vector<int> G[100005];
vector<int> gx[100005];
vector<int> gy[100005];

bool A[100005];

int root;

int x[100005];
int y[100005];
int par[100005];

bool ans;

void func(int pos,int prev=-1){
  if(G[pos].size()==0){
    x[pos]=1;
    y[pos]=0;
    return;
  }

  x[pos]=y[pos]=0;
  for(int i=0;i<(int)G[pos].size();i++){
    int to=G[pos][i];
    func(to,pos);
    x[pos]+=y[to];
    y[pos]+=x[to];
  }

}

void dfs(int pos,int prev=-1){

  //  cout<<pos<<endl;

  sort(g[pos].begin(),g[pos].end());

  for(int i=0;i<(int)g[pos].size();i++){
    int to=g[pos][i];
    if(to==prev)continue;
    dfs(to,pos);
    G[pos].push_back(to);
  }
}

void rec(int pos,int prev=-1){

  //  if(G[pos].size()==0)
  if(prev!=-1){
    int nx=x[pos]+y[prev]-y[pos];
    int ny=y[pos]+x[prev]-x[pos];
    x[pos]=nx;
    y[pos]=ny;
  }
  /*
  cout<<pos<<endl;
  cout<<x[pos]<<' '<<y[pos]<<endl;
  cout<<endl;
  */
  if(x[pos]>0 && y[pos]==0)ans=true;
  for(int i=0;i<(int)G[pos].size();i++)
    rec(G[pos][i]);

}

bool solve(){
  if(N==1)return true; 
  if(N==2)return false;

  ans=false;

  for(int i=0;i<N;i++){
    if(g[i].size()>1)root=i;
    int cc=0;
    for(int to:g[i]){
      if(g[to].size()==1)cc++;
    }
    if(cc>=2)return true;
  }

  dfs(root);

  func(root);

  rec(root);
  return ans;
}

int main(){
  scanf("%d",&N);

  for(int i=0;i<N-1;i++){
    int a,b;
    scanf("%d %d",&a,&b);
    a--,b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  if(solve())printf("First\n");
  else printf("Second\n");
  return 0;
}

