        watch(leafs);
        if (leafs.size() == 2 && count(ALL(g[leafs[0]]), leafs[1])) {
            cout << "Second";
            return;
        }
        vi white_leafs;
        for (int v : leafs) {
            for (int to : g[v]) {
                deg[to]--;
                if (!used[to]) {
                    used[to] = true;
                    white_leafs.push_back(to);
                }
            }
        }
        if (white_leafs.size() < leafs.size()) {
            cout << "First";
            return;
        }
        leafs.clear();
        for (int v : white_leafs) {
            for (int to : g[v]) {
                deg[to]--;
                if (deg[to] == -1 && !used[to]) {
                    assert(0);
                    used[to] = true;
                    leafs.push_back(to);
