const int MAXN = 1000100;

int h[MAXN],ne[MAXN],t[MAXN],c[MAXN],v[MAXN];
int n,tot,m,cnt;
int q[MAXN],tmp[MAXN];

void link(int x,int y){
  tot++;
  t[tot] = y; ne[tot] = h[x];
  h[x] = tot;
}

void remove(int x){
  tmp[++tot] = x;
  v[x] = cnt;
}

bool killLeaf(){
  int m1 = m;
  cnt++; tot = 0;
  FOR(i,1,m){
    int x = q[i];
    c[x] = 0;
    for(int j = h[x]; j > 0; j = ne[j]){
      int y = t[j];
      if(v[y] == 0) remove(y);
    }
  }
  FOR(i,1,tot) q[i] = tmp[i];
  m = tot;
  int m2 = m;
  if(m2 == 0) return false;
  if(m2 < m1) return true;

  tot = 0;
  cnt++;
  FOR(i,1,m){
    int x = q[i];
    c[x] = 0;
    for(int j = h[x]; j > 0; j = ne[j]){
      int y = t[j];
      if(v[y] == 0){
        c[y]--;
        if(c[y] == 1) remove(y);
      }
    }
  }
  FOR(i,1,tot) q[i] = tmp[i];
  m = tot;
  return false;
}

bool solve(){
  m = 0; cnt = 1;
  FOR(i,1,n) if(c[i] == 1){
    q[++m] = i;
    remove(i);
  }
  while(m > 0){
    if(killLeaf()) return true;
  }
  return false;
}

int main(){
  scanf("%d",&n);
  FOR(i,1,n-1){
    int x,y;
    scanf("%d%d",&x,&y);
    link(x,y);
    link(y,x);
    c[x]++; c[y]++;
  }
  if(solve()) cout << "First";
  else cout << "Second";
  return 0;
}

