int get_sz(vector<vi> &tree, vi &sz, int v)
{
	int res = 1;
	for (auto u : tree[v])
	{
		res += get_sz(tree, sz, u);
	}
	return sz[v] = res;
}

int main()
{
	cin.sync_with_stdio(false); cout << fixed << setprecision(10);
	int n; cin >> n;
	vector<vi> g(n);
	REP(i, n - 1)
	{
		int a, b; cin >> a >> b;
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	int r = 0;
	vector<bool> vis(n);
	vis[r] = true;
	vector<set<int>> tree(n);
	queue<int> que;
	que.push(r);
	vi par(n);
	par[r] = -1;
	while (!que.empty())
	{
		int v = que.front();
		que.pop();
		for (auto u : g[v])
		{
			if (vis[u]) continue;
			vis[u] = true;
			tree[v].insert(u);
			par[u] = v;
			que.push(u);
		}
	}
	vi childcnt(n);
	REP(i, n) childcnt[i] = tree[i].size();

	set<int> leaf;
	set<int> uncolor; REP(i, n) uncolor.insert(i);
	vi color(n, -1);
	REP(i, n)
	{
		if (tree[i].empty()) leaf.insert(i);
	}
	bool ans = true;
	//for (auto v : leaf)
	while(!leaf.empty())
	{
		int v = *leaf.begin();
		leaf.erase(v);
		if (v == r)
		{
			color[v] = 0;
		}
		else
		{
			int u = par[v];
			color[v] = 1;
			uncolor.erase(v);
			if (color[u] != -1)
			{
				ans = false;
				break;
			}
			color[u] = 0;
			uncolor.erase(u);

			if (u != r)
			{
				childcnt[par[u]]--;
				if (childcnt[par[u]] == 0)
				{
					leaf.insert(par[u]);
				}
			}
		}
	}

	if (ans)
	{
		REP(i, n)
		{
			assert(color[i] != -1);
		}
		vi color2(n);
		REP(i, n)
		{
