			{
				color2[i] = 1;
				for (auto v : g[i]) color2[v] = 1;
			}
		}
		for (auto c : color2)
		{
			if (c == 0) ans = false;
		}
	}
	cout << (ans ? "Second" : "First") << endl;
	return 0;
}

