struct HopcroftKarp {
    vector<vector<int>> g;
    vector<int> d, mch;
    vector<bool> vv;

    HopcroftKarp(int n, int m) : g(n), mch(m, -1) {}

    void add_edge(int u, int v) {
      g[u].push_back(v);
    }

    void bfs() {
      d.assign(g.size(), -1);
      queue<int> que;
      for (int i = 0; i < (int)(g.size()); i++) {
        if (mch[i] != -1) {
          que.emplace(i);
          d[i] = 0;
        }
      }

      while (!que.empty()) {
        int a = que.front();
        que.pop();
        for (auto &b : g[a]) {
          int c = mch[b];
          if (c >= 0 && d[c] == -1) {
            d[c] = d[a] + 1;
            que.emplace(c);
          }
        }
      }
    }

    bool dfs(int a) {
      vv[a] = true;
      for (auto &b : g[a]) {
        int c = mch[b];
        if (c < 0 || (!vv[c] && d[c] == d[a] + 1 && dfs(c))) {
          mch[b] = a;
          return true;
        }
      }
      return false;
    }

    int bipartite_matching() {
      int ret = 0;
      while (true) {
        bfs();
        vv.assign(g.size(), false);
        int flow = 0;
        for (int i = 0; i < g.size(); i++) {
          if (mch[i] < 0 && dfs(i)) ++flow;
        }
        if (flow == 0) return ret;
        ret += flow;
      }
    }
};

int id1 = 0, id2 = 0;
vi v;

void dfs(int now, int prev, bool parity, const vvi &tr) {
  if(!parity) {
    v[now] = id1;
    id1++;
  } else {
    v[now] = id2;
    id2++;
  };

  for(int k=0;k<SZ(tr[now]);++k) {
    int nxt = tr[now][k];
    if(nxt == prev)continue;
    dfs(nxt, now, !parity, tr);
  }
}

void dfs2(int now, int prev, bool parity, const vvi &tr, HopcroftKarp &match) {
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    if(parity) {
      match.add_edge(v[now], v[nxt]);
    } else {
      match.add_edge(v[nxt], v[now]);
    }
    dfs2(nxt, now, !parity, tr, match);
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int n; cin >> n;
  vvi tr(n);
  for(int i=0;i<n-1;++i) {
    int a, b; cin >> a >> b;
    a--; b--;
    tr[a].push_back(b);
    tr[b].push_back(a);
  }

  v.resize(n);
  dfs(0, -1, 0, tr);
  HopcroftKarp match(id1, id2);
  id1 = 0, id2 = 0;
  dfs2(0, -1, 0, tr, match);

  if(n % 2 == 0 && match.bipartite_matching() == n/2) {
    cout << "Second" << endl;
  } else {
    cout << "First" << endl;
  }
}

