    a = p.second;
    b = *e[a].begin();
    st.erase(P(e[b].size(), b));
    auto tmp = e[b].begin();
    while (tmp != e[b].end()) {
      ll x = *tmp;
      st.erase(P(x, e[x].size()));
      e[x].erase(b);
      if (e[x].size() == 0) {
        if (a != x && i != j) {
          printf("First\n");
          return 0;
        }
      } else {
        st.insert(P(x, e[x].size()));
      }
      tmp = e[b].erase(tmp);
    }
  }
  printf("Second\n");
}

