void dfs(int u, int f) {
	mark[u] = 1; int ct = 0;
	for (int i = head[u]; i; i = e[i].next)
		if (e[i].to != f) dfs(e[i].to, u), ct += mark[e[i].to];
	if (ct > 1 || (u == 1 && ct == 0)) puts("First"), exit(0);
	if (ct == 1) mark[u] = 0;
}
