template<typename costType = int>
class TreeDiameter {
private:
    std::vector<std::vector<std::pair<int, costType>>> Graph;
    std::vector<costType> dist;
    int root;
    void makeTreeDfs(const std::vector<std::vector<int>> &G, int now, int prev) {
        for (auto &&e : G[now]) if (e != prev) {
            Graph[now].emplace_back(std::make_pair(e, 1));
            Graph[e].emplace_back(std::make_pair(now, 1));
            makeTreeDfs(G, e, now);
        }
    }
    void calcTreeDiameterDfs(int now, int prev) {
        for (auto &&e : Graph[now]) if (e.first != prev) {
            dist[e.first] = dist[now] + e.second;
            calcTreeDiameterDfs(e.first, now);
        }
    }
public:
    TreeDiameter() {}
    TreeDiameter(int n) {
        init(n);
    }
    void init(int n) {
        Graph.resize(n);
        dist.resize(n, 0);
    }
    TreeDiameter(const std::vector<std::vector<std::pair<int, costType>>> &G) {
        Graph = G;
        dist.resize(G.size());
    }
    TreeDiameter(const std::vector<std::vector<int>> &G) {
        Graph.resize(G.size());
        makeTreeDfs(G, 0, -1);
        dist.resize(G.size());
    }
    void addEdge(int u, int v, costType cost) {
        Graph[u].emplace_back(std::make_pair(v, cost));
        Graph[v].emplace_back(std::make_pair(u, cost));
    }
    int calcTreeDiameter() {
        calcTreeDiameterDfs(0, -1);
        root = std::distance(std::begin(dist), std::max_element(std::begin(dist), std::end(dist)));
        dist[root] = 0;
        calcTreeDiameterDfs(root, -1);
        return *std::max_element(std::begin(dist), std::end(dist));
    }
    int getRoot() {return this->root;}
};

