typedef pair<int, int> P;

int N;
vector<int> color;
priority_queue<P, vector<P>, less<P>> que_t;
priority_queue<P, vector<P>, greater<P>> que_a;
vector<vector<int>> tree;

bool win_takahashi() {
	vector<int> color2(color);

	for (int i = 1; i <= N; i++)
		if (color[i] == -1)
			for (int j = 0; j < tree[i].size(); j++)
				color2[tree[i][j]] = -1;

	int cnt = 0;
	for (int i = 1; i <= N; i++)
		if (color2[i] == -1)
			cnt++;

	if (cnt == N)
		return false;
	else
		return true;
}

int main() {
	cin >> N;
	color.resize(N+1);
	tree.resize(N+1);
	for (int i = 1; i <= N-1; i++) {
		int a, b;
		cin >> a >> b;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	for (int i = 1; i <= N; i++) {
		que_t.push(P(tree[i].size(), i));
		que_a.push(P(tree[i].size(), i));
	}

	bool takahashi = true;
	int count = 0;
	while (!que_t.empty() && !que_a.empty()) {
		if (takahashi) {
			while (!que_t.empty() && color[que_t.top().second] != 0) {
				que_t.pop();
			}
			int ii = que_t.top().second; que_t.pop();
			color[ii] = 1;
		}
		else {
			while (!que_a.empty() && color[que_a.top().second] != 0) {
				que_a.pop();
			}
			int ii = que_a.top().second; que_a.pop();
			color[ii] = -1;
		}

		takahashi = !takahashi;
		if (++count >= N) break;
	}

	if (win_takahashi())
		cout << "First" << endl;
	else
		cout << "Second" << endl;

}

