  for(int i=0;i<n-1;++i) {
    int a, b; cin >> a >> b;
    a--; b--;
    tr[a].push_back(b);
    tr[b].push_back(a);
  }

  v.resize(n);
  dfs(0, -1, 0, tr);
  HopcroftKarp match(id1, id2);
  id1 = 0, id2 = 0;
  dfs2(0, -1, 0, tr, match);

  int bm = match.bipartite_matching();
  //cout << bm << endl;

  if(n % 2 == 0 && bm == n/2) {
    cout << "Second" << endl;
  } else {
    cout << "First" << endl;
  }
}

