map<PP, int> R;

int cal(int a, int b) {
	PP p = make_pair(a, b);
	if (R.find(p) != R.end()) return R[p];
	if (G[b].size() > 2) {
		R[p] = -1;
		return -1;
	}
	if (G[b].size() == 1) {
		R[p] = 1;
		return 1;
	}
	int c = G[b][0] + G[b][1] - a;
	for (int i = 0;i < G[c].size();i++) {
		if (G[c][i] == b) continue;
		if (cal(c, G[c][i]) == 1) {
			R[p] = 1;
			return 1;
		}
	}
	R[p] = -1;
	return -1;
}

