const int MAXN=100005;
int n,col[MAXN],Ok;
vector<int>P[MAXN];
void dfs(int u,int fa){
	int cnt=0,p=0;
	int size=P[u].size();
	for(int i=0;i<size;i++){
		int v=P[u][i];
		if(v==fa)continue;
		dfs(v,u);
		if(P[v].size()==1)
			cnt++,p=v;
	}
	if(cnt>=2)Ok=1;
	if(cnt==1){
		col[u]=1;
		col[p]=-1;
	}
}
int main(){
	scanf("%d",&n);
	for(int i=1,u,v;i<n;i++){
		scanf("%d%d",&u,&v);
		P[u].push_back(v);
		P[v].push_back(u);
	}
	col[0]=1;
	P[0].push_back(1);
	P[1].push_back(0);
	dfs(1,0);
	for(int i=1;i<=n;i++){
		int cnt=0;
		int size=P[i].size();
		if(col[i]==-1)continue;
		for(int j=0;j<size;j++)
			if(col[P[i][j]]==1)
				cnt++;
		if(cnt==size)Ok=1;
	}
	if(Ok)printf("First\n");
	else printf("Second\n");
}

