inline void $(int u, int v){
    next[tot] = head[u];to[tot] = v;head[u] = tot++;
    next[tot] = head[v];to[tot] = u;head[v] = tot++;
}
int dp(int x, int fa){
    int cnt = 0;
    for(int i = head[x];~i;i = next[i]){
        if(to[i] == fa)continue;
        cnt += dp(to[i], x);
        if(cnt >= 2)puts("First"), exit(0);
    }
    return !cnt;
}
