#include <bits/stdc++.h>
#define FOR(i, m, n) for (int i = (m); i < (n); i++)
#define REP(i, n) FOR(i, 0, n)
#define ALL(x) (x).begin(), (x).end()
using namespace std;
using ll = long long int;

int main (void) {
  int N;
  cin >> N;
  vector<set<int>> graph(N);
  vector<pair<int, int>> connect(N);
  REP(i, N) {
    connect[i] = make_pair(0, i);
  }
  vector<int> color(N);
  // 0: empty
  // 1: takahashi
  // 2: aoki
  REP(i, N - 1) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    connect[a].first++;
    connect[b].first++;
    graph[a].insert(b);
    graph[b].insert(b);
  }
  sort(ALL(connect), greater<pair<int, int>>());
  // REP(i, N) {
  //   cout << connect[i].second << ":" << connect[i].first << endl;
  // }
  int takahashi = 0;
  REP(turn, N) {
    if (turn % 2 == 0) { // takahashi
      while (color[connect[takahashi].second] != 0) {
        takahashi++;
      }
      color[connect[takahashi].second] = 1;
    } else { //aoki
      bool nuri = false;
      REP(i, N) {
        if (color[i] == 1) {
          for (const auto& next : graph[i]) {
            if (color[next] == 0) {
              color[next] = 2;
              nuri = true;
            }
          }
        }
        if (nuri) break;
      }
      if (!nuri) {
        REP(i, N) {
          if (color[i] == 0) {
            color[i] = 2;
            break;
          }
        }
      }
    }
  }
  vector<int> target;
  REP(i, N) {
    if (color[i] == 2) {
      for (const auto& next : graph[i]) {
        target.push_back(next);
      }
    }
  }
  for (const auto& t : target) {
    color[t] = 2;
  }
  REP(i, N) {
    if (color[i] == 1) {
      cout << "First" << endl;
      return 0;
    }
  }
  cout << "Second" << endl;
  return 0;
}

