void smain() {

    int n;
    cin >> n;
    fori (_, n - 1) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vi leafs;
    for (int v = 1; v <= n; ++v) {
        deg[v] = g[v].size();
        if (g[v].size() == 1) {
            leafs.push_back(v);
            used[v] = true;
        }
    }
    if (leafs.size() == 2 && count(ALL(g[leafs[0]]), leafs[1])) {
        cout << "Second";
        return;
    }
    while (leafs.size()) {
        watch(leafs);

        vi white_leafs;
        for (int v : leafs) {
            for (int to : g[v]) {
                deg[to]--;
                if (!used[to]) {
                    used[to] = true;
                    white_leafs.push_back(to);
                }
            }
        }
        if (white_leafs.size() < leafs.size()) {
            cout << "First";
            return;
