	for(auto i : g[v])
		if(i!=pr) dfs(i, v), deg[v]++;
	ord.pb(v);
}
bool efs(int v, int p) {
	bool win = deg[v]==0&&v==p;
	int c = 0;
	for(auto i : g[v])
		if(i!=p&&!rem[i]) win |= efs(i, v), c += deg[i]==0;
	if(c>1) win = 1;
	return win;
}
