void make_edgelist(const V<t2> &srclist, V<ll> edgelist[])
{
    for (auto src : srclist) {
        ll a = get<0>(src);
        ll b = get<1>(src);
        edgelist[a].pb(b);
        edgelist[b].pb(a);
    }
}



void make_parental_relation(const V<ll> edgelist[], ll root, ll n,
                            ll parents[], V<ll> children[], ll levels[])
{
    queue<ll> q;
    bool checked[n+1];

    memset(checked, 0, sizeof(checked));

    q.push(root);
    checked[root] = true;
    parents[root] = root;
    levels[root] = 0LL;

    for ( ; !(q.empty()); ) {
        ll now = q.front(); q.pop();
        for (auto next : edgelist[now]) {
            if (checked[next]) continue;
            q.push(next);
            checked[next] = true;
            parents[next] = now;
            children[now].pb(next);
            levels[next] = levels[now] + 1LL;
        }
    }
}




void _main()
{
    ll n; llin(n);
    V<t2> uvlist; llinl2(uvlist, n-1);

    if (n == 2) {
        cout << "Second" << endl;
        return;
    }

    ll digs[100005] = {};
    for (auto uv : uvlist) {
        ll u = get<0>(uv);
        ll v = get<1>(uv);
        digs[u]++;
        digs[v]++;
    }

    ll root = -1;
    srep (v, 1, n+1) if (digs[v] > 1) {
        root = v;
        break;
    }

    assert(root > 0);
    debug_printf("---- root=%lld\n", root);

    S V<ll> edgelist[10005];
    make_edgelist(uvlist, edgelist);

    S ll parents[100005];
    S V<ll> children[100005];
    S ll levels[100005];
    make_parental_relation(edgelist, root, n, parents, children, levels);

    S ll ccnts[100005];
    srep (v, 1, n+1) ccnts[v] = children[v].size();

    S V<ll> saved[100005];

    queue<t2> q;
    srep (v, 1, n+1) if (!ccnts[v]) q.push(t2(v, 0));

    while (q.size()) {
        auto item = q.front(); q.pop();
        ll v = get<0>(item);
        ll chain = get<1>(item);
        ll pv = parents[v];
        if (v == pv) continue;
        ccnts[pv]--;
        saved[pv].pb(chain+1LL);
        if (!ccnts[pv]) {
            if (children[pv].size() == 1) {
                q.push(t2(pv, saved[pv][0]));
            }
            else {
                ll ocnt = 0;
                for (auto cc : saved[pv]) if (cc & 1LL) ocnt++;
                if (ocnt >= 2) {
                    debug_printf("---- first v=%lld pv=%lld\n", v, pv);
                    cout << "First" << endl;
                    return;
                }
                if (ocnt) {
                    q.push(t2(pv, 1));
                }
                else {
                    q.push(t2(pv, 0));
                }
            }
        }
    }

    cout << "Second" << endl;
}

