int dp [100001] [2],dp2 [100001] [2];

void dfs(int curr,int prev)
{
	bool leaf = true;
	for(const auto& it : edge [curr]) if(it != prev){
		dfs(it,curr);
		dp [curr] [0] += dp [it] [1];
		dp [curr] [1] += dp [it] [0];
		leaf = false;
	}
	if(leaf){
		dp [curr] [0] = 1;
	}
}

void dfs2(int curr,int prev)
{
	if(prev != -1){
		dp2 [curr] [0] += dp [prev] [1] + dp2 [prev] [1];
		dp2 [curr] [1] += dp [prev] [0] + dp2 [prev] [0];
		dp2 [curr] [0] -= dp [curr] [0];
		dp2 [curr] [1] -= dp [curr] [1];
	}
	else{
		if(edge [curr].size() == 1){
			dp2 [curr] [0]++;
		}
	}
	for(const auto& it : edge [curr]) if(it != prev){
		dfs2(it,curr);
	}
}

int main()
{
	scanf("%d",&N);
	FOR(i,0,N - 1){
		int u,v;
		scanf("%d%d",&u,&v);
		edge [u].push_back(v);
		edge [v].push_back(u);
	}

	bool ans = false;
	FOR(i,1,N + 1){
		int cntLeaf = 0;
		for(const auto& it : edge [i]){
			cntLeaf += edge [it].size() == 1;
		}
		if(cntLeaf >= 2){
			ans = true;
			break;
		}
	}

	dfs(1,-1);
	dfs2(1,-1);
	FOR(i,1,N + 1){
		if(dp [i] [1] == 0 && dp2 [i] [1] == 0){
			ans = true;
		}
	}
	printf("%s\n",ans ? "First" : "Second");

	return 0;
}

