void dfs(int pos, int pre, int dist) {
	if (dist % 2 == 1) {
		cnt[pos]++;
		if (cnt[pos] == 2) ret = true;
	}
	if (dist == 2) d2[pos]++;
	int deg = 0, p = -1;
