	ios_base::sync_with_stdio(false);

	cin >> n;

	for(int i = 0; i < n - 1; i++){
		int a, b;
		cin >> a >> b;
		adj2[a].push_back(b);
		adj2[b].push_back(a);
	}

	prep(1, 0);
	dfs(1, 0);

	cout << (dp[0][1] ? "Second" : "First") << endl;

	return 0;
}

