        ch = getchar();
    }
    if (ch == '-') minus1 = true; else result = ch-'0';
    while (true) {
        ch = getchar();
        if (ch < '0' || ch > '9') break;
        result = result*10 + (ch - '0');
    }
    if (minus1)
        return -result;
    else
        return result;
}

int kek[MAXN];
vector <int> g[MAXN];

int cnt[MAXN];-

void dfs(int v, int par) {
    cnt[g[v].size()] ++;
    for (int i : g[v]) {
        if (g[i].size() == 1) {
            kek[v] ++;
        }
        if (i == par) continue;
        dfs(i, v);
    }
}

