        if (kek[i] >= 2) {
            cout << "First";
            return 0;
        }
    }
    if (cnt[1] == 2 && cnt[2] == n - 2 && n % 2) {
        cout << "First";
        return 0;
    }
    cout << "Second";
    return 0;
}

