void solve(){
	queue<int>q;
	for(int i=0;i<n;i++){
		cnt[i]=v[i].size();
		if(cnt[i]==1){
			vis[i]=2;
			q.push(i);
		}
	}
	while(!q.empty()){
		int p=q.front();
		q.pop();
		if(cnt[p]==0){
			cout<<"First"<<endl;
			return;
		}
		cnt[p]--;
		for(int u:v[p]){
			if(vis[u]==1){
				cout<<"First"<<endl;
				return;
			}
			if(vis[u])continue;
			vis[u]=1;
			cnt[u]--;
			if(cnt[u]==1){
				for(int l:v[u]){
					if(!vis[l]){
						vis[l]=2;
						q.push(l);
					}
				}
			}
		}
	}
	for(int i=0;i<n;i++){
		if(vis[i]==2){
			for(int u:v[i]){
				if(vis[u]==1)vis[u]=3;
			}
		}
	}
	for(int i=0;i<n;i++){
		if(vis[i]==1){
			cout<<"First"<<endl;
			return;
		}
	}
	cout<<"Second"<<endl;
	return;
}

