const int N=1e5+100;
vi g[N];
int dp[N],ans[N];

void dfs(int v, int pr){
    int w=0,b=0,cnt=0,l=0;
    for(auto p:g[v]){
        if(p==pr)
            continue;
        dfs(p,v);
        w+=(dp[p]==1);
        b+=(dp[p]==0);
        l+=(dp[p]==3);
        cnt++;
    }
    if(cnt==0){
        dp[v]=3;
    }else if(w>=1){
        dp[v]=1;
    } else if(l>=2){
        dp[v]=1;
    }
}

void dfs(int v,int pr,int kek){
    int w=(kek==1),b=(kek==0),l=(kek==3);
    for(auto p:g[v]){
        if(p==pr)
            continue;
        w+=(dp[p]==1);
        b+=(dp[p]==0);
        l+=(dp[p]==3);
    }
    if(w>=1||l>=2){
        ans[v]=1;
    }
    for(auto p:g[v]){
        if(p==pr)
            continue;
        if(g[v].size()==1)
            dfs(p,v,3);
        else{
            w-=(dp[p]==1);
            b-=(dp[p]==0);
            l-=(dp[p]==3);
            if(w>=1||l>=2){
                dfs(p,v,1);
            }else{
                dfs(p,v,0);
            }
            w+=(dp[p]==1);
            b+=(dp[p]==0);
            l+=(dp[p]==3);
        }
    }

}

