		static std::uint64_t mod;
		dmod(std::uint64_t v = 0) :val(v%mod)
		{

		}
		dmod& operator+=(dmod const& rhs)
		{
			val += rhs.val;
			val %= mod;
			return *this;
		}
		dmod& operator-=(dmod const& rhs)
		{
			val += mod - rhs.val;
			val %= mod;
			return *this;
		}
		dmod& operator*=(dmod const& rhs)
		{
			val *= rhs.val;
			val %= mod;
			return *this;
		}
	};
	template<class Tag>dmod<Tag> operator+(dmod<Tag> lhs, dmod<Tag> const& rhs)
	{
		return lhs += rhs;
	}
	template<class Tag>dmod<Tag> operator-(dmod<Tag> lhs, dmod<Tag> const& rhs)
	{
		return lhs -= rhs;
	}
	template<class Tag>dmod<Tag> operator*(dmod<Tag> lhs, dmod<Tag> const& rhs)
	{
		return lhs *= rhs;
	}
