bool check(std::vector<std::set<int>>const& edge, int now, int prev, int size)
{
	if (edge[now].size() == 1 && *edge[now].begin == prev)
	{
		return size % 2 == 1;
	}
	for (auto const& v : edge[now])
	{
		if (v == prev)
		{
			continue;
		}
		if (check(edge, v, now, size + 1))
			return true;
	}
	return false;
}

