#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
template<typename T> using Graph = vector<vector<T>>;

#define REP(i, a, b) for (int i = (int)(a); i < (int)(b); i++)
#define rep(i, a) REP(i, 0, a)
#define EACH(i, a) for (auto i: a)
#define ITR(x, a) for (__typeof(a.begin()) x = a.begin(); x != a.end(); x++)
#define ALL(a) (a.begin()), (a.end())
#define HAS(a, x) (a.find(x) != a.end())
#define endl '\n'

int N;
vector<int> tree[100005];
int a[100005], b[100005];
int odd[100005], cnt[100005], reafs[100005];

void dfs(int u, int d) {
  odd[u] = d % 2;
  for (auto v: tree[u]) {
    if (odd[v] != -1) continue;
    dfs(v, d + 1);
  }
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N;
  if (N == 2) {
    cout << "Second" << endl;
    return 0;
  }

  rep(i, N - 1) {
    cin >> a[i] >> b[i];
    a[i]--; b[i]--;
    tree[a[i]].push_back(b[i]);
    tree[b[i]].push_back(a[i]);
  }

 rep(i, N - 1) cnt[a[i]]++, cnt[b[i]]++;

  set<int> is_reaf;
  rep(i, N) if (cnt[i] == 1) is_reaf.insert(i);

  rep(i, N - 1) {
    if (HAS(is_reaf, a[i])) reafs[b[i]]++;
    if (HAS(is_reaf, b[i])) reafs[a[i]]++;
  }
  bool first = false;
  rep(i, N) if (reafs[i] >= 2) first = true;


  rep(i, N) odd[i] = -1;
  dfs(0, 0);
  int zero = 0;
  rep(i, N) if (odd[i] == 0) zero++;

  first |= (N - zero)%2 != zero%2;

  cout << (first ? "First":"Second") << endl;

  return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int maxn=2e5+10;

int n,deg[maxn];
int tote,FIR[maxn],TO[maxn],NEXT[maxn];
bool vis[maxn];
queue<int> q;

void addedge(int u,int v)
{
	TO[++tote]=v;
	NEXT[tote]=FIR[u];
	FIR[u]=tote;
}

int main()
{
#ifdef h10
	freopen("D.in","r",stdin);
	freopen("D.out","w",stdout);
#endif
	int i,u,v;
	scanf("%d",&n);
	if (n&1) {puts("First"); return 0;}
	for (i=1;i<n;i++)
	{
		scanf("%d%d",&u,&v);
		addedge(u,v);
		addedge(v,u);
		deg[u]++; deg[v]++;
	}
	for (i=1;i<=n;i++)
		if (deg[i]==1) q.push(i);
	vis[0]=1;
	for (i=1;i<=n>>1;i++)
	{
		u=v=0;
		while (vis[u]) u=q.front(),q.pop();
		for (int p=FIR[u];p;p=NEXT[p])
		{
			v=TO[p];
			if (!vis[v]) break;
		}
		if (vis[v]) {puts("First"); return 0;}
		vis[u]=vis[v]=1;
		for (int p=FIR[v];p;p=NEXT[p])
		{
			u=TO[p];
			if (!vis[u]&&(--deg[u])==1) q.push(u);
		}
	}
	puts("Second");
}

