const int maxn = 1e5 + 58;
int sz[maxn];
vector <int> adj[maxn];

bool dfs(int v, int p = -1) {
	bool f = 1;
	int t = 0;
	sz[v] = 1;
	for (auto u: adj[v]) {
		if (u != p) {
			f = dfs(u, v) & f;
			sz[v] += sz[u];
			if (sz[u] % 2) t++;
		}
	}
	return f && (t <= 1);
}

