// dp[u][i] -- is there a perf. matching in sub of u
// with u matched up if i is 1

void dfs (int u, int p) {
  int c00 = 0;
  int c01 = 0;
  int c10 = 0;
  int c11 = 0;
  for (int nxt : adj[u]) {
    if (nxt != p) {
      dfs(nxt, u);

      if (dp[nxt][0]) {
        if (dp[nxt][1]) {
          c11++;
        } else {
          c10++;
        }
      } else {
        if (dp[nxt][1]) {
          c01++;
        } else {
          c00++;
        }
      }
    }
  }

  if (c00 == 0) {
    // determine dp[u][1]
    dp[u][1] = (c01 == 0);

    // determine dp[u][0]
    dp[u][0] = (c01 <= 1) && (c01 + c11 > 0);
  }
}

