struct cmp { bool operator() (const int &, const int &) const; };

int n;
set <int> g[N];
bool mark[N];

set <int, cmp> heap;

int main() {
	cin >> n;
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		g[a].insert(b);
		g[b].insert(a);
	}

	for (int i = 0; i < n; i++) 
		heap.insert(i);

	while (!heap.empty()) {
		int v = *heap.begin();
		heap.erase(heap.begin());

		if (mark[v])
			continue;
		mark[v] = true;

		// cerr << "V: " << v + 1 << endl;; 
		assert(g[v].size() == 1);
		int pv = *g[v].begin();
		g[pv].erase(v);
		// cerr << "Pv: " << pv + 1 << endl;
		for (int u: g[pv]) {
			heap.erase(u);
			g[u].erase(pv);
			if (g[u].empty()) {
				// cerr << "CON: " << u + 1 << endl;
				cout << "First" << endl;
				return 0;
			}
			heap.insert(u);
		}
		mark[pv] = true;
		// cerr << v + 1 << ' ' << pv + 1 << endl;
		heap.erase(pv);
	}

	cout << "Second" << endl;
}


bool cmp::operator() (const int &v, const int &u) const {
	return g[v].size() != g[u].size()? g[v].size() < g[u].size() : v < u;
}


