    function<void(int, int)> rec = [&] (int curr, int prev) {
      vis[curr] = true;
      int cnt = 0;
      each (next, g[curr]) {
        if (next == prev) continue;
        if (vis[next]) continue;
        if (g[next].size() == 1) ++cnt;
        rec(next, curr);
      }
      if (2 <= cnt) throw "";
      return ;
    };

    for (int i = 0; i < n; ++i) {
      if (1 < g[i].size()) {
        try { rec(i, -1); } catch (const char* s) { f = true; }
      }
    }


    cout << (f ? "First" : "Second") << endl;
  }

  return 0;
}


