    for(int i = 1; i <= n; i++) {
        int cnt = 0;
        for(auto x: g[i]) {
            if(deg[x] == 1)
                cnt++;
        }
        if(cnt >= 2) {
            cout << "First\n";
            return 0;
        }
    }
    set<point> s;
    for(int i = 1; i <= n; i++) {
        s.insert({ i });
    }
    while(!s.empty()) {
        auto it = s.begin();
        int v = it->v;
        if(deg[v] > 1 || deg[g[v][0]] != 2)
            break;
        s.erase({ v });
        del[v] = 1;
        for (auto u: g[v]) {
            if(del[u]) continue;
            for(auto x: g[u]) {
                if(del[x]) continue;
                if(x != v) {
                    s.erase({ x });
                    deg[x]--;
                    s.insert({ x });
                }
            }
            del[u] = 1;
            s.erase({ u });
        }
    }
    for(auto it: s) {
        int i = it.v;
        int cnt = 0;
        for(auto x: g[i]) {
            if(del[x]) continue;
            if(deg[x] == 1)
                cnt++;
        }
        if(cnt >= 2) {
            cout << "First\n";
            return 0;
        }
    }
    cout << "Second\n";
    return 0;
}

