int inEdge[MAX_N];

bool used[MAX_N];

bool dfs(int pos, int cnt = 0)
{
  used[pos] = true;
  int C = 0;
  for (int i = 0; i < Edge[pos].size(); i++) {
    int next = Edge[pos][i];
    if(used[next]){
      continue;
    }
    C++;
    if(dfs(next, cnt+1)){
      return true;
    }
    break;
  }

  if(C == 0 && cnt%2 == 0){
    return true;
  }
  else if(C == 0 && cnt%2 == 1){
    return false;
  }
  else{
    return false;
  }

}

bool ans = false;

//0 1
pair<int, int> solve(int pos, int pre = -1)
{
  bool check = false;

  int l = 0, r = 0;

  for (int i = 0; i < Edge[pos].size(); i++) {
    int next = Edge[pos][i];
    if(next == pre){
      continue;
    }
    check = true;

    pair<int, int> p = solve(next, pos);

    l += p.first;
    r += p.second;
  }

  if(!check){
    return make_pair(0, 1);
  }

  if(r >= 2 || l >= 2){
    ans = true;
    return make_pair(0, 0);
  }

  int retR = 0, retL = 0;

  if(r > 0){
    retL = 1;
  }
  if(l > 0){
    retR = 1;
  }

  return make_pair(retL, retR);
}

