{
  CC[pos] = color;
  color = (color+1) % 2;

  for (int i = 0; i < Edge[pos].size(); i++) {
    int next = Edge[pos][i];
    if(next == pre){
      continue;
    }
    nuli(next, pos, color);
  }

  return;
}

