}

int main()
{
  cin >> N;
  for (int i = 0; i < N-1; i++) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    Edge[a].push_back(b);
    Edge[b].push_back(a);
    inEdge[a]++; inEdge[b]++;
  }

  queue<int> que;
  for (int i = 0; i < N; i++) {
    if(inEdge[i] == 1){
      que.push(i);
    }
  }

  memset(used, 0, sizeof(used));
  while(que.size()){
    int pos = que.front();
    que.pop();

    if(used[pos]){
      continue;
    }

    bool ok = false;
    for (int i = 0; i < Edge[pos].size(); i++) {
      int next = Edge[pos][i];
      if(used[next]){
        continue;
      }
      else{
        used[pos] = used[next] = true;
        for (int j = 0; j < Edge[pos].size(); j++) {
          int tmp = Edge[pos][j];
          if(tmp != next && !used[tmp]){
            que.push(tmp);
          }
        }

        for (int j = 0; j < Edge[next].size(); j++) {
          int tmp = Edge[next][j];
          if(tmp != pos && !used[tmp]){
            que.push(tmp);
          }
        }

        ok = true;
        break;
      }
    }

    if(!ok){
      cout << "First" << endl;
      return 0;
    }
  }

  cout << "Second" << endl;

  return 0;
}

