    else
        return first.v < second.v;
}

int main() {
    //ios_base::sync_with_stdio(false);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n;
    cin >> n;
    if(n & 1) {
        cout << "First\n";
        return 0;
    }
    for(int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        g[a].insert(b);
        g[b].insert(a);
        deg[a]++;
        deg[b]++;
    }
    for(int i = 1; i <= n; i++) {
        int cnt = 0;
        for(auto x: g[i]) {
            if(deg[x] == 1)
                cnt++;
        }
        if(cnt >= 2) {
            cout << "First\n";
            return 0;
        }
    }
    set<point> s;
    for(int i = 1; i <= n; i++) {
        s.insert({ i });
    }
    while(!s.empty()) {
        auto it = s.begin();
        int v = it->v;
        if(deg[v] > 1 || deg[*g[v].begin()] != 2)
            break;
        s.erase({ v });
        g[*g[v].begin()].erase(v);
        s.erase({ *g[v].begin() });
        for (auto u: g[v]) {
            for(auto x: g[u]) {
                s.erase({ x });
                deg[x]--;
                s.insert({ x });
                g[x].erase(u);
                break;
            }
        }
    }
    for(auto it: s) {
        int i = it.v;
        int cnt = 0;
        for(auto x: g[i]) {
            if(deg[x] == 1)
                cnt++;
        }
        if(cnt >= 2) {
            cout << "First\n";
            return 0;
        }
    }
    cout << "Second\n";
    return 0;
}

