#include<bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
bool dp[N], up[N], ok[N] = {true};
bool child[N], L[N], R[N];
vector<int> adj[N];
int n, par[N];

void dfs1(int u) {
	child[u] = true;
	for (int i = 0; i < adj[u].size(); i++)
		if (adj[u][i] ^ par[u]) {
			par[adj[u][i]] = u;
			dfs1(adj[u][i]);
			child[u] &= dp[adj[u][i]];
			dp[u] |= child[adj[u][i]];
		}
	L[0] = R[adj[u].size() - 1] = false;
	for (int i = 0; i < adj[u].size(); i++)
		L[i + 1] = R[i - 1] = (adj[u][i] ^ par[u]? child[adj[u][i]]: ok[par[u]]);
	for (int i = 1; i < adj[u].size(); i++)
		L[i] |= L[i - 1], R[adj[u].size() - i - 1] |= R[adj[u].size() - i];
	for (int i = 0; i < adj[u].size(); i++)
		if (adj[u][i] ^ par[u])
			ok[adj[u][i]] = (L[i] || R[i]);
}

void dfs2(int u) {
	L[0] = R[adj[u].size() - 1] = true;
	for (int i = 0; i < adj[u].size(); i++)
		L[i + 1] = (L[i] && (adj[u][i] ^ par[u]? dp[adj[u][i]]: ok[u]));
	for (int i = adj[u].size() - 1; i; i--)
		R[i - 1] = (R[i] && (adj[u][i] ^ par[u]? dp[adj[u][i]]: ok[u]));
	for (int i = 0; i < adj[u].size(); i++)
		if (adj[u][i] ^ par[u])
			up[adj[u][i]] = (L[i] && R[i]);
	for (auto v: adj[u])
		if (v ^ par[u])
			dfs2(v);
}

inline void readInput() {
	cin >> n;
	for (int i = 1; i < n; i++) {
		int u, v;
		cin >> u >> v;

		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

inline void solve() {
	dfs1(0), dfs2(0);
	for (int i = 0; i < n; i++)
		if (child[i] && (par[i] == i || up[par[i]])) {
			cout << "First\n";
			exit(0);
		}
	cout << "Second\n";
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	readInput(), solve();
	return 0;
}

