std::vector<int> conn[100001];
int depth[100001];

int main() {
  int N, a, b;
  scanf("%d", &N);

  for (int i = 0; i < N - 1; i++) {
    scanf("%d %d", &a, &b);
    conn[a].push_back(b);
    conn[b].push_back(a);
  }

  for (int i = 1; i <= N; i++) {
    if (conn[i].size() == 1) conn[0].push_back(i);
    depth[i] = -1;
  }
  depth[0] = 0;

  std::queue<int> q;
  q.push(0);
  while(!q.empty()) {
    int node = q.front();
    int next_depth = depth[node] + 1;
    q.pop();

    for (int i = 0, ilim = conn[node].size(); i < ilim; i++) {
      int next_node = conn[node][i];
      if (depth[next_node] != -1) continue;
      depth[next_node] = next_depth;
      q.push(next_node);
    }
  }

  int ok = 0;
  for (int i = 1; i <= N; i++) {
    if (depth[i] == 2) {
      int cnt = 0;
      for (int j = 0; j < conn[i].size(); j++) {
	if (depth[conn[i][j]] == 1) cnt++;
      }
      if (cnt >= 2) ok = 1;
    }
  }
  if (ok == 1) 
    printf("First\n");
  else 
    printf("Second\n");

  return 0;
}

