#define LLINF 2000000000000000000LL //2e18
#define SIZE 100010

vector<int> way[SIZE];

pair<int,int> dfs(int now, int back=-1){
  int t = 0;
  int s = 0;

  for(int i=0;i<way[now].size();i++){
    if(way[now][i] == back) continue;
    pair<int,int> p = dfs(way[now][i],now);

    t += p.first;
    s += p.second;    
  }

  if(s == 1 && t <= 1){
    return {1-t, s};
  }

  if(t <= 1 && s <= 1){
    return {1-t, s};
  }

  if(s == 0 && t == 2){
    return {1,1};
  }

  return {INF,INF};
}

