const int Maxn=100000;
int n;
int head[Maxn+5],arrive[Maxn<<1|5],nxt[Maxn<<1|5],tot;
void add_edge(int from,int to){
	arrive[++tot]=to;
	nxt[tot]=head[from];
	head[from]=tot;
}
int deg[Maxn+5];
int root;
int check_dfs(int u,int fa){
	int sum_1=0,sum_2=0;
	for(int i=head[u];i;i=nxt[i]){
		int v=arrive[i];
		if(v==fa){
			continue;
		}
		int tmp=check_dfs(v,u);
		if(tmp==1){
			return 1;
		}
		if(tmp==2){
			sum_1++;
		}
		if(tmp==3){
			sum_2++;
		}
	}
	if(sum_1>=2){
		return 1;
	}
	if(sum_1==1){
		return 3;
	}
	return 2;
}
