	clock_t begin=clock(),end;
	scanf("%d",&n);
	for(int i=1;i<n;i++){
		int u,v;
		scanf("%d%d",&u,&v);
		add_edge(u,v);
		add_edge(v,u);
		deg[u]++,deg[v]++;
	}
	if(check_dfs(1,0)==1){
		puts("First");
	}
	else{
		puts("Second");
	}
	return 0;;
	int last=0;
	while(1){
		end=clock();
		if((end-begin)*1.0/CLOCKS_PER_SEC>0.9){
			break;
		}
		root=-1;
		for(int i=last+1;i<=n;i++){
			if(deg[i]!=1){
				root=i;
				break;
			}
		}
		if(root==-1){
			break;
		}
		last=root;
		if(check_dfs(root,0)==1){
			puts("First");
			return 0;
		}
	}
	puts("Second");
	return 0;
}

