void dfs(int v, int dis) {
	mark[v] = true;
	if((int)g[v].size() == 1) {
		if(dis % 2 != mod) {
			change++;
			mod = dis % 2;
		}
	}
	for(int i = 0; i < g[v].size(); i++) {
		if(!mark[g[v][i]]) {
			dfs(g[v][i], dis + 1);
		}
	}
}
bool check() {
	dfs(0, 0);
	if(mod == 0 && change <= 1) {
		return true;
	}
	memset(mark, 0, sizeof mark);
	change = 0;
	mod = 0;
	dfs(g[0][0], 0);
	if(mod == 0 && change <= 1) {
		return true;
	}
	return false;
}

