void Build(int x, int y)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	deg[x]++;
}

void Init()
{
	all = -1; memset(last, -1, sizeof(last));
	memset(deg, 0, sizeof(deg));
	for (int i = 1; i <= n - 1; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		Build(u, v); Build(v, u);
	}
}

void Dfs(int orig, int x, int fa, int dep)
{
	int ed = last[x], dr, cnt = 0;
	if (x != orig && deg[x] == 1 && (dep & 1)) flag = true;
	while (ed != -1) {
		dr = other[ed];
		if (dr != fa) Dfs(orig, dr, x, dep + 1);
		ed = pre[ed];
	}
}

void Solve()
{
	flag = false;
	for (int i = 1; i <= n; i++) 
		if (deg[i] == 1) {
			Dfs(i, i, 0, 1);
			break;
		}
	if (flag) printf("First\n");
		else printf("Second\n");
}

