bool check(std::vector<std::set<int>>const& edge, int now, int prev, int size)
{
	if (edge[now].size() == 1)
	{
		return size % 2 == 1;
	}
	for (auto const& v : edge[now])
	{
		if (v == prev)
		{
			continue;
		}
		if (check(edge, v, now, size + 1))
			return true;
	}
	return false;
}

void Main()
{
	int N;
	std::cin >> N;
	std::vector<int> vec(N + 1, 0);
	std::vector<std::set<int>> edge(N + 1);
	for (int i = 0; i < N - 1; ++i)
	{
		int a, b;
		std::cin >> a >> b;
		if (vec[a] == 0)
		{
			vec[a] = b;
		}
		else
		{
			vec[a] = -1;
		}
		if (vec[b] == 0)
		{
			vec[b] = a;
		}
		else
		{
			vec[b] = -1;
		}
		edge[a].emplace(b);
		edge[b].emplace(a);
	}
	for (int i = 1; i < N; ++i)
	{
		if (vec[i] > 0)
		{
			if (check(edge, i, -1, 1))
			{
				std::cout << "First" << std::endl;
				return;
			}
		}
	}
	std::cout << "Second" << std::endl;
}

