void rEdge(int a, int b) {
    adj[a].erase(b), adj[b].erase(a);
}

void makePa(int x, int y) {
    pa[x] = pa[y] = 1;
    rEdge(x,y);
    for (int i: adj[y]) {
        rEdge(y,i);
        if (sz(adj[i]) == 1) todo.push(i);
    }
}

