    }

    FOR(i,1,N+1) if (sz(adj[i]) == 1) todo.push(i);
    while (sz(todo)) {
        int x = todo.front(); todo.pop();
        if (pa[x]) continue;
        if (sz(adj[x]) == 0) {
            cout << "First";
            exit(0);
        }
        int y = *adj[x].begin();
        makePa(x,y);
    }

    FOR(i,1,N+1) if (!pa[i]) {
        cout << "First";
        exit(0);
    }

    cout << "Second";
}

