int dp[N];
int dp2[N];
int leaf[N];
bool mark[N];

void dfs(int v)
{
	mark[v] = true;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (deg[u] == 1)
		{
			dp[v]++;
		}
		if (!mark[u])
		{
			dfs(u);
		}
	}
	if (deg[v] == 1)
	{
		leaf[v] = 1;
	}
	dp2[v] = 1;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		leaf[v] += leaf[u];
		dp2[v] += dp2[u];
	}

}

int main()
{
	cin >> n;
	for (int i = 0; i < n - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		graph[u - 1].push_back(v - 1);
		graph[v - 1].push_back(u - 1);
		deg[u - 1]++;
		deg[v - 1]++;
	}
	dfs(0);
	for (int i = 0; i < n; i++)
	{
		if (dp[i] > 1)
		{
			cout << "First";
			exit(0);
		}
		if (dp[i] == 0 && deg[i] != 1)
		{
			int cnt = 0;
			for (int j = 0; j < graph[i].size(); j++)
			{
				if (leaf[graph[i][j]] == 1 && dp2[graph[i][j]] % 2 == 0)
				{
					cnt++;
				}
			}
			if (cnt >= 2)
			{
				cout << "First";
				exit(0);
			}
		}
	}
	cout << "Second";



}

