bool dfs(int v) {
    if (used[v]) {
        return false;
    }
    used[v] = true;

    for (int u : G[v]) {
        if (match[u] < 0 || dfs(match[u])) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }

    return false;
}

int bipartite_matching() {
    int res = 0;
    memset(match, -1, sizeof(match));
    for (int v = 0; v < N; v++) {
        if (match[v] >= 0) {
            continue;
        }
        memset(used, 0, sizeof(used));
        if (dfs(v)) {
            res++;
        }
    }
    return res;
}


