#define debug(args...) //fprintf (stderr, args);

const int maxn = 1e5 + 10;

int n;
int sons[maxn];

int root = -1;
int deg[maxn];
vector <int> adj[maxn];
int leaf[maxn];

bool win = false;

void dfs (int v, int par)
{
	if (v != 1)
		--deg[v];

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

		if (u == par)
			continue;

		dfs (u, v);

		if (leaf[u])
			++sons[v];
	}

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

		if (u == par)
			continue;

		if (leaf[u] && sons[v] > 1)
		{
			debug ("node = %d\n", v);
			win = true;
		}
	}

	int degmax[2] = {-1, -1};
	int node[2] = {-1, -1};

	int cont = 0;

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

		if (u == par)
			continue;

		if (deg[u] > degmax[0])
		{
			degmax[1] = degmax[0];
			node[1] = node[0];

			node[0] = u;
			degmax[0] = deg[u];
		}
		else
			if (deg[u] > degmax[1])
			{
				degmax[1] = deg[u];
				node[1] = u;
			}
	}

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

		if (u == par)
			continue;

		int d = (node[0] == u) ? (degmax[1]) : (degmax[0]);

		if (d > 1)
			++cont;
	}

	if (cont > 1)
		win = true;

	if (!sons[v])
		leaf[v] = true;
}

int main ()
{
	scanf ("%d", &n);

	for (int i = 1; i <= n - 1; ++i)
	{
		int a, b;
		scanf ("%d %d", &a, &b);

		adj[a].push_back (b);
		adj[b].push_back (a);

		++deg[a];
		++deg[b];
	}

	for (int i = 1; i <= n; ++i)
		if (deg[i] > 1)
		{
			root = i;
			break;
		}

	if (root == -1)
	{
		printf ("Second\n");
		return 0;
	}

	dfs (root, -1);

	for (int i = 1; i <= n; ++i)
		debug ("%d ", leaf[i]);

	debug ("\n");

	if (win)
		printf ("First\n");
	else
		printf ("Second\n");

	return 0;
}

