bool solve() {
	int n = ri();

	Graph G(n);
	vi J(n);
	rep(i, n-1) {
		int u = ri() - 1;
		int v = ri() - 1;
		G[u].emplace_back(v);
		G[v].emplace_back(u);
		J[u]++;
		J[v]++;
	}

	if (n == 2) return false;

	int root = -1;
	rep(i, n) {
		if (J[i] != 1) {
			root = i;
			break;
		}
	}

	out(root);

	vi P(n);
	vi D(n, 1e9);
	D[root] = 0;
	{
		function<void(int, int)> dfs = [&](int cur, int pre) {
			P[cur] = pre;
			forr(nex, G[cur]) {
				if (nex.dst != pre) {
					D[nex.dst] = D[cur] + 1;
					dfs(nex.dst, cur);
				}
			}
		};
		dfs(root, -1);
	}

	priority_queue<pii> Q;
	rep(i, n) {
		if (J[i] == 1) {
			Q.emplace(D[i], i);
		}
	}


	vi U(n);

	while (sz(Q)) {
		int u = Q.top().snd;
		Q.pop();

		int p = P[u];
		out(u, p);

		if (u == root) return true;
		if (U[p]) return true;

		U[u] = U[p] = 1;

		int g = P[p];
		if (g != -1) {
			J[g]--;
			if (J[g] == 1 && g != root) {
				out(g);
				Q.emplace(D[g], g);
			}
		}
	}
	return false;
}

