using namespace std;

int connect_num[100001];
bool used[100001];
bool elem_sort(const int&x, const int&y) {
	return connect_num[x] < connect_num[y];
}


int main(void) {
	int N;
	cin >> N;

	if (N%2==1) {
		cout << "First" << endl;
		return 0;
	}

	vector <int> order;
	for (int i = 1; i <= N; i++) {
		connect_num[i] = 0;
		order.push_back(i);
	}

	vector <pair <int, int>> edge;
	for (int i = 1; i <= N-1; i++) {
		int a, b;
		cin >> a >> b;
		edge.push_back(make_pair(a, b));
		connect_num[a]++;
		connect_num[b]++;
		used[i] = false;
	}

	sort(order.begin(), order.end(), elem_sort);
	int vec_size = edge.size();

	bool win = false;
	for (int i = 0; i < N; i+=2) {
		int from = order.at(i);
		if (connect_num[from] == 0) {
			win = true;
			break;
		}
		int to;
		for (int j = 0; j < vec_size; j++) {
			if (used[j]) continue;
			bool found = false;
			if (edge.at(j).first == from) {
				to = edge.at(j).second;
				found = true;
			}
			if (edge.at(j).second == from) {
				to = edge.at(j).first;
				found = true;
			}
			if (found) {
				used[j] = true;
				for (int k = 0; k < vec_size; k++) {
					if (used[k]) continue;
					if (edge.at(k).first == to) {
						connect_num[edge.at(k).second]--;
						used[k] = true;
					}
					else if (edge.at(k).second == to) {
						connect_num[edge.at(k).first]--;
						used[k] = true;
					}
				}
				connect_num[from] = -1;
				connect_num[to] = -1;
				break;
			}
		}
		sort(order.begin(), order.end(), elem_sort);
	}
	if (win) {
		cout << "First" << endl;
	} else {
		cout << "Second" << endl;
	}
	return 0;
}

