        cin >> N;
        A.resize(N-1); B.resize(N-1);
        E.resize(N);
        rep(i, N-1) {
            cin >> A[i] >> B[i];
            A[i]--; B[i]--;
            E[A[i]].push_back(B[i]);
            E[B[i]].push_back(A[i]);
        }
        rep(i, N) {
            int cnt = 0;
            for(int nxt : E[i]) {
                cnt += E[nxt].size() == 1;                
            }
            if(cnt >= 2) {
                cout << "First" << endl;
                return 0;
            }
        }
        cout << "Second" << endl;
        return 0;
        int root = -1;
        rep(i, N) {
            if(E[i].size() > 1) {
                root = i;
                break;
            }
        }
        cout << (root >= 0 and dfs(root, -1) ? "First" : "Second") << endl;
        return 0;
    }
};

