const int maxn=2e5+1e2;

struct edge
{
	int v,next;
}e[maxn*2];

int head[maxn],cnt=0,col[maxn];

void insert(int t1,int t2)
{
	e[++cnt].v=t2;
	e[cnt].next=head[t1];
	head[t1]=cnt;
}

int a[maxn];

int main()
{
	int n;
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int t1,t2;
		scanf("%d%d",&t1,&t2);
		insert(t1,t2);
		insert(t2,t1);
		a[t1]++;
		a[t2]++;
	}
	bool flag=false;
	for(int i=1;i<=n;i++)
	{
		int re=0;
		for(int j=head[i];j;j=e[j].next)
		{
			if(a[e[j].v]==1)re++;
		}
		if(re>=2)flag=true;
	}
	for(int i=1;i<=n;i++)
	{
		if(a[i]==1)
		{
			for(int j=head[i];j;j=e[j].next)
			{
				col[e[j].v]=1;
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		if(col[i]||a[i]==1)continue;
		bool have=true;
		for(int j=head[i];j;j=e[j].next)
		{
			if(!col[e[j].v])have=false;
		}
		if(have)
		{
			flag=true;
		}
	}
	if(flag)printf("First\n");
	else printf("Second\n");
	return 0;
}

