  rep(i,0,n-1){
    int a,b;cin>>a>>b;
    --a;--b;
    e[a].pb(b);
    e[b].pb(a);
    deg[a]++;
    deg[b]++;
  }

  queue<int> q;
  V<int> flag(n,0);
  rep(i,0,n){
    if(deg[i]==1){
      q.push(i);
      q.push(0);
      flag[i]=1;
    }


    while(q.size()){
      int now=q.front();q.pop();
      int len=q.front();q.pop();

      for(auto&& to:e[now]){
        if(flag[to])continue;

        if(deg[to]>=3){
          if(len%2){
            deg[to]--;
            continue;
          }
          else {
            q.push(to);
            q.push(len+1);
            flag[to]=1;
          } 
        }else if(deg[to]==1){
          if(len%2){
            cout<<"First"<<ENDL;
            return 0;
          }else{
            q.push(to);
            q.push(len+1);
            flag[to]=1;
          } 
        }else{
          q.push(to);
          q.push(len+1);
          flag[to]=1;
        }
      }
    }
  }
  cout<<"Second"<<ENDL;
