		if(tmp.size() > 1 && tmp[i].FI == 1 && tmp[i].SE.FI + tmp[i].SE.SE == 1)continue;
		ret.FI = max(ret.FI,tmp[i].FI);
		ret.SE.SE += tmp[i].SE.FI;
		ret.SE.FI += tmp[i].SE.SE;
	}	
	ret.FI++;
	if(ret.SE.FI + ret.SE.SE == 0){
		ret = MP(0,MP(0,1));
	}
	//cout << num << " " << ret.FI << " " << ret.SE.FI << " " << ret.SE.SE << endl;
	return ret;
}

