const LL LINF = INF * (LL) INF;

const int MAX = 100100;
VI g[MAX];

PII MN[MAX][2];

int P[MAX];

void dfs(int x, int p)
{
	P[x] = p;
	if (SZ(g[x]) == 1)
	{
		MN[x][0] = MP(0, x);
		return;
	}

	MN[x][0] = MN[x][1] = MP(INF, INF);
	FOR (i, 0, SZ(g[x]))
	{
		int to = g[x][i];
		if (to == p) continue;

		dfs(to, x);

		MN[x][1] = min(MN[x][1], MN[to][0]);
		if (MN[x][1] < MN[x][0]) swap(MN[x][0], MN[x][1]);
	}

	MN[x][0].first++;
	MN[x][1].first++;
}


