bool hasMaxMatching(const vector<vector<int>>& tree){
    int n=tree.size();
    vector<bool> visited(n,false);
    vector<bool> matched(n,false);
    vector<int> preds(n,0);
    matched[0]=true;
    stack<int> si;
    si.push(1);
    visited[1]=true;
    while(!si.empty()){
        int cur=si.top();
        for(int i:tree[cur]){
            if(!visited[i]){
                si.push(i);
                preds[i]=cur;
                visited[i]=true;
            }
        }
        if(cur==si.top()){
            if(!matched[cur]&&!matched[preds[cur]]){
                matched[cur]=true;
                matched[preds[cur]]=true;
            }
            else if(!matched[cur] && matched[preds[cur]]){
                return false;
            }
            si.pop();
        }
    }
    return true;
}

