using namespace std;
typedef long long ll;
vector<ll> node[100005];
bool isodd[100005],used[100005];
ll leaf[100005]={0};

ll dp(ll pos,ll n){
  ll kn=0,sm=n-1;
  for(int i=0;i<node[pos].size();i++){
    ll to=node[pos][i];
    if(!used[to]){
      used[to]=true;
      ll d=dp(to,n);
      if(d%2==1) isodd[pos]=true;
      kn+=d;
    }
  }
  sm-=kn;
  if(sm%2==1){
    isodd[pos]=true;
  }
  return kn+1;
}
int main(){
  ll n;
  cin>>n;
  for(int i=1;i<n;i++){
    ll s,t;
    cin>>s>>t;
    node[s].push_back(t);
    node[t].push_back(s);
  }
  int st=0;
  for(int i=1;i<=n;i++){
    if(node[i].size()>1) st=i;
    else leaf[node[i][0]]++;
  }
  for(int i=1;i<=n;i++){
    if(leaf[i]>=2){
      cout<<"First"<<endl;
      return 0;
    }
  }
  if(st==0){
    cout<<"Second"<<endl;
    return 0;
  }
  for(int i=1;i<=n;i++){
    isodd[i]=false;
    used[i]=false;
  }
  used[st]=true;
  dp(st,n);
  bool f=false;
  for(int i=1;i<=n;i++){
    if(!isodd[i]) {
      f=true;
    }
  }
  cout<<(f?"First":"Second")<<endl;
}

