void addedge(int u,int v)
{
    *tp=(edge){v,head[u]},head[u]=tp++;
    *tp=(edge){u,head[v]},head[v]=tp++;
}

void init()
{
    n=getint();
    for(int i=1; i<n; i++){
        int u=getint(),v=getint();
        addedge(u,v);
    }
