bool cmp(int a,int b)
{
    return dep[a]>dep[b];
}

void dfs(int x)
{
    for(edge *i=head[x]; i; i=i->next){
        if(dep[i->v]) continue;
        dep[i->v]=dep[x]+1;
        fa[i->v]=x;
        dfs(i->v);
    }
}

