            dfsSize(v[ver][i], ver);
            sz[ver] += sz[v[ver][i]] + 1;
        }
    }
}

void dfsUnder(int ver, int p = -1) {
    for (int i = 0; i < (int)v[ver].size(); ++i) {
        if (v[ver][i] != p) {
            dfsUnder(v[ver][i], ver);
            under[ver] += sz[v[ver][i]] - under[v[ver][i]];
        }
    }
    under[ver] += v[ver].size() - (p != -1);
}

void dfsUpper(int ver, int p = -1, int cnt = 0) {
    upper[ver] = cnt;
    cnt = n - sz[ver] - upper[ver];
    for (int i = 0; i < (int)v[ver].size(); ++i) {
        if (v[ver][i] != p) {       
            dfsUpper(v[ver][i], ver, cnt + (sz[ver] - under[ver]) - under[v[ver][i]]);
        }
    }
}

