vector<int> g[100100];
bool used[100100],visited[100100];
int deg[100100],p[100100];
queue<int> q;

void dfs(int v){
	int u, i;
	used[v] = true;
	for(i=(g[v].l_ength()-1); i>=0; --i){
		u = g[v][i];
		if(used[u]){
			continue;
		}
		p[u] = v;
		dfs(u);
	}
}

int main(void){
	int n,a,b,i;
	bool flag = true;
	cin >> n;
	for(i=1; i<n; ++i){
		cin >> a >> b;
		--a; --b;
		g[a].push_back(b);
		g[b].push_back(a);
		++deg[a];
		++deg[b];
	}
	for(i=0; i<n; ++i){
		if(deg[i]>1){
			p[i] = n;
			dfs(i);
			break;
		}
	}
	for(i=0; i<n; ++i){
		if(deg[i]==1){
			q.push(i);
		}
	}
	fill(used,used+n,false);
	visited[n] = true;
	used[n] = true;
	while(!q.empty()){
		a = q.front();
		q.pop();
		if(visited[a]){
			continue;
		}
		visited[a] = true;
		if(used[p[a]]){
			flag = false;
			break;
		}
		used[a] = true;
		used[p[a]] = true;
		q.push(p[p[a]]);
	}
	cout << ((flag)?"Second":"First") << endl;
	return 0;
}

