using Weight = int;
struct Edge {
	int dst;
	Weight weight;
	Edge() : dst(0), weight(0) {}
	Edge(int d, Weight w = 1) : dst(d), weight(w) {}
};
ostream &operator<<(ostream &os, const Edge &e) { return os << e.dst; }
using Edges = vector<Edge>;
using Graph = vector<Edges>;

bool solve() {
	int n = ri();

	Graph G(n);
	vi J(n);
	rep(i, n-1) {
		int u = ri() - 1;
		int v = ri() - 1;
		G[u].emplace_back(v);
		G[v].emplace_back(u);
		J[u]++;
		J[v]++;
	}

	if (n == 2) return false;

	int root = -1;
	queue<int> Q;
	rep(i, n) {
		if (J[i] != 1) {
			root = i;
		}
		else {
			Q.emplace(i);
		}
	}

	out(root);

	vi P(n);
	{
		function<void(int, int)> dfs = [&](int cur, int pre) {
			P[cur] = pre;
			forr(nex, G[cur]) {
				if (nex.dst != pre) {
					dfs(nex.dst, cur);
				}
			}
		};
		dfs(root, -1);
	}

	vi U(n);

	while (sz(Q)) {
		int u = Q.front();
		Q.pop();

		if (u == root) return true;
		if (U[u]) continue;

		int p = P[u];
		if (U[p]) return true;

		int g = P[p];

		out(u, p, g);
		if (g != -1 && g != root && !U[g]) Q.emplace(g);

		U[u] = U[p] = 1;
	}
	return false;
}

void Main() {
	cout << (solve() ? "First" : "Second") << endl;
}

