int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<set<int>>edge(N);
	for (int i = 1; i < N; i++) {
		cin >> L >> R;
		L--;
		R--;
		edge[L].insert(R);
		edge[R].insert(L);
	}
	queue<int>Q;
	int three = 0;
	for (int i = 0; i < N; i++) {
		if (edge[i].size() == 1)Q.push(i);
		else if (edge[i].size() >= 3)three++;
	}
	while (three) {
		if (Q.empty()) {
			cout << "First\n";
			return 0;
		}
		vector<vector<int>>parent(N);
		set<int>nxq;
		while (!Q.empty()) {
			int cn = Q.front();
			int node = 0;
			int n = cn;
			int nx = n;
			int depth = 0;
			Q.pop();
			while (edge[nx].size() < 2) {
				node++;
				n = nx;
				nx = *edge[n].begin();
				edge[n].erase(nx);
				edge[nx].erase(n);
			}
			if (edge[nx].size() == 2)three--;
			if (node % 2) {
				edge[n].insert(nx);
				edge[nx].insert(n);
				if (edge[nx].size() == 3)three++;
				parent[nx].push_back(n);
			}
			if (edge[nx].size() == 2)nxq.insert(nx);
			if (!three) {
				node = 0;
				for (auto i : edge)if (i.size() == 2)node++;
				if (node % 2)cout << "First\n";
				else cout << "Second\n";
				return 0;
			}
		}
		for (auto i : nxq) {
			if (edge[i].size() == 2) {
				for (auto j : parent[i])Q.push(j);
			}
			if (edge[i].size() == 1)Q.push(i);
		}
		cout << Q.size() << endl;
	}
	int node = 0;
	for (auto i : edge)if (i.size() == 2)node++;
	if (node % 2)cout << "First\n";
	else cout << "Second\n";
	return 0;
}

