const int max_n = 1e5 + 20;
vector<int> adj[max_n];
int n;
int mark[max_n], barg[max_n];
int dfs(int v) {
    mark[v] = 1;
    int det = 0, z = 1;
    for (auto i : adj[v]) {
        if (!mark[i]) {
            int tmp = dfs(i);
            det = max(det, tmp);
        }
    }
    if (!det && v == 0) {
        cout << "First";
        exit(0);
    }
    return !det;
}
