using namespace std;
const int maxn=1e5+10;
int head[maxn*2];
int tot=0;
struct E{
    int to,nex;
}e[maxn*5];
void add(int u,int v){
    e[tot]=E{v,head[u]}; head[u]=tot++;
}
int pre[2*maxn],vis[2*maxn];
int dfs(int u){
    for(int i=head[u];i!=-1;i=e[i].nex){
        int p=e[i].to;
        if(!vis[p]){
            vis[p]=1;
            if(pre[p]==-1||dfs(pre[p])){
                pre[p]=u;
                return 1;
            }
        }
    }
    return 0;
}
int hungry(int n){
    int ans=0;
    memset(pre,-1,sizeof pre);
    for(int i=1;i<=n;i++){
        memset(vis,0,sizeof vis);
        if(dfs(i)) ans++;
    }
    return ans;
}
int main(){
    memset(head,-1,sizeof head);
    int n;
    scanf("%d",&n);
    for(int i=0;i<n-1;i++){
        int a,b;
        scanf("%d%d",&a,&b);
        add(a,b+maxn);
        add(b,a+maxn);
    }
    int ans=hungry(n);
    if(ans==n) cout<<"Second"<<endl;
    else cout<<"First"<<endl;
}

