int n,m,i,j,dp[100005],x,y;
vector<int> bi[100005];
void dfs(int x,int fa)
{
	int i;
	dp[x]=0;
	for (vector<int>::iterator it=bi[x].begin();it!=bi[x].end();it++)
	{
		if (*it==fa) continue;
		dfs(*it,x);
		if (dp[*it]==0) dp[x]++;
		if (dp[*it]>1||dp[x]>1)
		{
			dp[x]=2;
			break;
		}
	}
}
