int sz[MR], cc;

void dfs(int nr)
{
	doneL[nr] = cc;
	for (auto v : g[nr])
		if (!doneL[v] && lastL[v])
			dfs(v);
}

bool go(int N)
{
	REP(i, N)
		if (g[i].size() == 1)
		{
			q[0].push(i);
			done[i] = 1;
			if (done[g[i].front()])
				return 0;
			q[1].push(g[i].front());
			done[g[i].front()] = 1;
		}

	N -= q[0].size() + q[1].size();

	// wyczysc liscie
	while (!q[0].empty())
		q[0].pop();

	while (N)
	{
		// przetwarzaj rodzicow i wyznacz nowe liscie
		while (!q[1].empty())
		{
			int akt = q[1].front(); q[1].pop();
			for (auto v : g[akt])
				if (!done[v])
				{
					q[0].push(v);
					done[v] = 1;
					N--;
					break;
				}
		}

		// wyznacz nowych rodzicow
		vector<int> cp;
		while (!q[0].empty())
		{
			int akt = q[0].front(); q[0].pop(); cp.push_back(akt);
			lastL[cp.back()] = 1;
			for (auto v : g[akt])
				if (!done[v])
				{
					q[1].push(v);
					done[v] = 1;
					// odznacz, ze lisc jest zmatchowany
					lastL[cp.back()] = 0;
					N--;
					break;
				}
		}

		if (q[1].size() < cp.size())
		{
			// spr czy jest jakis nieparzysty komponent wsrod lisci, ktory nie byl zmatchowany
			cc = 0;
			for (auto v : cp)
				if (!doneL[v])
				{
					cc++;
					dfs(v);
				}
			for (auto v : cp)
				sz[doneL[v]]++;
			FORQ(i, 1, cc)
				if (sz[i] % 2)
					return 0;
			for (auto v : cp)
				lastL[v] = 0;
			for (auto v : cp)
				sz[doneL[v]] = 0;
		}
	}

	return 1;
}

int main()
{
	int N;
	scanf("%d", &N);

	if (N == 1)
	{
		printf("First\n");
		return 0;
	}

	if (N == 2)
	{
		printf("Second\n");
		return 0;
	}

	REP(i, N - 1)
	{
		int a, b;
		scanf("%d%d", &a, &b); a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	if (go(N))
		printf("Second\n");
	else
		printf("First\n");

	return 0;
}

