    subTree[node] = 1;

    int lim = graph[node].size(), neigh_Leafs = 0;;
    for(int i = 0; i < lim; i++) {
        int neigh = graph[node][i];
        if(!viz[neigh]) {
            dfs(neigh);
            subTree[node] = (subTree[node] + subTree[neigh]) %  2;
        }

        if(leaf[neigh])
            neigh_Leafs++;    
    }
    if(neigh_Leafs > 1) {
        printf("First\n");
        exit(0);
    }
}

void dfs2(int node) {
    viz[node] = 1;

    int lim = graph[node].size(), sum  = 0;
    for(int i = 0; i < lim; i++) {
        int neigh = graph[node][i];
        sum += subTree[neigh];
    }
    if(sum != 1) {
        printf("First\n");
        exit(0);
    }
    for(int i = 0; i < lim; i++){
        int neigh = graph[node][i];
        if(!viz[neigh]) {
            subTree[node] = n - subTree[neigh];
            dfs(neigh);
        }
    }
}

