typedef long long ll;

const int MAX = 100010;

int cnt[MAX];
vector <int> adj[MAX];
bool used[MAX];
bool go(int v, int d){
    if ((int)adj[v].size() > 2) return false;
    if (d == 3) return true;
    used[v] = true;
    bool f = false;
    for (int t : adj[v]) {
        if (!used[t]) {
            f = f || go(t, d+1);
        }
    }
    return f;
}

void solve(void){
    int N;
    cin >> N;
    if (N%2) {
        cout << "First" << endl;
        return;
    }
    bool ff = N%2;
    rep(N-1, i) {
        int a, b;
        scanf("%d %d\n", &a, &b);
        a--; b--;
        adj[a].pb(b);
        adj[b].pb(a);
        cnt[a]++;
        cnt[b]++;
    }
    int two = N-2, one = 2;
    rep(N, i) {
        if (cnt[i] == 2) two--;
        else if (cnt[i] == 1) one--;
        else ff = false;
    }
    ff = ff && (two == 0) && (one == 0);
    if (ff) {
        cout << "First" << endl;
        return;
    }
    rep(N, n) {
        int cnt = 0;
        for (int k : adj[n]) {
            cnt += (int)adj[k].size() == 1;
        }
        memset(used, false, sizeof(used));
        if (cnt > 1 || ((int)adj[n].size() > 2 && cnt == 1 && go(n, 0))) {
            cout << "First" << endl;
            return;
        }
    }
    cout << "Second" << endl;
}

int main(void){
  solve();
  return 0;
}

