		--a; --b;
		g.add_edge(a, b);
		g.add_edge(b, a);
	}
	const int t = (n % 2 == 1 ? -1 : solve(0, -1, g));
	cout << (t < 0 ? "First" : "Second") << endl;
	return 0;
}

