using Graph=vector<vector<int>>;

template<typename G>
bool AllMatching(const G &g){
    int sz=g.size();
    vector<int> deg(sz,0);
    vector<bool> seen(sz,0);
    queue<int> que;
    for(int i=0;i<sz;i++){
        deg[i]=g[i].size();
        if(deg[i]==1) que.push(i);
    }
    while(!que.empty()){
        int now=que.front(); que.pop();
        if(seen[now]) continue;
        int next=-1;
        for(auto e:g[now]){
            if(!seen[e]){ //+++++++++++++++
                next=e; //++++++++++++++++
                break;
            }
        }
        if(next==-1) return false;
        seen[next]=true;
        for(auto e:g[next]){
            if(seen[e]) continue; //+++++++++++++++++++++
            deg[e]--;   //+++++++++++++++++++
            if(deg[e]==1) que.push(e); //++++++++++++++
        }
    }
}

