	for (int l=1;l<n;l++) {
		int u,v;
		cin>>u>>v;
		lj(u,v);
		lj(v,u);
	}
	bfs();
	int ans=0;
	for (int u=1;u<=n;u++) {
		if (bl[u]==0) {
			ans++;
		}
	}
