int n,id;
int first[MAXN];
int size[MAXN];
int fa[MAXN];
int mark[MAXN];

void addE(int u,int v)
{
	edge[++id] = (Edge){v,first[u]};
	first[u] = id;
}

void dfs(int u)
{
	size[u] = 1;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa[u])
		{
			fa[edge[i].to] = u;
			dfs(edge[i].to);
		}
}

int main()
{
	scanf("%d",&n);
	for (int u,v,i = 1;i < n;i++)
	{
		scanf("%d%d",&u,&v);
		addE(u,v);
		addE(v,u);
	}
	for (int i = 1;i <= n;i++)
		if (!edge[first[i]].nxt)
			mark[edge[first[i]].to]++;
	dfs(1);
	for (int i = 1;i <= n;i++)
	{
		if (mark[i])
			continue;
		int cnt[4] = {0};
		for (int j = first[i];j;j = edge[j].nxt)
		{
			int sz = (edge[j].to == fa[i] ? n - size[i] : size[edge[j].to]);
			cnt[0]++;
			if (mark[edge[j].to])
				sz = 2;
			if (sz < 4)
				cnt[sz]++;
		}
		if (mark[i] > 1 || cnt[2] == cnt[0])
		{
			cout << "First" << endl;
			return 0;
		}
	}
	cout << "Second" << endl;
	return 0;
}

