{
	int res, ret = 0;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		res = dfs(G[v][i], v);
		if(res == -1) return -1;
		ret += res;
	}
	if(ret >= 2) return -1;
	if(ret == 1) return 0;
	if(ret == 0) return 1;
