	Edge(int d, Weight w = 1) : dst(d), weight(w) {}
};
ostream &operator<<(ostream &os, const Edge &e) { return os << e.dst; }
using Edges = vector<Edge>;
using Graph = vector<Edges>;

bool solve() {
	int n = ri();

	Graph G(n);
	vi J(n);
	rep(i, n-1) {
		int u = ri() - 1;
		int v = ri() - 1;
		G[u].emplace_back(v);
		G[v].emplace_back(u);
		J[u]++;
		J[v]++;
	}

	if (n == 2) return false;

	int root = -1;
	queue<int> Q;
	rep(i, n) {
		if (J[i] != 1) {
			root = i;
		}
		else {
			Q.emplace(i);
		}
	}

	vi P(n);
	{
		function<void(int, int)> dfs = [&](int cur, int pre) {
			P[cur] = pre;
			forr(nex, G[cur]) {
				if (nex.dst != pre) {
					dfs(nex.dst, cur);
				}
			}
		};
		dfs(root, -1);
	}

	vi U(n);

	const int BLACK = 1;
	const int WHITE = 0;
	const int UNKNOWN = -1;

	vi C(n, UNKNOWN);

	while (sz(Q)) {
		int u = Q.front();
		Q.pop();

		if (C[u] == UNKNOWN) C[u] = BLACK;

		int p = P[u];

		if (p == root) {
			int pcol = 1 - C[u];
			if (C[p] == UNKNOWN || C[p] == pcol) {
				C[p] = pcol;
			}
			else return false;
		}
		else {
			if (C[u] == BLACK) {
				C[p] = WHITE;
			}
			else if (C[p] == UNKNOWN) {
				C[p] = BLACK;
			}
		}
		J[p]--;
		if (J[p] == 1 && p != root) Q.emplace(p);
	}
	return true;
}

void Main() {
	cout << (solve() ? "First" : "Second") << endl;
}

