void dfs(int u) {
	if(g[u].size() == 1) leaves.push(u);
	for(int v: g[u]) if(v != par[u]) {
		par[v] = u;
		lvl[v] = lvl[u]+1;
		dfs(v);
	}
}
int main() {
	ios::sync_with_stdio(false);
