#include <bits/stdc++.h>
#define F first
#define S second
using namespace std;
using ll = long long;
typedef pair<int, int> P;
const ll Mod = 1000000007;
const int INF = 1000000;
int N;
vector<int> Graph[110000];
vector<int> Depth[110000];
vector<int> Deep(110000);
vector<int> Parent(110000);
vector<int> child[110000];
int root = 0;
void BFS() {
  for (int i = 0; i < (int)Deep.size(); i++) {
    Deep[i] = 999999;
  }
  priority_queue<P, vector<P>, greater<P>> Q;
  Q.push(make_pair(0,root));
  Depth[0].push_back(root);
  Deep[root] = 0;
  while (!Q.empty()) {
    P p = Q.top();
    Q.pop();
    for (int i = 0; i < (int)Graph[p.S].size(); i++) {
      if (Deep[Graph[p.S][i]] > p.F + 1) {
        Q.push(make_pair(p.F+1,Graph[p.S][i]));
        Deep[Graph[p.S][i]] = p.F + 1;
        Depth[p.F+1].push_back(Graph[p.S][i]);
        Parent[Graph[p.S][i]] = p.S;
        child[p.S].push_back(Graph[p.S][i]);
      }
    }
  }
}
int main() {
  cin >> N;
  vector<bool> exist(N);
  bool can = false;
  for (int i = 0; i < N; i++) {
    exist[i] = true;
  }
  for (int i = 0; i < N-1; i++) {
    int a,b;
    cin >> a >> b;
    a--; b--;
    Graph[a].push_back(b);
    Graph[b].push_back(a);
  }

  BFS();

  for (int i = N-1; i >= 1; i--) {
    for (int j = 0; j < (int)Depth[i].size(); j++) {
      int s = Depth[i][j];
      int ch = 0;
      if (i == 1) ch++;
      for (int k = 0; k < (int)child[s].size(); k++) {
        if (exist[child[s][k]]) ch++;
      }
      if (ch == 0) {
        continue;
      } else if (ch == 1) {
        exist[s] = false;
        exist[child[s][0]] = false;
      } else if (ch >= 2) {
        can = true;
      }
    }
    if (can) {
      break;
    }
  }

  if (can) {
    cout << "First" << endl;
  } else {
    cout << "Second" << endl;
  }
  return 0;
}

