void dfs2(int p, int fa, int ff, int fg)
{

	int sf = 0, sg = 0;
	for (auto i : e[p])
	{
		if (i != fa)
		{
			sf += f[i];
			sg += g[i];
		}
	}
	if (p == 1)
	{
		for (auto i : e[p])
			dfs2(i, p, sf - f[i], sg - g[i]);
		return;
	}
	bool uf = false, ug = false;
	if (fg > 1 || (fg == 1 && g[p] == 0))
		uf = true;
	if (fg == s[fa])
		ug = true;
	sf += uf;
	sg += ug;
	if (sf == s[p] + 1)
	{
		printf("First\n");
		exit(0);
	}
	for (auto i : e[p])
	{
		if (i != fa)
			dfs2(i, p, sf - f[i], sg - g[i]);
	}
}

void dfs(int p, int fa)
{
	f[p] = 0;
	g[p] = 1;
	s[p] = 1;
	for (auto i : e[p])
	{
		if (i != fa)
		{
			dfs(i, p);
			s[p] += s[i];
			f[p] |= g[i];
			g[p] &= f[i];
		}
	}
	if (e[p].size() == 0)
	{
		f[p] = 0;
		g[p] = 1;	
	}
	return;
}

