        for(e = 0;e < edges[u].size();++e)
            if(!removed[edges[u][e]])
                v = edges[u][e];
        removed[v] = removed[u] = true;
        for(e = 0;e < edges[v].size();++e)
            if(!removed[edges[v][e]] && --degree[edges[v][e]] == 1)
                queue.push(edges[v][e]);
            else if(!removed[edges[v][e]] && degree[edges[v][e]] == 0)
                return puts("First"),0;
    }
    puts("Second");

    return 0;
}

