struct Node{
  int color;
  set<int> next;
};

Node nodes[100000];
vector<int> colors(100000, kBlank);

map<vector<int>, int> m;


int AndSearch(int turn);

int WhoWin(){
  vector<int> judge(N, kWhite);

  for(int i=0; i<N; i++){
	if(nodes[i].color == kBlack){
	  judge[i] = kBlack;
	  for(auto s : nodes[i].next){
		judge[s] = kBlack;
	  }
	}
  }

  for(int i=0; i<N; i++){
	if(judge[i] == kWhite){
	  return kWhite;
	}
  }
  return kBlack;
}

int OrSearch(int turn){
  if(turn == N){
	return WhoWin();
  }

  for(int i=0; i<N; i++){
	if(nodes[i].color == kBlank){
	  nodes[i].color = kWhite;
	  colors[i] = kWhite;
	  int result;
	  try{
		result = m.at(colors);
	  }catch(out_of_range&){
		result = AndSearch(turn + 1);
		m.insert(make_pair(colors, result));
	  }
	  nodes[i].color = kBlank;
	  colors[i] = kBlank;
	  if(result == kWhite){
		return kWhite;
	  }
	}
  }
  return kBlack;
}

int AndSearch(int turn){
