int leafCount[100005];

using P = pair<int, int>;
bool bfs(int s) {
    set<P> used;
    queue<P> que;
    que.push(P(s, leafCount[s] > 0));
    used.insert(P(s, leafCount[s] > 0));
    while (que.size()) {
        auto now = que.front();
        que.pop();
        int v = now.first;
        int cnt = now.second;
        if (cnt >= 3) return true;

        for (auto u : G[v]) {
            int t;
            if (leafCount[u] == 0)
                t = 0;
            else
                t = min(3, cnt + 1);
            auto next = P(u, t);
            if (used.count(next)) continue;
            que.push(next);
        }
    }

    return false;
}

