signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(20);
	//modcalc();

	int n;
	cin >> n;
	vector<vector<int>> graph(n, vector<int>());
	vector<int> deg(n);
	vector<int> a(n - 1), b(n - 1);
	rep(i, n - 1) {
		cin >> a[i] >> b[i];
		a[i]--; b[i]--;
		graph[a[i]].pb(b[i]);
		graph[b[i]].pb(a[i]);
		deg[a[i]]++;
		deg[b[i]]++;
	}
	int cnt = 0;
	queue<int> que;
	rep(i, n) if (deg[i] == 1) que.push(i);
	while (!que.empty()) {
		int p = que.front(); que.pop();
		if (deg[p] != 1) continue;
		int q;
		for (int i : graph[p]) {
			if (deg[i]) q = i;
		}
		if (deg[q]) cnt++;
		deg[p] = 0; deg[q] = 0;
		for (int i : graph[q]) {
			if (i == p || !deg[i]) continue;
			deg[i]--;
			if (deg[i] == 1) {
				que.push(i);
			}
		}
	}
	cout << (cnt * 2 != n ? "First" : "Second") << endl;
}

