inline int dfs(int x,int f) {
	if(tag) return 1;
	int cnt=0;
	for(auto v:edge[x]) 
		if(v^f) cnt+=dfs(v,x);
	if(!cnt) return 1;
	else if(cnt==1) return 0;
	else return tag=1;
}
