void solve() {
	int N; cin >> N;
	REP(i, N - 1) {
		int u, v; cin >> u >> v;
		u--, v--;
		G[u].push_back(v);
		G[v].push_back(u);
		deg[u]++;
		deg[v]++;
	}
	make(0,0);
	vector<int>use;
	REP(i, N) {
		if (deg[i] == 1&&i!=0)use.push_back(i);
	}
	int cnt = 0;
	while (use.size() > 0) {
		vector<int>n_use;
		REP(i, use.size()) {
			int n = use[i];
			//DEBUG(n);
			if (used[n])continue;
			if (par[n] == n)No();
			if (used[par[n]])No();
			used[n] = used[par[n]] = true;
			cnt += 2;
			deg[par[par[n]]]--;
			if (deg[par[par[n]]] == 1)n_use.push_back(par[par[n]]);
		}
		use.clear();
		for (auto n : n_use)use.push_back(n);
	}
	if (cnt != N)No();
	print("Second");
}

