using namespace std;

const int white = 1;
const int black = 2;

int leaves(
  const vector<vector<int>>& vertices,
  vector<int>& colors,
  int v
) {
  int n = 0;
  for (auto i: vertices[v]) {
    if (colors[i] == 0 and vertices[i].size() == 1) ++n;
  }
  return n;
}

int whites(
  const vector<vector<int>>& vertices,
  vector<int>& colors,
  int v
) {
  int n = 0;
  for (auto i: vertices[v]) if (colors[i] == white) ++n;
  return n;
}

bool offence(
  const vector<vector<int>>& vertices,
  vector<int>& colors
) {
  vector<int> next1, next2, next3;
  for (int i = 0; i < colors.size(); ++i) {
    if (colors[i] == 0) {
      bool used = false;
      int w = whites(vertices, colors, i);
      if (w > 1) return true;
      if (w == 1) {
        next2.push_back(i);
        used = true;
      }

      int l = leaves(vertices, colors, i);
      if (l > 1) return true;
      if (l == 1) {
        next1.push_back(i);
        used = true;
      }
      if (!used) next3.push_back(i);
    }
  }
  if (!next1.empty()) {
    colors[next1[0]] = white;
  } else if (!next2.empty()) {
    colors[next2[0]] = white;
  } else {
    colors[next3[0]] = white;
  }
  return false;
}

void defence(
  const vector<vector<int>>& vertices,
  vector<int>& colors
) {
  vector<int> next;
  for (int i = 0; i < colors.size(); ++i) {
    if (colors[i] == 0) {
      int w = whites(vertices, colors, i);
      if (w > 1) {
        colors[i] = black;
        return;
      }
      if (w == 1) {
        if (vertices[i].size() == 1) {
          colors[i] = black;
          return;
        }
        next.push_back(i);
      }
    }
  }
  colors[next[0]] = black;
}

int main()
{
  int N;
  cin >> N;
  vector<vector<int>> vertices(N);
  for (int i = 1; i < N; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    vertices[a].push_back(b);
    vertices[b].push_back(a);
  }
  vector<int> colors(N, 0);
  int turn = 0;
  bool first = false;
  for (int i = 0; i < N; ++i) {
    if (turn == 0) {
      bool win = offence(vertices, colors);
      if (win) {
        first = true;
        break;
      }
      turn = 1;
    } else {
      defence(vertices, colors);
      turn = 0;
    }
  }
  cout << (first ? "First" : "Second") << endl;
  return 0;
}

