int main()
{
    int N;
    cin>>N;
    vector<vector<int>> E(N);
    for (int i=0; i<N-1; i++)
    {
        int a, b;
        cin>>a>>b;
        E[a-1].push_back(b-1);
        E[b-1].push_back(a-1);
    }

    bool line = true;
    for (auto e: E)
        if (e.size()>=3)
            line = false;
    bool ans;
    if (line)
    {
        ans = N%2!=0;
    }
    else
    {
        vector<vector<int>> T(N);

        for (int s=0; s<N; s++)
        if (E[s].size()==1)
        {
            int p = s;
            int c = E[s][0];
            int l = 1;
            while (E[c].size()==2)
            {
                int tc = c;
                c = E[c][0]==p ? E[c][1] : E[c][0];
                p = tc;
                l += 1;
            }
            T[c].push_back(l);
