        for (int i=0; i<N; i++)
        {
            int oc = 0;
            for (int l: T[i])
                if (l%2 != 0)
                    oc++;
            if (oc>=2)
                ans = true;
        }
    }
    cout<<(ans ? "First" : "Second")<<endl;
