int N;
vector<vector<int> > G;
map<PP, int> R;

int cal(int a, int b) {
	PP p = make_pair(a, b);
	if (R.find(p) != R.end()) return R[p];
	// Check whether path from a to b is a line.
	if (G[b].size() == 1) {
		R[p] = 1;
		return 1;
	}
	if (G[b].size() == 2) {
		int c = G[b][0] + G[b][1] - a;
		int d = cal(b, c);
		if (d == 1) {
			R[p] = 0;
		}
		if (d == 0) {
			R[p] = 1;
		}
		if (d == -1) {
			R[p] = -1;
		}
		return R[p];
	}
	R[p] = -1;
	return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin >> N;
    G.resize(N);
    for (int i = 1;i < N;i++) {
    	int a, b;
    	cin >> a >> b;
    	a--;
    	b--;
    	G[a].push_back(b);
    	G[b].push_back(a);
    }
    bool ok = 0;
    for (int i = 0;i < N;i++) {
    	int crt = 0;
    	for (int j = 0;j < G[i].size();j++) {
    		int k = cal(i, G[i][j]);
    		if (k > 0) crt++;
    	}
    	if (crt > 1) ok = 1;
    }
    if (ok) cout << "First" << endl;
    else cout << "Second" << endl;
    return 0;
}

