void adge(int f,int t){
	e[++cnt]=(E){t,h[f]};h[f]=cnt;
}

int dp[N][2],dan[N];

void dfs1(int u,int fa){	
	for(int i=h[u];~i;i=e[i].xt) if(e[i].t!=fa){
		dfs1(e[i].t,u);
		if(dan[e[i].t]) dp[u][1]++;
		else dp[u][0]++;
	}
	if(dp[u][1]+dp[u][0]==0){
		dan[u]=1;
	}
	else if(dp[u][1]>1){
			puts("First");
			exit(0);
	}
	else if(dp[u][1]==1){
		dan[u]=0;
	}
	else if(dp[u][1]==0){
		dan[u]=1;
	}
}

void dfs2(int u,int fa){
	if(dp[u][1]!=1){
		puts("First");
		exit(0);
	}
	for(int i=h[u];~i;i=e[i].xt) if(e[i].t!=fa){
		int t[2];
		t[0]=dp[u][0]-(!dan[e[i].t]);
		t[1]=dp[u][1]-dan[e[i].t];
		if(t[1]+t[0]==0){
			dp[e[i].t][1]++;
		}
		else if(t[1]==1){
			dp[e[i].t][0]++;
		}
		else if(t[1]==0){
			dp[e[i].t][1]++;
		}
		dfs2(e[i].t,u);	
	}
}

