		for (auto nxt : graph[cur]) {
			int to, cost; tie(to, cost) = nxt;
			if (used[to]) continue;
			if (from[cur] == to) continue;
			sz = max(sz, size[to]);
			q.push(to);
		}
		if (sz < best) {
			best = sz;
			centroid = cur;
		}
	}
	used[centroid] = 1;
	tcolor[centroid] = turn;
	for (auto nxt : graph[centroid]) {
		int to, cost; tie(to, cost) = nxt;
		if (used[to]) continue;
		go(to, turn ^ 1);
		turn ^= 1;
	}
}

