const int N = 1e5 + 10;

int f[N], g[N], head[N], en, n;

struct Edge
{
    int nxt, to;
} eg[N << 1];

void setEdge(int u, int v)
{
    eg[++en] = (Edge) {head[u], v};
    head[u] = en;
}

void dfs(int u, int fa)
{
    int t = 0;
    for (int e = head[u]; e; e = eg[e].nxt)
    {
        int v = eg[e].to;
        if (v == fa) continue;
        dfs(v, u);
        if (f[v]) continue;
        if (!g[v])
        {
            f[u] = g[u] = 0;
            return ;
        }
        t++;
    }
    if (t > 1)
        f[u] = g[u] = 0;
    if (t == 1)
        f[u] = 1, g[u] = 0;
    if (t == 0)
        f[u] = 0, g[u] = 1;
}

