int N;
vector<vector<int> > G;
map<PP, int> R;

int cal(int a, int b) {
	PP p = make_pair(a, b);
	if (R.find(p) != R.end()) return R[p];
	// Check whether path from a to b is a line.
	if (G[b].size() == 1) {
		R[p] = 1;
		return 1;
	}
	if (G[b].size() == 2) {
		int c = G[b][0] + G[b][1] - a;
		int d = cal(b, c);
		if (d == 1) {
			R[p] = 0;
		}
		if (d == 0) {
			R[p] = 1;
		}
		if (d == -1) {
			R[p] = -1;
		}
		return R[p];
	}
	for (int i = 0;i < G[b].size();i++) {
		if (G[b][i] == a) continue;
		int d = cal(b, G[b][i]);
		if (d == 1) {
			R[p] = 0;
			return 0;
		}
	}
	R[p] = -1;
	return -1;
}

