    	G[b].push_back(a);
    }
    bool ok = 0;
    for (int i = 0;i < N;i++) {
    	int crt = 0;
    	for (int j = 0;j < G[i].size();j++) {
    		int k = cal(i, G[i][j]);
    		if (k > 0) crt++;
    	}
    	if (crt > 1) ok = 1;
    }
    if (ok) cout << "First" << endl;
    else cout << "Second" << endl;
    return 0;
}

