        deg[v] = g[v].size();
        if (g[v].size() == 1) {
            leafs.push_back(v);
            used[v] = true;
        }
    }
    while (leafs.size()) {
        vi white_leafs;
        for (int v : leafs) {
            for (int to : g[v]) {
                deg[to]--;
                if (!used[to]) {
                    used[to] = true;
                    white_leafs.push_back(to);
                }
            }
        }
        if (white_leafs.size() < leafs.size()) {
            cout << "First";
            return;
        }
        leafs.clear();
        for (int v : white_leafs) {
            for (int to : g[v]) {
                deg[to]--;
                if (deg[to] == 0 && !used[to]) {
                    used[to] = true;
                    leafs.push_back(to);
                }
            }
        }

    }

    cout <<  "Second";

}

