		graph[u - 1].push_back(v - 1);
		graph[v - 1].push_back(u - 1);
		deg[u - 1]++;
		deg[v - 1]++;
	}
	dfs(0);
	for (int i = 0; i < n; i++)
	{
		if (dp[i] > 1 || (dp[i] == 0 && deg[i] != 1))
