			int cnt = 0;
			for (int j = 0; j < graph[i].size(); j++)
			{
				if (leaf[graph[i][j]] == 1 && dp2[graph[i][j]] % 2 == 0)
				{
					cnt++;
				}
			}
			if (cnt >= 2)
			{
				cout << "First";
				exit(0);
			}
		}
	}
