typedef struct edge {
  int y;        /* adjancency info */
  int type;        /* edge type by dfs */
  int weight;     /* edge weight, if any */
  struct edge *next;    /* next edge in list */
} edge;


//////////////////////////////////////
///graph
#define MAXV    100001   /* maximum number of vertices */

int deg[100001] = {};


typedef struct graph{
  vector< edge* > edges;
  vector< int > deg;
  int nv,ne,dir;

  void init_graph(int v, bool d){
    nv = v;
    ne = 0;
    dir = d;
    for (int i=0; i<=MAXV; i++) deg.push_back(0);
    for (int i=0; i<=MAXV; i++) edges.push_back(NULL);
  }

  void insert_edge(int x, int y, int w ,bool dir){
    edge *p = (edge*)malloc(sizeof(edge));

    p->weight = w;
    p->y = y;
    p->type = -1;
    p->next = edges[x];

    edges[x] = p;
    deg[x] ++;

    if (dir == false) insert_edge(y,x,w,true);
    else  ne ++;
  }

  bool judge = false;

  void traverse_graph(){
    edge *p;
    int leaf_count = 0;
    for (int i=0; i<nv; i++) {

      int leaf = 0;
      p = edges[i];

      while (p != NULL) {
        if(deg[p->y] == 1)
          leaf++;
        p = p->next;
      }

      if(leaf > 1)
        leaf_count++;
    }
    if(leaf_count>0)
      judge = true;
  }

} graph;



int main()
{
  int n; cin >> n;
  graph g;
  g.init_graph(n,0);
  for(int i=0;i<n-1;i++){
    int x,y;
    cin >> x >> y; x--; y--;
    g.insert_edge(x,y,0,0);
    deg[x]++;
    deg[y]++;
  }

  g.traverse_graph();

  if(g.judge == false)
    cout << "Second" << endl;
  else
    cout << "First" << endl;

  return 0;
}

