int cond(int a) {
	if(deg[a] != 1) return -1;
	int b = -1;
	rep(i, 0, sz(G[a])) {
		int n = G[a][i];
		if(!used[n]) b = n;
	}
	if(deg[b] <= 2) return b;
	else return -1;
}

void solve() {
	cin >> N;
	rep(i, 0, N - 1) {
		int a, b; cin >> a >> b; a--; b--;
		G[a].pb(b);
		G[b].pb(a);
		deg[a]++; deg[b]++;
	}
	queue<pi> que;
	rep(i, 0, N) {
		int b = cond(i);
		if(b != -1) que.push(pi(i, b));
	}
	int del = 0;
	while(!que.empty()) {
		pi p = que.front(); que.pop();
		del++;
		used[p.fst] = 1;
		used[p.sec] = 1;
		int b = p.sec;
		int c = -1;
		rep(i, 0, sz(G[b])) {
			int n = G[b][i];
			if(!used[n]) c = n;
		}
		if(c == -1) continue;
		deg[p.fst]--;
		deg[b] -= 2;
		deg[c]--;
		int d = cond(c);
		if(d != -1) que.push(pi(c, d));
	}
	if(del * 2 == N) cout << "Second\n";
	else cout << "First\n";
}

