void dfs(int now,int fa) {
	siz[now]=1;
	for(int i=head[now];i;i=edge[i].nex) {
		if(edge[i].to!=fa) {
			dfs(edge[i].to,now);
			siz[now]+=siz[edge[i].to];
		}
	}
	if(siz[now]==1) return;
	int cnt=0;
	for(int i=head[now],v;i;i=edge[i].nex) {
		v=edge[i].to;
		if(v==fa) continue;
		if(!col[v]) cnt++;
	}
	if(cnt==1) col[now]=1;
	if(cnt>1) ans=1;
	if(now==1&&cnt==0) ans=1;
}

