using Graph=vector<vector<int>>;

bool flag=false;

bool dfs(int idx,int par,Graph &g){
	int cnt=0;
	int sum=0;
	//cout<<idx<<endl;
	for(int next:g[idx]){
		if(next==par) continue;
		sum++;
		if(dfs(next,idx,g)) cnt++;
	}
	if(cnt>=2) flag=true;
	if(sum==0) return true;
	return false;
}

vector<int> dfs2(int idx,int par,Graph &g){
	vector<int> cnt(3,0);
	int sum=0;
	for(int next:g[idx]){
		if(next==par) continue;
		vector<int> x=dfs2(next,idx,g);
		sum++;
		for(int i=0;i<3;i++){
			cnt[i]+=x[i];
		}
	}
	//cout<<idx<<endl;
	//vout(cnt);
	if(par==-1 && sum==2 && cnt[1]>=2) flag=true;
	if(cnt[2]>=1 && cnt[0]>=1) flag=true;
	if(sum==1) cnt[2]=cnt[1];
	else cnt[2]=0;
	cnt[1]=cnt[0];
	cnt[0]=0;
	if(sum==0) cnt[0]++;
	return cnt;
}

