	for(int i = 1; i < N; i++)
		scanf("%d%d", &u, &v),
		addEdge(u, v);

	for(int i = 1; i <= N; i++)
		if(Adj[i].size() > 1)
		{
			DFS(i, 0);
			break;
		}

	puts(noSolution ? "First" : "Second");

	CLOSEALL();
	return 0;
}

