				C[v] = FIRST;
				C[to] = SECOND;
			}else{
				return true;//勝ちの塗り方
			}
		}else{
			if( visit[to] == false ){
				bool res = dfs(to);
			}
		}
		if( C[to] == FIRST ){
			++count;
		}
	}
	if( count == Gra[v].size() ){
		return true;
	}else if(count+1 == Gra[v].size() ){
		for(int i=0;i<(int)Gra[v].size();++i){
			int to = Gra[v][i];
			if( C[to] == 0 ){
				bool res = dfs(to);
				return res;
			}
		}
	}
