::std::vector<::std::pair<ll, ll>> gabow_edmonds(const ::std::vector<::std::vector<ll>>& gra){
	struct edge {
		ll to;
		ll label;
		edge(ll to, ll label) : to(to), label(label) {}
	};
	// E0 - 初期化
	ll N = gra.size();
	::std::vector<::std::vector<edge>> g(N + 1);
	::std::vector<::std::pair<ll, ll>> edges;
	{
		ll cnt = N + 1;
		for(ll i = 0;i < N;i++){
			for(auto to : gra[i]){
				if(i < to){
					g[to + 1].emplace_back(i + 1, cnt);
					g[i + 1].emplace_back(to + 1, cnt++);
					edges.emplace_back(i + 1, to + 1);
				}
			}
		}
	}
	::std::vector<ll> mate(N + 1 , 0);
	::std::vector<ll> label(N + 1 , -1);
	::std::vector<ll> first(N + 1 , 0);
	::std::queue<ll> que;

	// firstの遅延評価
	::std::function<ll(ll)> eval_first = [&](ll x){
		if(label[first[x]] < 0) return first[x];
		first[x] = eval_first(first[x]);
		return first[x];
	};

	// サブルーチンR
	::std::function<void(ll, ll)> rematch = [&](ll v, ll w){
		// R1
		ll t = mate[v];
		mate[v] = w;
		if(mate[t] != v) return;
		// R2
		if(label[v] <= N){
			mate[t] = label[v];
			rematch(label[v] , t);
		}
		// R3
		else{
			ll x = edges[label[v] - N - 1].first;
			ll y = edges[label[v] - N - 1].second;
			rematch(x , y);
			rematch(y , x);
		}
	};

	::std::function<void(ll, ll, ll)> assignLabel = [&](ll x, ll y, ll num){
		// L0
		ll r = eval_first(x);
		ll s = eval_first(y);
		ll join = 0;
		if(r == s) return;
		// -numがフラグ
		label[r] = -num;
		label[s] = -num;
		while(true){
			// L1
			if(s != 0) ::std::swap(r , s);
			// L2
			r = eval_first(label[mate[r]]);
			if(label[r] == -num){
				join = r;
				break;
			}
			label[r] = -num;
		}
		// L3
		ll v = first[x];
		// L4
		while(v != join){
			que.push(v);
			label[v] = num;
			first[v] = join;
			v = first[label[mate[v]]];
		}
		// L3
		v = first[y];
		// L4
		while(v != join){
			que.push(v);
			label[v] = num;
			first[v] = join;
			v = first[label[mate[v]]];
		}
		// L5は遅延評価しているため不要
		// L6
		return;
	};

	::std::function<bool(ll)> augment_check = [&](ll u){
		// E1 後半
		first[u] = 0;
		label[u] = 0;
		que.push(u);
		while(!que.empty()){
			// E2 
			ll x = que.front();
			que.pop();
			for(auto e : g[x]){
				ll y = e.to;
				// E3
				if(mate[y] == 0 && y != u){
					mate[y] = x;
					rematch(x , y);
					return true;
				}
				// E4
				else if(label[y] >= 0){
					assignLabel(x , y , e.label);
				}
				// E5
				else if(label[mate[y]] < 0){
					label[mate[y]] = x;
					first[mate[y]] = y;
					que.push(mate[y]);
				}
				// E6
			}
		}
		return false;
	};

	for(ll i = 1;i <= N;i++){
		// E1
		que = ::std::queue<ll>();
		if(mate[i] != 0) continue;
		if(augment_check(i)){
			// E7
			::std::fill(label.begin(), label.end(), -1);
		}
	}

	::std::vector<::std::pair<ll, ll>> ans;
	for(ll i = 1;i <= N;i++){
		if(i < mate[i]){
			ans.emplace_back(i-1 , mate[i]-1);
		}
	}
	return ans;
}
