{
	if (edge[now].size() == 1 && *edge[now].begin() == prev)
	{
		return size % 2 == 1;
	}
	if (size % 2 == 0 && edge[now].size() >= 3)
	{
		return false;
	}
	for (auto const& v : edge[now])
	{
		if (v == prev)
		{
			continue;
		}
		if (check(edge, v, now, size + 1))
			return true;
	}
	return false;
}

