int sz[100001];

int dfs(int v, int p, vector<vector<int>> &G) {
    if (sz[v]) return sz[v];
    int ret = 1;
    for(int i = 0; i < G[v].size(); i++) {
        if (G[v][i] == p) continue;
        ret += dfs(G[v][i], v, G);
    }
    return sz[v] = ret;
}

int hasNmata(int v, int p, vector<vector<int>> &G) {
    if (sz[v] == 1) return 0;
    int ret = 0;
    int cnt = 0;
    for(int i = 0; i < G[v].size(); i++) {
        if (G[v][i] == p) continue;
        if (sz[G[v][i]] % 2 == 1) cnt++;
    }
    ret |= cnt >= 2;

    for(int i = 0; i < G[v].size(); i++) {
        if (G[v][i] == p) continue;
        ret |= hasNmata(G[v][i], v, G);
    }
    return ret;
}

