        int a, b; cin >> a >> b; a--, b--;
        add_edge(g, a, b);
    }
    if(n % 2 == 1) Exit("First");
    vector<int> color(n, -1);
    rep(i, 0, n)if(g[i].size() == 1){
        int v = g[i][0];
        int tcnt = 0;
        for(auto nv: g[v]){
            if(g[nv].size() == 1) tcnt++;
            if(tcnt >= 2) Exit("First");
