void solve(){
	int N;
	cin >> N;
	vector< vector<int> > Gra(N);
	for(int i=0;i<N-1;++i){
		int a,b;
		cin >> a >> b;
		--a;--b;
		Gra[a].push_back(b);
		Gra[b].push_back(a);
	}
	vector<int> AA(N,0);
	for(int i=0;i<N;++i){
		if( Gra[i].size() == 1 ){
			AA[ Gra[i][0] ] ++;
		}
	}
	for(int i=0;i<N;++i){
		if( AA[i] >= 2 ){
			cout << "First" << endl;
			return;
		}
	}
	cout << "Second" << endl;
}

