int pre[2 * MaxN + 5] , last[MaxN + 5] , other[2 * MaxN + 5];
int all , dis[MaxN + 5] , ind[MaxN + 5] , tot , si[MaxN + 5];
vector<int>son[MaxN + 5];
struct NODE{
	int l , r;
}a[MaxN + 5];
int n;
void Build(int u , int v){
	pre[++all] = last[u];
	last[u] = all;
	other[all] = v;
}
void dfs(int x , int fa , int d){
	dis[x] = d;
	a[x].l = ++tot;
	int ed = last[x];
	while(ed != -1){
		int dr = other[ed];
		if(dr != fa) {
			son[x].push_back(dr);
			dfs(dr , x , d + 1);
		}
		ed = pre[ed];
	}
	a[x].r = tot;
}
void Init(){
	tot = 0;
	memset(son , -1 , sizeof(son));
	memset(last , -1 , sizeof(last));
	memset(ind , 0 , sizeof(ind));
	all = -1;
	for(int i = 1;i <= n - 1;i++){
		int u , v;
		scanf("%d%d" , &u , &v);
		Build(u , v); Build(v , u);
		ind[u]++ ; ind[v]++;
	}
	dfs(1 , 0 , 0);
	for(int i = 1;i <= n;i++) si[i] = 1 << 30;
	for(int i = 1;i <= n;i++){
		for(int j = 0;j < son[i].size();i++){
			si[i] = min((int)son[son[i][j]].size() , si[i]);
		}
		if(son[i].size() == 0) si[i] = 0;
	}
}
void Solve(){
	for(int i = 1;i <= n;i++){
		if(ind[i] >= 3){
			if((dis[i] + a[i].r - a[i].l >= 4) && (son[i].size() >= 3 || si[i] >= 1)) {
				printf("Second\n");
				return;
			}
		}
	}
	printf("First\n");
}
int main()
{
	while(~scanf("%d" , &n)){
		Init();
		Solve();
	}
}

