lli depth(lli x,lli p){
    lli j = -1;
    lli sum = 0;
    s[x] = vll(g[x].size());
    for(lli i = 0;i < g[x].size();i++){
        if(g[x][i] == p){
            j = i;
            continue;
        }
        s[x][i] = depth(g[x][i],x);
        sum += s[x][i];
    }
    if(j >= 0) s[x][j] = n-sum-1;
    return sum + 1;
}



