	vector<vi> ed(N);
	vi deg(N);
	rep(i,0,N-1) {
		int a, b;
		cin >> a >> b;
		--a, --b;
		ed[a].push_back(b);
		ed[b].push_back(a);
		deg[a]++;
		deg[b]++;
	}

	vi deg1, deg0;
	rep(y,0,N) {
		if (deg[y] == 1) deg1.push_back(y);
		if (deg[y] == 0) deg0.push_back(y);
	}

	vi dead(N);
	auto kill = [&](int found) {
		dead[found] = 1;
		trav(y, ed[found]) {
			--deg[y];
			if (deg[y] == 1) deg1.push_back(y);
			if (deg[y] == 0) deg0.push_back(y);
		}
	};

