pair<pair<bool, bool>, pair<bool, bool>> dfs(int p, int o) {
  if(v[p].size() == 1) {
    return make_pair(make_pair(true, false), make_pair(false, false));
  }
  pair<pair<bool, bool>, pair<bool, bool>> r = make_pair(make_pair(false, false), make_pair(false, false));
  int k = 0;
  for(auto i : v[p]) {
    if(i != o) {
      auto w = dfs(i, p);
      if(w.first.first) {
        k++;
        r.first.second = true;
      }
      if(w.first.second) {
        r.first.first = true;
      }
      if(w.second.first) {
        r.second.second = true;
      }
      if(w.second.second) {
        r.second.first = true;
      }
    }
  }
  if(k >= 2 || (w.first.first && w.second.first) || (w.first.second && w.second.second)) {
    cout << "First" << endl;
    exit(0);
  }
  if(k == 1) {
    r.second.second = true;
  }
  return r;
}

