inline void addedge(int u, int v) { cnt ++; e[cnt] = enode(v,h[u]); h[u] = cnt; }

int sum[maxn], a[maxn], sz[maxn];

void dfs1(int u, int fa) {
  sum[u] = 0;
  sz[u] = 1;
  a[u] = 0;
  int bo = 0;
  for(int i = h[u];~ i;i = e[i].n) {
    int v = e[i].v;
    if(v == fa) continue;
    dfs1(v,u);
    sz[u] += sz[v];
    bo = 1;
    if(a[v]) sum[u] ++;
  }
  if(!bo) a[u] = 1;
  else if(sum[u] > 1) {
  	a[u] = 1;
  	flag = 1;
  }
  else if(sum[u] == 0) {
    a[u] = 1;
  }
}

