  for(int i = h[u], tmp, now;~ i;i = e[i].n) {
    int v = e[i].v;
    if(v == fa) continue;
    if(a[v]) tmp = sum[u] - 1;
    else tmp = sum[u];
    if(sz[1] - sz[v] == 1) sum[v] ++;
    else {
	  if(tmp > 1 || tmp == 0) sum[v] ++;
    }
