	even[v] = 1;
	for (int i = 0; i < g[v].size(); i++)
		if (g[v][i] != par) {
			dfs(g[v][i], v);
			odd[v] += even[g[v][i]];
			even[v] += odd[g[v][i]];
		}
	for (int i = 0; i < g[v].size(); i++)
		if (g[v][i] != par) {
			if (even[v] - odd[g[v][i]] > 0) {
				odd[g[v][i]]++;
			}
			if (odd[v] - even[g[v][i]] > 0)
				even[g[v][i]]++;
		}	
}

