using namespace std;

int INF = 114514;
int n;
vector<int> et[100000];
int dist[100000];
int cnt[100001];

int dfs(int v, int p) {
	if (p >= 0 && et[v].size() == 1) return dist[v] = 0;
	dist[v] = INF;
	for (int i = 0; i < et[v].size(); i++) {
		if (et[v][i] == p) continue;
		dist[v] = min(dist[v], dfs(et[v][i], v) + 1);
	}
	return dist[v];
}

int main() {
	int i;

	cin >> n;
	for (i = 0; i < n - 1; i++) {
		int a, b;
		cin >> a >> b; a--; b--;
		et[a].push_back(b);
		et[b].push_back(a);
	}
	dfs(0, -1);
	for (i = 0; i < n; i++) cnt[dist[i]]++;

	for (i = 0; i < n; i += 2) {
		if (cnt[i] != cnt[i + 1]) {
			cout << "First" << endl;
			return 0;
		}
	}

	cout << "Second" << endl;
	return 0;
}

