	bool ans=true;
	for (int i=0;i<G[u].size();i++){
		if (G[u][i]==pa) continue;
		int v=G[u][i];
		for (int j=0;j<G[v].size();j++){
			if (G[v][j]==u) continue;
			if (!canpick(v,G[v][j])) ans=false;
		}
	}
	return ans;
}
