int e, n, m, Begin[maxn], Next[maxn<<1], To[maxn<<1] ;
void add ( int x, int y ) {
	To[++e] = y ;
	Next[e] = Begin[x] ;
	Begin[x] = e ;
}
int d[maxn], l[maxn] ;
bool vis[maxn] ;
queue <int> Q ;
void make ( int x ) {
	int i, u ;
	for ( i = Begin[x] ; i ; i = Next[i] ) {
		u = To[i] ;
		if (vis[u]) continue ;
		l[u] ++ ;
		break ;
	}
}
void solve ( int x ) {
	vis[x] = 1 ;
	int i, u, v ;
	for ( i = Begin[x] ; i ; i = Next[i] ) {
		u = To[i] ;
		if (vis[u]) continue ;
		if (l[u] > 1) {
			puts("First") ;
			exit(0) ;
		} else {
			vis[u] = 1 ;
			for ( i = Begin[u] ; i ; i = Next[i] ) {
				v = To[i] ;
				if (vis[v]) continue ;
				d[v] -- ;
				if (d[v] == 1) {
					Q.push(v) ;
					make(v) ;
				}
				return ;
			}
		}
	}
}
