        int a = in()-1;
        int b = in()-1;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
}

bool solve(){
    foreach(i,edges){
        if(i.size()==1)continue;
        int cnt = 0;
        foreach(j,i){
            if(edges[j].size()==1)++cnt;
        }
        if(cnt>=2)return true;
    }
    return false;
}

int main(){
    input();
    cout << (solve()?"First":"Second") << endl;
	return 0;
}

