using namespace std;



class Edge {
public:
	int lv;
	int rv;
	double w;
	Edge(int lv, int rv, double w) {
		this->lv = lv;
		this->rv = rv;
		this->w = w;
	}

	Edge(int r, int l) : Edge(r, l, 1) {}
};

class Graph {
public:
	vector<double> vs;
	vector<vector<Edge> > es;

	Graph(vector<double>& vs, vector<vector<Edge> >& es) {
		this->vs = vs;
		this->es = es;
	}

	Graph(int n, vector<vector<Edge> >& es) {
		this->vs = vector<double>(n, 0);
		this->es = es;
	}

	Graph(int n, vector<Edge>& es, bool isBidirectional) {
		this->vs = vector<double>(n, 0);
		this->es = vector<vector<Edge> >(n, vector<Edge>());

		for (int i = 0;i < es.size();i++) {
			this->es[es[i].lv].push_back(es[i]);
		}

		if (isBidirectional) {
			for (int i = 0;i < es.size();i++) {
				this->es[es[i].rv].push_back(Edge(es[i].rv, es[i].lv, es[i].w));
			}
		}
	}

	Graph(int n) {
		this->vs = vector<double>(n, 0);
		this->es = vector<vector<Edge> >();
	}

};


class Main {
public:
	void pairing(Graph& g, vector<bool>& paired, int root) {
		if (g.es[root].size() == 0) {
			return;
		} else {
			for (auto it = g.es[root].begin();it != g.es[root].end();++it) {
				pairing(g, paired, it->rv);
			}

			for (auto it = g.es[root].begin();it != g.es[root].end();++it) {
				int a = it->rv;
				bool b = paired[a];
				if (!paired[it->rv]) {
					paired[root] = true;
					paired[it->rv] = true;
					break;
				}
			}
			return;
		}
	}

	bool firstWins(Graph& tree) {
		vector<bool> paired(tree.vs.size(), false);
		pairing(tree, paired, 0);

		rep(i, paired.size()) {
			if (!paired[i]) {
				return true;
			}
		}
		return false;
	}
};

int main(void) {
	Main main;
	int n;
	cin >> n;

	vector<Edge> es;
	rep(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		int s = min(a, b);
		int l = max(a, b);
		es.push_back(Edge(s, l));
	}
	Graph g(n, es, false);

	string ans = main.firstWins(g) ? "First" : "Second";
	cout << ans << endl;

	return 0;
}

