const int MAXN = 2e5 + 5;

int last[MAXN + 5], other[MAXN + 5], pre[MAXN + 5];
int check[MAXN + 5][5];

int N, all = -1, ok = 0;

void build(int u, int v)
{
    pre[++all] = last[u];
    last[u] = all;
    other[all] = v;
}

void dfs(int ans, int fa)
{
    int a = 0, b = 0;
    int dt = last[ans];
    while(dt != -1){
        int dr = other[dt];
        if(dr != fa){
            dfs(dr, ans);
            if(check[dr][1] == 1){
                if(a == 1) ok = 1;
                else a = 1;
            }
            if(check[dr][2] == 1) b = 1;
        }
        dt = pre[dt];
    }
    if(b == 1) check[ans][1] = 1;
    if(a == 1) check[ans][2] = 1;
}

int main()
{
