    for(int i = 1; i <= N; i++) last[i] = -1;
    for(int i = 1; i < N; i++){
        int u, v;
        scanf("%d %d", &u, &v);
        build(u, v);
        build(v, u);
    }
    dfs(1, 1);
    if(ok == 1) printf("First\n");
    else printf("Second\n");
}

