void dfs(int v, int par = -1) {
    vector<int> sons;
    for (int to : g[v]) {
        if (to != par) {
            dfs(to, v);
            sons.emplace_back(to);
        }
    }
    int sz = (int)sons.size();
    dp[v][0] = 1;
    int good = 0;
    for (int to : sons) {
        if (!dp[to][1])dp[v][0]=0;
        if (dp[to][0])++good;
    }
    for (int to : sons) {
        if (good - dp[to][0] == sz - 1 && dp[to][1]) {
            dp[v][1] = 1;
        }
    }
}

