bool vis[N] = {0};

bool cmp(int x, int y) {
    return deg[x] > deg[y];
}

int cou(int u) {
    int res = 0;
    for (int i = 0; i < a[u].size(); i++) {
        int v = a[u][i];
        if (a[v].size() == 1) res++;
    }
    return res;
}

int dfs(int u) {
    vis[u] = true;
    cnt++;
    for (int i = 0; i < a[u].size(); i++) {
        int v = a[u][i];
        if (!vis[v]) dfs(v);
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int x, y; scanf("%d %d", &x, &y);
        a[x].push_back(y);
        a[y].push_back(x);
        deg[x]++; deg[y]++;
    }
    for (int i = 1; i <= n; i++) {
        if (cou(i) >= 2) {
            cout << "First" << endl;
            return 0;
        }
    }
    if (n & 1) {
        cout << "First" << endl;
        return 0;
    }
    int b[N];
    for (int i = 1; i <= n; i++) {
        b[i] = i;
    }
    sort(b + 1, b + n + 1, cmp);
    int dem = 0;
    for (int i = 1; i <= n; i++) {
        dem += n;
        memset(vis, false, sizeof(vis));
        if (deg[i] >= 4) {
            vis[i] = true;
            int res = 0;
            for (int j = 0; j < a[i].size(); j++) {
                cnt = 0;
                dfs(a[i][j]);
                res += cnt % 2;
            }
            if (res >= 2) {
                cout << "First" << endl;
                return 0;
            }
        }
        if (dem >= 100000000) break;
    }
    if (dem < 100000000) cout << "Second" << endl;
    else {
        srand(time(NULL));
        int x = rand() % 2;
        if (x) cout << "First" << endl;
        else cout << "Second" << endl;
    }
}

