struct spec
{
	int odd,even;
	spec operator +(const spec & a)const
	{
		spec aux;
		aux.odd=a.odd+odd;
		aux.even=a.even+even;
		return aux;
	}
}v[MaxN];
spec DFS(int node,int d)
{
	spec aux;
	D[node]=d;
	found[node]=true;
	int neigh=0;
	for(int i=0;i<Graph[node].size();i++)
		if(!found[Graph[node][i]])
			aux=aux+DFS(Graph[node][i],d+1),neigh++;
	swap(aux.even,aux.odd);
	if(neigh==0)
		aux.even=1,leaf[node]=true;
	return aux;
}
