	ll n; cin >> n;
	vvl path(n);
	REP(i, n - 1) {
		ll u, v; cin >> u >> v;
		u--,v--;
		path[u].push_back(v);
		path[v].push_back(u);
	}
	vl leafs;
	REP(i, n) if (path[i].size() == 1) leafs.push_back(i);

	vl deg(n); REP(i, n) deg[i] = path.size();
	vb used(n, 0);
	while (!leafs.empty()) {
		ll id = leafs.back();
		leafs.pop_back();

		// 葉の親を探す
		ll next = [&] {
			for (auto node : path[id]) if (!used[node]) {
				return node;
			}
			return -1ll;
		}();

		// 葉が孤独頂点だった場合
		if (next == -1) {
			cout << "First" << endl;
			return 0;
		} else {
			used[id] = 1;
			used[next] = 1;
			for (auto node : path[next]) if(!used[node]) {
				deg[node]--;
				if (deg[node] == 1) leafs.push_back(node);
			}
		}
	}
	cout << "Second" << endl;


