  fill(memo, memo+100000, INF);
  int from=0;
  rep(i,n) if(vec[i].size()==1){
    from=i;
    break;
  }
  memo[from]=1;
  int to=vec[from][0];
  while(vec[to].size()==2){
    memo[to] = memo[from]+1;
    rep(i,2) if(vec[to][i]!=from){
      from = to;
      to = vec[to][i];
