void check(vector<vector<int>> g, int n) {
    for (int i = 1; i <= n; i++) {
        if (g[i].size() == 1) {
            g[0].emplace_back(i);
            g[i].emplace_back(0);
        }
    }
    queue<int> que;
    que.emplace(0);
    vector<int> depth(n + 1, -1);
    vector<int> cnt(n + 1);
    cnt[0] = 1;
    depth[0] = 0;
    while (!que.empty()) {
        for (int i = que.size(); i > 0; i--) {
            int v = que.front();
            que.pop();
            for (int to : g[v]) {
                if (depth[to] != -1) {
                    continue;
                }
                depth[to] = depth[v] + 1;
                que.emplace(to);
                cnt[depth[to]]++;
            }
        }
    }
    for (int i = 1; i < n; i += 2) {
        if (cnt[i] == 0) {
            cout << "Second" << '\n';
            break;
        }
        if (cnt[i + 1] == 0) {
            if (cnt[i] == 1) {
                cout << "First" << '\n';
            } else {
                cout << "Second" << '\n';
            }
            break;
        }
        if (cnt[i] > cnt[i + 1]) {
            cout << "First" << '\n';
            break;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int x, y;
        cin >> x >> y;
        g[x].emplace_back(y);
        g[y].emplace_back(x);
    }
    vector<int> l(n + 1);
    for (int i = 1; i <= n; i++) {
        if (g[i].size() == 1) {
            l[g[i][0]]++;
        }
    }
    if (n == 2) {
        cout << "Second" << '\n';
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        if (l[i] > 1) {
            cout << "First" << '\n';
            return 0;
        }
    }
    vector<int> sz(n + 1, 1);
    vector<int> depth(n + 1, -1);
    depth[1] = 0;
    function<void(int, int)> dfs = [&](int v, int p) {
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            depth[to] = depth[v] + 1;
            dfs(to, v);
            sz[v] += sz[to];
        }
    };
    dfs(1, -1);
    for (int i = 0; i < n; i++) {
        if ((n - sz[i]) % 2 == 1) {
            continue;
        }
        bool ok = true;
        for (int j : g[i]) {
            if (sz[j] > sz[i]) {
                continue;
            }
            if (sz[j] % 2) {
                ok = false;
            }
        }
        if (ok) {
            cout << "First" << '\n';
            return 0;
        }
    }
    check(g, n);
    return 0;
}

