const int N = int(1e5) + 9;
const int NN = 10*N;
map<PII, int> E; vector<PII> L;

int n;
namespace DSU{ // Disjoint Set Union
    int P[N], R[N];
    inline void Make(int x){
        P[x] = x, R[x] = 0;
    }
    inline int Find(int x){
        return P[x] == x ? x : P[x] = Find(P[x]);
    }
    inline void Unionn(int x, int y){
        if (R[x] == R[y]) ++R[x];
        else if (R[x] < R[y]) swap(x, y);
        P[y] = x;
    }
    inline void Union(int x, int y){
        x = Find(x), y = Find(y);
        if (x != y) Unionn(x, y);
    }
    inline void Init(){
        REP(i, n) Make(i);
    }
} //using namespace DSU;

#define v (*it)
struct Tree{
    vector<int> adj[N];

    int d(int x){
        return adj[x].size();
    }

    void in(){
        REP(i, n) adj[i].clear();

        DO(n-1){
            int x, y; RD(x, y); --x, --y;
            adj[x].PB(y);
            adj[y].PB(x);
        }
        REP(u, n){
            ECH(it, adj[u]){
                if (u < v) E[MP(u, v)] += NN+d(u)+d(v);
            }
        }
    }
    void Del(PII e){
        int u = e.fi;
        ECH(it, adj[u]){
            int uu = DSU::Find(u), vv = DSU::Find(v);
            int x = min(uu, vv), y = max(uu, vv);
            E[MP(x, y)] -= NN+d(x)+d(y);
        }

        u = e.se;
        ECH(it, adj[u]){
            int uu = DSU::Find(u), vv = DSU::Find(v);
            int x = min(uu, vv), y = max(uu, vv);
            if (x != y) E[MP(x, y)] -= NN+d(x)+d(y);
        }
    }

    void Ins(PII e){
        if (e.fi < e.se) swap(e.fi, e.se);
        DSU::Union(e.fi, e.se);
        ECH(it, adj[e.fi]) if (e.se == v){
            adj[e.fi].erase(it);
            break;
        }
        ECH(it, adj[e.se]) if (e.fi != v) adj[e.fi].PB(v); adj[e.se].clear();
        int u = e.fi;
        ECH(it, adj[e.fi]){
            int uu = DSU::Find(u), vv = DSU::Find(v);
            int x = min(uu, vv), y = max(uu, vv);
           // cout << " 1 " << x << " " << y << endl;
            if (x != y){
                PII e =MP(x, y);
                if ((E[e] += NN+d(x)+d(y)) > 2*NN){
                    L.PB(e);
                }
            }
        }

    }

} R, B;

