    while (!L.empty()){
        PII e = L.back(); L.pop_back();
        e.fi = DSU::Find(e.fi);
        e.se = DSU::Find(e.se);
        if (E[e] > 2*NN){
            R.Del(e); B.Del(e);
            R.Ins(e); B.Ins(e);
