vector<int> G[100005];
int used[100005];
bool ans;

bool search(int s, int tama){
	vector<int> children;
	used[s]=true;
	rep(i,G[s].size()){
		if(!used[G[s][i]]){
			children.push_back(G[s][i]);
		}
	}
	if(children.size() == 0){
		if(tama%2==0){
			//cout<<s<<"a"<<endl;
			return true;
		}
	}
	if(children.size()==1){
		//cout<<s<<"b"<<endl;
		return search(children[0],tama+1);
	}
	int count=0;
	rep(i,children.size()){
		if(search(children[i],0)){
			count++;
		}
	}
	if(count == 2){
		//cout<<s<<"c"<<endl;
		ans=true;
		return true;
	}
	if(count==1 && tama%2 == 1){
		//cout<<s<<"d"<<endl;
		return true;
	}
	//cout<<s<<"e"<<endl;
	return false;
}

int main(void){
	int n,a,b;
	cin>>n;
	rep(i,n-1){
		cin>>a>>b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	reps(i,n){
		used[i]=false;
	}
	ans = false;
	bool memo = search(1,0);
	if(memo || ans){
		cout<<"First"<<endl;
	}else{
		cout<<"Second"<<endl;
	}
	return 0;
}

