using namespace std;

#define MAX_N 100005

int N;

vector<int> Edge[MAX_N];

int inEdge[MAX_N];

bool dfs(int pos, int pre = -1, int cnt = 0)
{

  int C = 0;
  for (int i = 0; i < Edge[pos].size(); i++) {
    int next = Edge[pos][i];
    if(next == pre){
      continue;
    }
    C++;
    if(dfs(next, pos, cnt+1)){
      return true;
    }
  }

  if(C == 0 && cnt%2 == 0){
    return true;
  }
  else if(C == 0 && cnt%2 == 1){
    return false;
  }
  else{
    return false;
  }

}

int main()
{
  cin >> N;
  for (int i = 0; i < N-1; i++) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    Edge[a].push_back(b);
    Edge[b].push_back(a);
    inEdge[a]++; inEdge[b]++;
  }

  for (int i = 0; i < N; i++) {
    if(inEdge[i] == 1){
      if(dfs(i)){
        cout << "First" << endl;
      }
      else{
        cout << "Second" << endl;
      }
      return 0;
    }
  }

  return 0;
}

