string const F = "First";
string const S = "Second";

int const N = 1e5 + 41;

vector<int> e[N];
int root;
int l[N];
int n;
int d[N];

void print(string ans){
	cout << ans << endl;
	exit(0);
}

int dfs(int u, int p){
	if(sz(e[u]) == 1) l[u] = 1;
	int cnt = 0;
	rep(i, 0, sz(e[u])){
		int to = e[u][i];
		if(to == p) continue;
		cnt += dfs(to, u);
	}
	if(cnt > 1) print(F);
	return l[u];
}

void dfs2(int u, int p){
	if(u == p) e[u].pb(u);
	if(l[u]){
		return;
	}
	int cntOne = 0;
	int cntTwo = 0;
	int cntL = 0;
	rep(i, 0, sz(e[u])){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs2(to, u);
		if(l[to]){
			++cntL;
		}else if(d[to] == 1){
			++cntOne;
		}else if(d[to] == 2){
			++cntTwo;
		}
	}
	if(cntTwo > 1) print(F);
	if(cntTwo > 0){
		if(cntL > 0){
			print(F);
		}
	}
	if(cntOne + cntTwo == sz(e[u]) - 1){
		d[u] = 2;
	}else{
		if(cntL > 0) d[u] = 1;
	}
}

void solve(){
	cin >> n;
	rep(i, 0, n-1){
		int a, b;
		cin >> a >> b;
		--a;--b;
		e[a].pb(b);
		e[b].pb(a);
	}

	rep(i, 0, n) if(sz(e[i]) > sz(e[root])) root = i;
	dfs(root, root);
	dfs2(root, root);


	print(S);
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();

	return 0;
}

