        g[a].push_back(b);
        g[b].push_back(a);
        d[a]++;
        d[b]++;
    }
    ll root=0;
    rep(n)if(d[i]==1)root=i;
    vec(unordered_set<ll>,child,n);
    vec(ll,parent,n);
    auto dfs=[&](ll from,ll at,auto f)->void{
        each(i,g[at])if(i!=from){
            child[at].insert(i);
            parent[i]=at;
            f(at,i,f);
        }
    };
    dfs(-1,0,dfs);
    queue<ll>q;
    rep(n)if(d[i]==2)q.push(i);
    while(q.size()){
        ll at=q.front();
        q.pop();
        ll p,c;
        if(d[at]==1&&at!=root){
            p=parent[at];
            c=at;
            if(d[p]<1||2<d[p])continue;
        }
        elif(d[at]==2||at==root){
            p=at;
            c=*child[at].begin();
            if(d[c]!=1)continue;
        }
        else continue;
        each(i,g[p])d[i]--;
        each(i,g[c])d[i]--;
        q.push(parent[p]);
    }
    each(i,d)if(i)return out("First");
    out("Second");
}

