			win = true;
		}
	}

	int degmax[2] = {-1, -1};
	int node[2] = {-1, -1};

	int cont = 0;

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

		if (u == par)
			continue;

		if (deg[u] > degmax[0])
		{
			degmax[1] = degmax[0];
			node[1] = node[0];

			node[0] = u;
			degmax[0] = deg[u];
		}
		else
			if (deg[u] > degmax[1])
			{
				degmax[1] = deg[u];
				node[1] = u;
			}
	}

	for (int i = 0; i < adj[v].size(); ++i)
	{
		int u = adj[v][i];

