void dfs2(int u, int p){
	if(u == p) e[u].pb(u);
	if(l[u]){
		return;
	}
	int cntOne = 0;
	int cntTwo = 0;
	int cntL = 0;
	rep(i, 0, sz(e[u])){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs2(to, u);
		if(l[to]){
			++cntL;
		}else if(d[to] == 1){
			++cntOne;
		}else if(d[to] == 2){
			++cntTwo;
		}
	}
	if(cntTwo > 1 || cntOne > 1) print(F);
	if(cntTwo > 0){
		if(cntL > 0){
			print(F);
		}
	}
	if(cntOne == sz(e[u]) - 1){
		d[u] = 2;
	}else{
		if(cntL > 0) d[u] = 1;
	}
}

