    bool del[100002]{0};
    for(int i = 0; i < n; i++){
        int u = p[i].second;
        int k = 0;
        for(int v : t.t[u]){
            if(!del[v]) k++;
            del[v] = true;
        }
        if(k >= 2){
            cout << "First" << endl;
            return 0;
        }
        if(k == 1){
            del[u] = true;
        }
    }
    cout << "Second" << endl;
}

