  for(int i = 1; i < N; i++) {
    int a, b; scanf("%d%d", &a, &b);
    gph[a].push_back(b);
    gph[b].push_back(a);
    deg[a] += 1;
    deg[b] += 1;
  }

  try {
    if(N <= 2) throw "Second";

    priority_queue< pii, vector<pii>, greater<pii> > pq;
    for(int i = 1; i <= N; i++) {
      pq.push(pii(deg[i], i));
    }

    auto go = [&pq](int u) {
      chk[u] = true;
      for(int v : gph[u]) if(!chk[v]) pq.push(pii(--deg[v], v));
    };

    while(!pq.empty()) {
      int d, u; tie(d, u) = pq.top(); pq.pop();
      if(deg[u] != d || chk[u]) continue;

      if(deg[u] == 0) throw "First";

      go(u);

      for(int v : gph[u]) if(!chk[v]) {
        go(v);
        break;
      }
    }
    throw "Second";
  }catch(const char* s) {
    cout << s << endl;
  }
  return 0;
}

