        {
            even[c] = true;
            return;
        }

        int ec = 0;
        int oc = 0;
        for (int e: E[c])
        if (e != p)
        {
            BT(e, c);
            if (even[e])
                ec++;
            if (odd[e])
                oc++;
        }
        if (ec>0)
            odd[c] = true;
        if (oc>0)
            even[c] = true;
        if (ec>=2 ||
            (p==-1 && E[c].size()==1 && oc>0))
            ans = true;
    };
    BT(0, -1);
    cout<<(ans ? "First" : "Second")<<endl;
