struct bipartite_matching {
	VVI g;
	VI match;
	VI used;

	bipartite_matching(int N) {
		g = VVI(N);
	}

	int dfs(int v) {
		used[v]=1;
		for(int i=0;i<(int)g[v].size();i++) {
			int u=g[v][i], w=match[u];
			if(w<0 || (!used[w] && dfs(w))) {
				match[v]=u;
				match[u]=v;
				return 1;
			}
		}
		return 0;
	}

	int run() {
		int res=0;
		match=VI(g.size(), -1);
		for(int v=0;v<(int)g.size();v++){
			if(match[v]<0) {
				used=VI(g.size());
				if(dfs(v)) res++;
			}
		}
		return res;
	}

	void add_edge(int u, int v){
		g[u].push_back(v);
		g[v].push_back(u);
	}
};

bool z;
bool dfs(int u, int p, VVI& G) {
	int x = 0;
	for (int v: G[u]) if (v != p) x += dfs(v, u, G);
	if (x == 0) return true;
	if (x == 1) return false;
	z = true;
	return false;
}
bool dfs2(int u, int p, VVI& G) {
	int x = 0;
	int ch=0;
	for (int v: G[u]) if (v != p) {
		ch++;
		x += dfs2(v, u, G);
	}
	if(ch==0) return false;
	else if(x<ch-1) {
		z = true;
		return false;
	} else return x==ch-1;
}
