    int a,b;
    cin >> a >> b;
    a--; b--;
    Graph[a].push_back(b);
    Graph[b].push_back(a);
  }

  BFS();

  for (int i = N-1; i >= 0; i--) {
    for (int j = 0; j < (int)Depth[i].size(); j++) {
      int s = Depth[i][j];
      int ch = 0;
      vector<int> vec;
      if (i == 1) ch++;
      for (int k = 0; k < (int)child[s].size(); k++) {
        if (exist[child[s][k]]) {
          vec.push_back(child[s][k]);
          ch++;
        }
      }
      if (i <= 1) {
        if (ch >= 2) {
          can = true;
        }
      } else {
        if (ch == 0) {
          continue;
        } else if (ch == 1) {
          exist[s] = false;
          exist[vec[0]] = false;
        } else if (ch >= 2) {
          can = true;
        }
      }
    }
    if (can) {
      break;
    }
  }

  if (can) {
    cout << "First" << endl;
  } else {
    cout << "Second" << endl;
  }
  return 0;
}

