        edges[b].push_back(a);
    }
    vector<bool> used(n, false);
    function<void(int, int)> dfs = [&](int c, int p) {
        for (auto &v : edges[c]) {
            if (v == p)
                continue;
            dfs(v, c);
        }
        if (!used[c] && p != -1) {
            used[c] = used[p] = true;
        }
    };
    dfs(0, -1);
    bool match = true;
    for (int i = 0; i < n; ++i) {
        if (!used[i]) {
            match = false;
            break;
        }
    }
    if (match) {
        cout << "Second"
             << "\n";
    } else {
        cout << "First"
             << "\n";
    }
    return 0;
}

