class HashVI {  // ハッシュ関数オブジェクト
public:
    size_t operator()(const vector<int> &x) const {
        const int C = 997;      // 素数
        size_t t = 0;
        for (int i = 0; i != x.size(); ++i) {
            t = t * C + x[i];
        }
        return t;
    }
};

