            if(to == par) continue;
            self(self, to, cur);
            deg++;
            for(int k=0; k<2; k++) cnt[k] += dp[to][k];
        }

        dp[cur][0] = 1;
        for(auto to : G[cur]) {
            if(to == par) continue;
            dp[cur][0] &= dp[to][1];
            dp[cur][1] |= (dp[to][0] and deg - 1 == cnt[1] - dp[to][1]);
        }
        // fprintf(stderr, "cur = %d, dp = (%d, %d)\n", cur, dp[cur][0], dp[cur][1]);
    };

    dfs(dfs, 0, -1);
    printf("%s\n", (dp[0][1] ? "Second" : "First"));
