int main(){
	int N,a[100001],b[100001];
	int p[100001];
	bool black[100001]={};
	int blacknum=0;
	int edgecount[100001]={};
	vint connect[100001];
	vint leaf;
	scan(N);
	fill(p,p+N+1,-1);
	rep(i,N-1){
		scan(a[i]);scan(b[i]);
		connect[a[i]].push_back(b[i]);
		connect[b[i]].push_back(a[i]);
		if(edgecount[a[i]]==0&&edgecount[b[i]]==0){
			p[a[i]]=b[i];
		}
		else{
			if(edgecount[a[i]]>edgecount[b[i]]){
				p[b[i]]=a[i];
			}
			else{
				p[a[i]]=b[i];
			}
		}
		edgecount[a[i]]++;
		edgecount[b[i]]++;
	}
	if(N==2){
		prin("Second");
		return 0;
	}
	rep1(i,N){
		if(edgecount[i]==1) leaf.push_back(i);
	}
	rep(i,leaf.size()){
		if(black[leaf[i]]==false){
			black[leaf[i]]=1;
			blacknum++;
		}
		else continue;
		int nownode=leaf[i];
		while(1){
			if(p[nownode]==-1) break;
			else if(p[p[nownode]]==-1) break;
			else if(black[p[nownode]]==false&&black[p[p[nownode]]]==false){
				black[p[p[nownode]]]=true;
				nownode=p[p[nownode]];
				blacknum++;
			}
			else break;
		}
	}
	rep(i,leaf.size()){
		if(black[connect[leaf[i]][0]]){
			black[connect[leaf[i]][0]]=false;
			blacknum--;
		}
	}
	if(blacknum>N/2) prin("First");
	else prin("Second");
	return 0;
}

