  is_visited[node] = true;

  int odd = 0;
  for (int e : edge[node]) {
    if (!is_visited[e]) {
      int r = dfs(e, is_visited);
      if (r < 0) {
        return -1;
      }
      odd += r;
    }
  }
  if (odd >= 2) {
    return -1;
  } else if (odd == 1) {
    return 0;
  } else {
    return 1;
  }
}

