    for (int i=1;i<n;i++){
        scanf("%d%d",&x,&y);
        add(x,y); add(y,x);
    }
    dfs2(1,-1); dfs(1,-1);
    if (flag||dp[1]) puts("First");
    else puts("Second");
    return 0;
}

