int dfs (int x, int f = -1) {
	int d = 0, cnt = 0, del = 1;
	for (int i = 0; i < e[x].size (); i++) {
		if (e[x][i] == f) continue;
		d = std::max (d, dfs (e[x][i], x));
		if (magic[e[x][i]] != 1) del = 0;
		if (magic[e[x][i]] == 2) {
			cnt++;
			magic[x] = 1;
		}
		size[x] += size[e[x][i]];
	}
	if (del) magic[x] = 2;
	size[x]++;
	if (cnt >= 2) return 1;
	return d;
}

