        graph[b].push_back(a);
        ++deg[a];
        ++deg[b];
    }

    vector<bool> used(N);
    queue<int> que;
    rep(i,0,N) if(deg[i]==1) que.push(i);
    while(!que.empty()){
        int u=que.front();
