	N -= q[0].size() + q[1].size();

	// wyczysc liscie
	while (!q[0].empty())
		q[0].pop();

	while (N)
	{
		// przetwarzaj rodzicow i wyznacz nowe liscie
		while (!q[1].empty())
		{
			int akt = q[1].front(); q[1].pop();
			for (auto v : g[akt])
				if (!done[v])
				{
					q[0].push(v);
					done[v] = 1;
					N--;
					break;
				}
		}

		int ileL = q[0].size();

		// wyznacz nowych rodzicow
		vector<int> cp;
		while (!q[0].empty())
		{
			int akt = q[0].front(); q[0].pop(); cp.push_back(akt);
			for (auto v : g[akt])
				if (!done[v])
				{
					q[1].push(v);
					done[v] = 1;
					N--;
					break;
				}
		}

		if (q[1].size() < ileL)
		{
			// spr czy jest jakis nieparzysty komponent wsrod lisci
			for (auto v : cp)
				lastL[v] = 1;
			cc = 0;
			for (auto v : cp)
				if (!doneL[v])
				{
					cc++;
					dfs(v);
				}
			for (auto v : cp)
				sz[doneL[v]]++;
			FORQ(i, 1, cc)
				if (sz[i] % 2)
					return 0;
			for (auto v : cp)
				lastL[v] = 0;
		}
	}

	return 1;
}

