    in(N);
    tree<> g(2 * k5);
    g.ing(N, N - 1);
    auto win = [&](int i) {
        if (i)fin("First");
        else fin("Second");
    };
    if (N == 2) {
        win(0);
    }
    g.root_change_mid();
    deb(g.root);
    mapp map;
    fix([&](auto ds, int p, int i) -> int {
        if (g.leaf(i)) {
            map[mp(p, i)] = 1;
        }
        if (map.count(mp(p, i)))return map[mp(p, i)];
        int v = -1;
        fort(gi, g[i]) {
            int nv = ds(i, t);
            if (v == -1)v = nv ^ 1;
            else if (v != (nv ^ 1))v = 2;
        }
        return map[mp(p, i)] = v;
        deb(p, i);
    })(-1, g.root);
    deb(map);
    fix([&](auto ds, int p, int i) -> void {
        int n = sz(g[i]);
        int eq = 0;
        int t0 = g[i][0].t;
        int guki = map[mp(i, t0)];
        int othert = t0;
        forg(gi, g[i]) {
            if (guki == map[mp(i, t)])eq++;
            else othert = t;
        }
        if(eq==1)othert = t0;
        fort(gi, g[i]) {
            map[mp(t, i)] = 2;
        }
        //全部ok
        if (eq == n) {
            fort(gi, g[i]) {
                map[mp(t, i)] = guki ^ 1;
            }
        } else if ((eq == 1 || eq == n - 1) && othert != p) {
            map[mp(othert, i)] = guki ^ 1;
        }
        deb(p, i);
    })(-1, g.root);
    deb(map);
    rep(i, N){
        int cou=0;
        forg(gi, g[i]){
            int guki = map[mp(i,t)];
            if(guki == 1)cou++;
        }
        if(cou>=2){
            win(1);
        }
    }
    win(0);
}


