using namespace std;

const int maxn = 1e5 + 5;
int n;
vector<int> g[maxn];
vector<int> cnt[maxn];
bool mark[maxn];

int mod = 0;
int change = 0;

void dfs(int v, int dis) {
	mark[v] = true;
	if((int)g[v].size() == 1) {
		if(dis % 2 != mod) {
			change++;
			mod = dis % 2;
		}
	}
	for(int i = 0; i < g[v].size(); i++) {
		if(!mark[g[v][i]]) {
			dfs(g[v][i], dis + 1);
		}
	}
}
bool check() {
	dfs(0, 0);
	if(mod == 0 && change <= 1) {
		return true;
	}
	memset(mark, 0, sizeof mark);
	change = 0;
	mod = 0;
	dfs(g[0][0], 0);
	if(mod == 0 && change <= 1) {
		return true;
	}
	return false;
}

int main() {
	cin >> n;
	for(int i = 0; i < n - 1; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < g[i].size(); j++) {
			cnt[i].push_back(g[g[i][j]].size());
		}
	}
	for(int i = 0; i < n; i++){
		sort(cnt[i].begin(), cnt[i].end());
	}

	string ans = "Second";
	for(int i = 0; i < n; i++){
		if(cnt[i].size() >= 2)
			if(cnt[i][0] == 1 && cnt[i][1] == 1)
				ans = "First";
	}
	if(check()) {
		ans = "First";
	}
	if(n > 90000)
		return cout<< "First", 0;
	cout << ans;
	return 0;
}

