/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */

int main() {
    int N;
    cin >> N;

    int cnt[N];
    fill(cnt, cnt + N, 0);

    vector<int> path[N];

    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        ++cnt[--a], ++cnt[--b];
        path[a].push_back(b);
        path[b].push_back(a);
    }

    vector<int> one;
    // cnt[v] = 1なる頂点の集合

    for (int v = 0; v < N; ++v) {
        if (cnt[v] == 1) one.push_back(v);
    }

    while (!one.empty()) {
        int v = one.back();
        one.pop_back();
        if (cnt[v] != 1) continue;

        int w;
        for (int sv : path[v]) {
            if (cnt[sv] < INF) w = sv;
        }

        cnt[w] = INF * 2;

        vector<int> zero;
        for (int sv : path[w]) {
            --cnt[sv];
            if (cnt[sv] == 1) one.push_back(sv);
            if (cnt[sv] == 0) zero.push_back(sv);
        }

        // cout << v << ":" << w << "->" << zero << endl;

        if (zero.size() > 1) {
            cout << "First" << endl;
            return 0;
        }

        cnt[zero.back()] = INF * 2;
    }

    cout << "Second" << endl;
    return 0;
}

