bool good[100001];
int rest;

int dfs(int v){
	used[v]=true;
	if(G[v].size()>=3){
		used[v]=false;
		if(cnt[v]>=1)return 1;
		return -1000000;
	}
	for(int i=0;i<G[v].size();i++){
		if(!used[G[v][i]] && !used2[G[v][i]]){
			return (dfs(G[v][i])+1);
		}
	}
}

void dfs2(int v,int d){
	used2[v]=true;
	if(G[v].size()>=3){
		used[v]=false;
		if(d%2==1)good[v]=true;
		return;
	}
	rest--;
	for(int i=0;i<G[v].size();i++){
		if(!used2[G[v][i]]){
			dfs2(G[v][i],d+1);
		}
	}
}

bool solve(){
	if(rest==1)return true;
	memset(cnt,0,sizeof(cnt));
	for(int i=0;i<n;i++){
		if(e[i]==1){
			cnt[G[i][0]]++;
		}
	}
	for(int i=0;i<n;i++){
		if(cnt[i]>=2){
			return true;
		}
	}
	int on=0,se=0;
	bool flag=true;
	for(int i=0;i<n;i++){
		if(e[i]==1){
			on++;
		}
		if(e[i]==2){
			se++;
		}
		if(e[i]>2){
			flag=false;
		}
	}
	if(flag && on==2 && se==n-2){
		return (n%2==1);
	}
	for(int i=0;i<n;i++){
		if(!used[i] && e[i]==1){
			if(dfs(i)==4){
				return true;
			}
		}
	}
	memset(used,false,sizeof(used));
	for(int i=0;i<n;i++){
		if(cnt[i]==1){
			for(int j=0;j<G[i].size();j++){
				if(used[G[i][j]] && G[G[i][j]].size()==2){
					printf("First\n");
					return 0;
				}
				used[G[i][j]]=true;
			}
		}
	}
	memset(good,false,sizeof(good));
	for(int i=0;i<n;i++){
		if(!used[i] && e[i]==1){
			dfs2(i,0);
		}
	}
	bool flag2=false;
	for(int i=0;i<n;i++){
		if(e[i]>=3 && !good[i]){
			e[i]=1;
			flag2=true;
		}
		if(e[i]>=3 && good[i]){
			return false;
		}
	}
	if(!flag2)return false;
	return solve();
}

