int main() {
	int N = in();
	vector<V> G(N);
	for (int i = 0; i < N - 1; i++) {
		int a = in() - 1;
		int b = in() - 1;
		G[a].add_edge(b);
		G[b].add_edge(a);
	}

	stack<int> leaves;
	for (int i = 0; i < N; i++) if (G[i].dim == 1) leaves.push(i);
	bool firstwins = false;
	while (! leaves.empty()) {
		int l = leaves.top();
		leaves.pop();
		V &v = G[l];
		if (! v.alive) continue;
		if (v.dim <= 0) {
			firstwins = true;
			break;
		}
		int par = -1;
		for (int i = 0; i < v.e.size(); i++) if (G[v.e[i]].alive) {
			par = v.e[i];
			break;
		}
		assert(par >= 0);
		v.alive = false;
		G[par].alive = false;
		for (int i = 0; i < G[par].e.size(); i++) {
			V &w = G[G[par].e[i]];
			if (w.alive) {
				w.dim--;
				if (w.dim <= 0) {
					firstwins = true;
					goto END;
				}
				if (w.dim == 1) {
					leaves.push(G[par].e[i]);
				}
			}
		}
	}END:;
	cout << (firstwins ? "First" : "Second") << endl;
	return 0;
}

