const int MAXN = 100001;
const int INF = 1000000000;


int n;
vector<int> v[MAXN];
bool keks[MAXN];
bool used[MAXN];


inline bool kek(int x, int pr) {
    if (used[x]) {
        return keks[x];
    }
    used[x] = 1;
    bool ok = 0;
    int cnt = 0;
    for (auto h: v[x]) {
        if (h == pr) {
            continue;
        }
        if (sz(v[h]) == 1) {
            ok = 1;
        } else {
            if (!kek(h, x)) {
                cnt++;
                break;
            }
        }
    }
    keks[x] = ok && (cnt == 0);
    return keks[x];
}


int main() {
    n = readInt();
    if (n == 1) {
        writeWord("First\n");
        return 0;
    }
    for (int i = 0; i < n - 1; i++) {
        int a = readInt(), b = readInt();
        a--, b--;
        v[a].push_back(b);
        v[b].push_back(a);
    }    
    for (int i = 0; i < n; i++) {
        int cnt = 0;
        for (auto x: v[i]) {
            if (sz(v[x]) == 1) {
                cnt++;
            }
        }
        if (cnt > 1) {
            writeWord("First\n");
            return 0;
        }
    }
    for (int i = 0; i < n; i++) {
        if (sz(v[i]) < 2) {
            continue;
        }
        bool bad = 0;
        for (auto x: v[i]) {
            if (sz(v[x]) == 1) {
                bad = 1;
                break;
            }
        }
        if (bad) {
            continue;
        }
        for (auto x: v[i]) {
            if (!kek(x, i)) {
                bad = 1;
                break;
            }
        }
        if (!bad) {
            writeWord("First\n");
            return 0;
        }
    }
    writeWord("Second\n");
    return 0;
}

