#define INFL 0x3f3f3f3f3f3f3f3fLL
typedef long long ll;

int N;
vector<int> G[100010];
string Takahashi = "First";
string Aoki = "Second";

int end_cnt(int v) {
    int ret = 0;
    REP(i,G[v].size()) {
        int nxt = G[v][i];
        if(G[nxt].size() == 1) {
            int rev_nxt = G[nxt][0];
            if(rev_nxt == v) ret++;
        }
    }
    return ret;
}

int cnt2(int v, int ori) {
    int ret = 1;
    REP(i,G[v].size()) {
        if(end_cnt(G[v][i]) == 0) {
            if(G[v][i] != ori) ret = 0;
        }
    }
    return ret;
}

int main() {

    cin >> N;
    REP(i,N-1) {
        int a,b; cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    for(int i=1; i<=N; i++) {
        if(end_cnt(i) >= 2) {
            cout << Takahashi << endl;
            return 0;
        }
    }

    for(int i=1; i<=N; i++) {
        if(end_cnt(i) == 0 && G[i].size() > 1) {
            REP(j,G[i].size()) {
                if(end_cnt(G[i][j]) == 0) goto nextf;
            }
            cout << Takahashi << endl;
            return 0;
        }
    nextf:;
    }

    /* --- */
    for(int i=1; i<=N; i++) {
        if(end_cnt(i) == 0 && G[i].size() > 1) {
            int cnt = 0;
            REP(j,G[i].size()) {
                int nxt = G[i][j];
                cnt += cnt2(nxt,i);
            }
            if(cnt >= 2) {
                cout << Takahashi << endl;
                return 0;
            }
        }
    }

    cout << Aoki << endl;

    return 0;
}

