#include <bits/stdc++.h>
using namespace std;

const int N = 100000 + 10;
const int oo = 0x3f3f3f3f;

int n, m;
vector<int> g[N];
int deg[N], dist[N], qu[N], bg, ed;

void first() {
	printf( "First\n" );
	exit(0);
}
void second() {
	printf( "Second\n" );
	exit(0);
}
void bfs() {
	memset( dist, 0x3f, sizeof(dist) );
	bg = 1, ed = 0;
	for( int u = 1; u <= n; u++ ) {
		if( deg[u] == 1 ) {
			qu[++ed] = u;
			dist[u] = 1;
		}
	}
	while( bg <= ed ) {
		int u = qu[bg++];
		for( int t = 0; t < (int)g[u].size(); t++ ) {
			int v = g[u][t];
			if( dist[v] == oo ) {
				qu[++ed] = v;
				dist[v] = dist[u] + 1;
			}
		}
	}
}
int main() {
	scanf( "%d", &n );
	for( int i = 1; i < n; i++ ) {
		int u, v;
		scanf( "%d%d", &u, &v );
		deg[u]++;
		deg[v]++;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	bfs();
	int cnt = 0;
	for( int u = 1; u <= n; u++ ) {
		if( dist[u] & 1 ) cnt++;
	}
	if( cnt <= n - cnt ) second();
	else first();
}

