void solve(long long N, std::vector<long long> a, std::vector<long long> b)
{
  rep(i, N - 1) a[i]--, b[i]--;
  rep(i, N - 1) e[a[i]].push_back(b[i]), e[b[i]].push_back(a[i]);
  rep(i, N) leaf[i] = e[i].size() == 1;
  lli cnt = 0;
  rep(i, N)
  {
    int leafs = 0;
    for (auto s : e[i])
