using namespace std;
inline int gcd(int a, int b) {
	while (b) {
		int c = a;
		a = b; b = c % b;
	}
	return a;
}
inline int lcm(int a, int b) {
	return a / gcd(a, b) * b;
}
bool isprime(int n) {
	if (n == 1)return false;
	for (int i = 2; i * i <= n; i++) {
		if (n % i == 0)return false;
	}
	return true;
}
int mypow(int a, int b) {
	if (!b)return 1;
	if (b & 1)return mypow(a, b - 1) * a;
	int memo = mypow(a, b >> 1);
	return memo * memo;
}
int modpow(int a, int b, int m = mod) {
	if (!b)return 1;
	if (b & 1)return modpow(a, b - 1, m) * a % m;
	int memo = modpow(a, b / 2, m);
	return memo * memo % m;
}
int n, a, b, cnt[100010], parent[100010];
vector<int> vec[100010];
bool used[100010];
queue<int> leaf;
void dfs(int node) {
	used[node] = true;
	bool isparent = false;
	for (int i : vec[node]) {
		if (!used[i]) {
			isparent = true;
			parent[i] = node;
			dfs(i);
		}
	}
	if (!isparent) {
		leaf.push(node);
	}
}
signed main() {
	cin >> n;
	rep(i, n - 1) {
		cin >> a >> b;
		vec[a].push_back(b);
		vec[b].push_back(a);
		cnt[a]++; cnt[b]++;
	}
	dfs(1);
	fill(used + 1, used + n + 1, false);
	while (!leaf.empty()) {
		int node = leaf.front();
		leaf.pop();
		if (node == 1 || used[parent[node]]) {
			puts("First");
			return 0;
		}
		used[node] = true;
		used[parent[node]] = true;
		if (parent[node] != 1) {
			cnt[parent[parent[node]]]--;
			if (cnt[parent[parent[node]]] == 1) {
				leaf.push(parent[parent[node]]);
			}
		}
	}
	REP(i, n) {
		if (!used[i]) {
			puts("First");
			return 0;
		}
	}
	puts("Second");
	return 0;
}

