	if(P[fa].size()==1)
		cnt++,p=fa;
	for(int i=0;i<size;i++){
		int v=P[u][i];
		if(v==fa)continue;
		dfs(v,u);
		if(P[v].size()==1)
			cnt++,p=v;
	}
	if(cnt>=2)Ok=1;
	if(cnt==1){
		col[u]=1;
		col[p]=-1;
	}
}
