			g[a].push_back({b,1});
			g[b].push_back({a,1});
		}

		vector<bool> used(N); queue<int> que;
		for(int i:range(N))if(g[i].size()==1){
			que.push(i);
		}

		vector<int> inc(N);
		while(!que.empty()){
			int i = que.front();que.pop();
			// unique
			for(auto e:g[i])if(!used[e.to] && !used[i]){
				used[i] = used[e.to] = true;
				for(auto e2:g[e.to])if(!used[e.to]){
					inc[e.to]++;
					if(inc[e.to] == g[e.to].size()-1){
