bool solve() {
  vector<int> ch;
  queue<int> bl, wh;
  ch.assign(n, 0);
  for (int i = 0; i < n; ++i)
    if (g[i].size() == 1) bl.push(i);
  while (bl.size() || wh.size()) {
    while (bl.size()) {
      int now = bl.front();
      bl.pop();
      for (auto to : g[now]) {
        g[to].erase(now);
        if (ch[to]) return 1;
        ch[to] = 1;
        if (g[to].size() == 1) wh.push(to);
      }
    }
    while (wh.size()) {
      int now = wh.front();
      wh.pop();
      if (!ch[now]) return 1;
      for (auto to : g[now]) {
        g[to].erase(now);
        if (g[to].size() == 1) {
          if (ch[to])
            wh.push(to);
          else
            bl.push(to);
        }
      }
    }
  }
  return 0;
}

