int n;
vector<tuple<int, int>> graph[N];
int used[N];
int size[N];
int from[N];
int tcolor[N], color[N];

void calc(int v, int p) {
	size[v] = 1;
	for (auto nxt : graph[v]) {
		int to, cost; tie(to, cost) = nxt;
		if (to != p && !used[to]) {
			calc(to, v);
			from[to] = v;
			size[v] += size[to];
		}
	}
}

void go(int v = 0, int turn = 0) {
	calc(v, v);
	from[v] = v;
	int centroid = v;
	int comsz = 0;
	int best = size[v];
	queue<int> q;
	q.push(v);
	vector<pair<int, int>> adj;
	while (!q.empty()) {
		int cur = q.front(); q.pop();
		int sz = size[v] - size[cur];
		comsz++;
		for (auto nxt : graph[cur]) {
			int to, cost; tie(to, cost) = nxt;
			if (used[to]) continue;
			if (from[cur] == to) continue;
			sz = max(sz, size[to]);
			q.push(to);
		}
		if (sz < best) {
			best = sz;
			centroid = cur;
		}
	}
	used[centroid] = 1;
	tcolor[centroid] = turn;
	for (auto nxt : graph[centroid]) {
		int to, cost; tie(to, cost) = nxt;
		if (used[to]) continue;
		if (to == from[centroid]) adj.pb({size[v] - size[centroid], to});
		else adj.pb({size[to], to});
	}
	sort(adj.begin(), adj.end(), greater<pair<int, int>>());
/*	for (auto nxt : graph[centroid]) {
		int to, cost; tie(to, cost) = nxt;
		if (used[to]) continue;
		go(to, turn ^ 1);
		turn ^= 1;
	}
*/
	for (auto it : adj) {
		int to = it.snd;
		go(to, turn ^ 1);
		turn ^= 1;
	}
}

