	scanf("%d", &n);
	for (int i = 0; i + 1 < n; i++) {
		int a, b; scanf("%d%d", &a, &b); a--, b--;
		graph[a].pb(mt(b, 0));
		graph[b].pb(mt(a, 0));
	}
	go();
	for (int i = 0; i < n; i++) color[i] = tcolor[i];
	for (int i = 0; i < n; i++) if (tcolor[i]) for (auto nxt : graph[i]) {
		int to, cost; tie(to, cost) = nxt;
		color[to] = 1;
	}
	int ans = 0;
	for (int i = 0; i < n; i++) ans += color[i];
	if (ans == n) printf("Second\n");
	else printf("First\n");
	return 0;
}

