void bfs(int from, int c) {
    //cout << from << " " << c << endl;
    bool checker = true;
    for(int i = 0; i < pathes[from].size(); i++) {
        int to = pathes[from][i];
        if(color[to] != 2) checker = false;
    }
    //if(checker) cout << from << endl;
    win |= checker;
    if(c == 1) {
        int num = 0;
        for(int i = 0; i < pathes[from].size(); i++) {
            int to = pathes[from][i];
            if(color[to] == 0) num++;
        }
        if(num >= 2) return;
    }
    color[from] = c;
    for(int i = 0; i < pathes[from].size(); i++) {
        int to = pathes[from][i];
        if(color[to] == 0) bfs(to, 3 - c);
    }
}

