Graph<int> G;
bool success = true;

bool dfs(int pos, int par) {
    // マッチング途中ならtrue, そうでなければfalse
    if (pos != 0 && G[pos].size() == 1) {
        return true;
    }
    bool child = false;
    for (auto e : G[pos]) {
        if (e.to == par) continue;
        bool tmp = dfs(e.to, pos);
        if (child && tmp) {
            success = false;
            return false;
        }
        child = child || tmp;
    }
    return !child;
}

