int main()
{
    int N; cin >> N;

    auto neighbors = vector<set<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        neighbors[a].insert(b);
        neighbors[b].insert(a);
    }

    auto removed = set<int>();

    auto potential_leaves = set<int>();
    for (auto v = 0; v < N; v++) potential_leaves.insert(v);

    while (N >= 3)
    {
        auto seen = set<int>();
        for (const auto leaf : potential_leaves) if (neighbors[leaf].size() == 1)
        {
            const auto parent = *begin(neighbors[leaf]);
            if (seen.count(parent))
            {
                cout << "First" << endl;
                return 0;
            }
            else seen.insert(parent);

            removed.insert(leaf);
            removed.insert(parent);
            N -= 2;
        }

        potential_leaves.clear();
        for (const auto v : seen)
        {
            for (const auto w : neighbors[v]) if (!removed.count(w))
            {
                neighbors[w].erase(v);
                potential_leaves.insert(w);
            }
        }
    }

    cout << (N == 1 ? "First" : "Second") << endl;
}

