  for(int i=0; i<n; i++){
    if( G[i].size() == 1 ){
      leaf.insert( i );
    }
  }
  vector<int> col(n, -1);
  while(leaf.size()){
    int p = *leaf.begin();
    leaf.erase( *leaf.begin() );

    int nx_p = -1;
    for(int i=0; i<G[p].size(); i++){
      int nx = G[p][i];
      if( col[nx] == -1 ){
        col[nx] = 0;

        nx_p = nx;
        break;
      }
    }

    if(nx_p == -1){
      col[p] = 0;
      continue;
    }else{
      col[nx_p] = 0;
      col[p] = 1;
    }

    p = nx_p;
    vector<int> adj;
    for(int i=0; i<G[p].size(); i++){
      int nx = G[p][i];
      if( col[nx] == -1 ){
        adj.push_back(nx);
      }
    }

    if( adj.size() == 1 ){
      leaf.insert( adj.front() );
    }
