const int MAXN = 100000;
set<int> g[MAXN + 1];
int deg[MAXN + 1], del[MAXN + 1];

struct point {
    int v;
};

bool operator<(const point& first, const point& second) {
    if(deg[first.v] != deg[second.v])
        return deg[first.v] < deg[second.v];
    else if(deg[*g[first.v].begin()] != deg[*g[second.v].begin()])
        return deg[*g[first.v].begin()] < deg[*g[second.v].begin()];
    else
        return first.v < second.v;
}

int main() {
    //ios_base::sync_with_stdio(false);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n;
    cin >> n;
    if(n & 1) {
        cout << "First\n";
        return 0;
    }
    for(int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        g[a].insert(b);
        g[b].insert(a);
        deg[a]++;
        deg[b]++;
    }
    for(int i = 1; i <= n; i++) {
        int cnt = 0;
        for(auto x: g[i]) {
            if(deg[x] == 1)
                cnt++;
        }
        if(cnt >= 2) {
            cout << "First\n";
            return 0;
        }
    }
    set<point> s;
    for(int i = 1; i <= n; i++) {
        s.insert({ i });
    }
    while(!s.empty()) {
        auto it = s.begin();
        int v = it->v;
        if(deg[v] > 1)
            break;
        s.erase({ *g[v].begin() });
        for(auto u: g[*g[v].begin()]) {
            s.erase({ *g[v].begin() });
            deg[*g[v].begin()]--;
            if(deg[*g[v].begin()])
                s.insert({ *g[v].begin() });
            g[u].erase(*g[v].begin());
        }
    }
    for(auto it: s) {
        int i = it.v;
        if(deg[i] == 1) {
            cout << "First\n";
            return 0;
        }
    }
    cout << "Second\n";
    return 0;
}

