        *tp=(edge){v,fst[u]},fst[u]=tp++;
        *tp=(edge){u,fst[v]},fst[v]=tp++;
        ++cnt[u],++cnt[v];
    }
    repu(i,1,n)
        if (cnt[i]==1)
            stk[++top]=i;
    while (top)
    {
        int u=stk[top--],v=0;
        if (flag[u])
            continue;
        if (!cnt[u])
        {
            puts("First");
            return 0;
        }
        repe(i,u)
            if (cnt[i->v]>0)
                v=i->v;
        repe(i,v)
        {
            if (i->v!=u && cnt[i->v]==1)
            {
                puts("First");
                return 0;
            }
            if ((--cnt[i->v])==1)
                stk[++top]=i->v;
        }
        cnt[u]=cnt[v]=0,flag[u]=flag[v]=1;
    }
    puts("Second");
    return 0;
}

