int dfs(int u, int p, VVI& G) {
	int x = 0;
	int ch=0;
	for (int v: G[u]) if (v != p) {
		ch++;
		x += dfs(v, u, G);
	}
	if(ch==0) return 1; // need to match ... 葉
	if(x==0) return 1; // need to match ... 子が全部マッチしてるので
	if(x<=1) return 0; // matched
	return x;
}

