		g[x].clear();
		nn-=2;
	}
	for (int i=1;i<=n;i++){
		if (g[i].size()>=3){
			cout<<"First"<<endl;
			return 0;
		}
	}
	if (nn%2==1){
		cout<<"First"<<endl;
	}
	else{
		cout<<"Second"<<endl;
	}
}

