int main()
{
    int N; cin >> N;

    if (N % 2 == 1)
    {
        cout << "First" << endl;
        return 0;
    }

    auto neighbors = vector<set<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;

        neighbors[a].insert(b);
        neighbors[b].insert(a);
    }

    auto removed = set<int>();

    auto leaves = vector<int>();
    for (auto v = 0; v < N; v++) if (neighbors[v].size() == 1)
        leaves.push_back(v);

    while (N - int(removed.size()) >= 3)
    {
        auto parents = set<int>();
        for (const auto v : leaves)
        {
            const auto parent = *begin(neighbors[v]);
            if (parents.count(parent))
            {
                cout << "First" << endl;
                return 0;
            }
            parents.insert(parent);

            removed.insert(v);
            removed.insert(parent);
        }

        leaves.clear();

        for (const auto v : parents)
        {
            for (const auto w : neighbors[v]) if (!removed.count(w))
            {
                neighbors[w].erase(v);
                if (neighbors[w].size() == 1)
                    leaves.push_back(w);
            }
        }
    }

    cout << (N - int(removed.size()) == 1 ? "First" : "Second") << endl;
}

