		}
		ccc++;
		rangecan[ii]=dp(i,1,x);
		if(ii)rangecan[ii]+=rangecan[ii-1];
	}
	if(f==0){
		return mm[x][f]=(rangecan[SZ(adj[x])-1]==ccc);
	}
	else{
		REP(ii,SZ(adj[x])){
			int i=adj[x][ii];
			if(i==p)continue;
			int midv=dp(i,0,x);
			if(!midv)continue;
			int cv=1;
			if(ii)cv+=rangecan[ii-1];
			cv+=rangecan[SZ(adj[x])-1]-rangecan[ii];
			if(cv==ccc)return mm[x][f]=1;
		}
		return mm[x][f]=0;
	}
}

