			}
			else{
//				cout<<v1<<" "<<v[v1][i]<<" "<<2<<endl;
						dp3[v[v1][i]]+=dp2[v1]+dp4[v1];
			}
			if(dp2[v[v1][i]]>0){
//				cout<<v1<<" "<<v[v1][i]<<" "<<3<<endl;
				dp4[v[v1][i]]+=dp[v1]-1+dp3[v1];
			}
			else{
//				cout<<v1<<" "<<v[v1][i]<<" "<<4<<endl;
				dp4[v[v1][i]]+=dp[v1]+dp3[v1];
			}
			dfs2(v[v1][i]);
