int end_cnt(int v) {
    int ret = 0;
    REP(i,G[v].size()) {
        int nxt = G[v][i];
        if(G[nxt].size() == 1) {
            int rev_nxt = G[nxt][0];
            if(rev_nxt == v) ret++;
        }
    }
    return ret;
}

int nonend_deg(int v) {
    int ret = 0;
    REP(i,G[v].size()) {
        int nxt = G[v][i];
        ret = max(ret,(int)G[nxt].size() - 1);
    }
    return ret;
}

