		}
	}
	re[u]=cnt==0;
}
bool rre[1<<17];
bool ansflag;
pair<int,int>dfs3(int u,int p)
{
	int a=0,b=0,ecnt=0;
	for(int v:G[u])
	{
		if(v==p||re[v])continue;
		pair<int,int>q=dfs3(v,u);
		a+=q.first;
		b+=q.second;
		ecnt++;
	}
	if(rre[u])
	{
		a++;
	}
	if(a>=2)ansflag=true;
	if(b==ecnt)ansflag=true;
	else b=0;
	return make_pair(b>0,a>0);
}
