int main() {
	int N, a, b;
	cin >> N;
	vector<vector<int> > node(N);
	for (int i = 1;i < N;++ i) {
		cin >> a >> b;
		node[a - 1].push_back(b - 1);
		node[b - 1].push_back(a - 1);
	}
	queue<pair<int, int> > que; // 座標, 葉からの距離
	static int bfs[MAX];
	bool win = false;
	for (int i = 0;i < N;++ i) {
		bfs[i] = -1;
		if (node[i].size() <= 1) que.push(make_pair(i, 0)); // 葉
	}
	while(!que.empty()) {
		pair<int, int> tmp = que.front();
		que.pop();
		if (bfs[tmp.first] >= 0) {
			if (bfs[tmp.first] == tmp.second) win = tmp.second & 1; // 同距離
			continue;
		}
		bfs[tmp.first] = tmp.second;
		for (int i = 0;i < node[tmp.first].size();++ i) que.push(make_pair(node[tmp.first][i], tmp.second + 1));
	}
	cout << (win || N & 1 ? "First" : "Second");
	return 0;
}
