bool canpick(int pa,int u){

	if (deg[u]==1) return false;
	//cout<<u<<endl;
	for (int i=0;i<G[u].size();i++){
		if (G[u][i]==pa) continue;
		if (deg[G[u][i]]==1){
			return true;
		}
	}
	bool ans=true;
	for (int i=0;i<G[u].size();i++){
		if (G[u][i]==pa) continue;
		int v=G[u][i];
		for (int j=0;j<G[v].size();j++){
			if (G[v][j]==u) continue;
			if (!canpick(v,G[v][j])) ans=false;
		}
	}
	return ans;
}
