int solve(const vector<vector<int>> &G) {
    vector<int> A(G.size());
    for (int i = 0; i < G.size(); i++) {
        if (G[i].size() == 1) A[G[i][0]] += 1;
    }
    for (int i = 0; i < G.size(); i++) {
        if (A[i] >= 2) return 0;
        if (G[i].size() == 2 && A[G[i][0]] && A[G[i][1]]) return 0;
    }
    return 1;
}
