		a--;
		b--;
		int s = min(a, b);
		int l = max(a, b);
		es.push_back(Edge(s, l));
	}
	Graph g(n, es, true);

	string ans = main.firstWins(g) ? "First" : "Second";
	cout << ans << endl;

	return 0;
}

