void prep(int v, int p){
	for(int u : adj2[v]){
		if(u != p){
			prep(u, v);
			adj[v].push_back(u);
		}
	}
}

void dfs(int v){
	if(adj[v].size() == 0){
		dp[1][v] = true;
		dp[0][v] = false;
		return;
	}

    for(int i = 0; i < adj[v].size(); i++){
		int u = adj[v][i];

		dfs(u);

		if(i == 0){
			pre[i] = dp[0][u];
		}else{
			pre[i] = dp[0][u] & pre[i - 1];
		}
    }

    suf[adj[v].size()] = 1;
    for(int i = adj[v].size() - 1; i >= 0; i--){
		int u = adj[v][i];

		if(i == adj[v].size() - 1){
			suf[i] = dp[0][u];
		}else{
			suf[i] = dp[0][u] & suf[i + 1];
		}
    }

    dp[1][v] = suf[0];
    dp[0][v] = dp[1][adj[v][0]] & suf[1];

    for(int i = 1; i < adj[v].size(); i++){
		dp[0][v] |= (pre[i - 1] & dp[1][adj[v][i]] & suf[i + 1]);
    }
}

