		G::link(u, v);
		++deg[u], ++deg[v];
	}
	if( n == 2 ) return puts("Second"), 0;
	for( int i = 1; i <= n; ++i )
		if( deg[i] != 1 ) {
			rt = i;
			break;
		}
	dfs(rt, 0, 1);
	for( int i = 1; i <= n; ++i )
		if( deg[i] == 1 )
			leaf.push(i);
	while( !leaf.empty() ) {
		int u = leaf.top();
		leaf.pop();
		if( check( pa[u] ) ) return puts("First"), 0;
	}
	return puts("Second"), 0;
}

