class solver{
    istream& is;
    ostream& os;
    E_Set E;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    bool dfs(int v, int p = -1){
        int c = 0;
        for (auto &&u : E[v]) {
            if(u == p) continue;
            c += dfs(u, v);
        } // end
        if(c >= 2) throw 1;

        return c != 1;
    }

    bool solve(){
        try{
            dfs(1);
            return false;
        }
        catch(int k){
            return true;
        }
    }

    void run(){
        ll N;
        is >> N;
        if(!is) return;
        for (int i = 0; i < N - 1; ++i) {
            int A, B; is >> A >> B;
            E[A].insert(B);
            E[B].insert(A);
        } // end i
        cout << (solve() ? "First" : "Second") << endl;

    }
};

