int dfs(int n, int b){
	//cout << "dfs: " << n << " " << b << endl;
	if( d[n] ){
		start = n;
		return -1;
	}
	d[n] = true;
	if( edge[n].size() == 1 ) return 1;
	vector<int> v;
	for(auto t: edge[n]) if(t != b){
		v.push_back( dfs(t, n) );
	}
	int odd = 0;
	int even = 0;
	for(auto t: v){
		if( t > 0 && (t % 2) ) odd++;
		if( t > 0 && (t % 2 == 0) ) even++;
		//cout << t << " ";
	}
	//cout << endl;
	//cout << n << "," << b << "  ret: " << ret << endl;
	if( odd > 1 ){
		ans = true;
		//cout << "true " << ret << endl;
	}
	if( v.size() == even && even >= 2 ) return 1;
	return ( v.size()==1 ? v[0]+1 : -1 );
}

int find(int n, int b){
	if( edge[n].size() > 2 ) return n;
	for(auto t: edge[n]) if( t != b ){
		return find(t, n);
	}
	return b;
}

