vector<int> C;//無色
const int FIRST = 1;
const int SECOND = 2;
vector< vector<int> > Gra;
vector< bool > visit;

bool dfs(int v){
	if( C[v] != 0 ){
		return false;
	}
	visit[v] = true;
	int size = Gra[v].size();
	int count = 0;
	for(int i=0;i<size;++i){
		int to = Gra[v][i];
		if( Gra[to].size() == 1 ){//なんか
			if( C[v] == 0 ){
				C[v] = FIRST;
				C[to] = SECOND;
			}else{
				return true;//勝ちの塗り方
			}
		}else{
			if( visit[to] == false ){
				bool res = dfs(to);
			}
		}
		if( C[to] == FIRST ){
			++count;
		}
	}
	if( count == Gra[v].size() ){
		return true;
	}else if(count+1 == Gra[v].size() ){
		for(int i=0;i<(int)Gra[v].size();++i){
			int to = Gra[v][i];
			if( C[to] == 0 ){
				bool res = dfs(to);
				return res;
			}
		}
	}
	visit[v] = false;
}

int dfs2(int v){
	int size = Gra[v].size();
	int count = 0;
	int pos = -1;
	for(int i=0;i<size;++i){
		int to = Gra[v][i];
		if( Gra[to].size() == 1 ){
			C[v] = FIRST;
			C[to] = SECOND;
			return 1;//続行
		}
		if( C[to] == FIRST ){
			count++;
		}else{
			pos = i;
		}
	}
	if( count == size ){
		return 100;//勝ち
	}
	if( size-1 == count ){
		//pos
		if( C[ Gra[v][pos] ] != SECOND ){
			C[ Gra[v][pos] ] = FIRST;
			C[v] = SECOND;
			return 1;//続行
		}
	}
	return 0;
}
void solve(){
	int N;
	cin >> N;

	Gra = vector< vector<int> >(N);
	visit = vector< bool > (N,false);
	C = vector<int> (N,0);
	for(int i=0;i<N-1;++i){
		int a,b;
		cin >> a >> b;
		--a;--b;
		Gra[a].push_back(b);
		Gra[b].push_back(a);
	}
	vector<int> AA(N,0);
	for(int i=0;i<N;++i){
		/*if( Gra[i].size() == 0 ){//条件：木
			cout << "First" << endl;
			return;
		}*/
		if( Gra[i].size() == 1 ){
			AA[ Gra[i][0] ]++;
		}
	}
	for(int i=0;i<N;++i){
		if( AA[i] >= 2 ){
			cout << "First" << endl;
			return;
		}
	}

	for(int i=0;i<N;++i){
		if( Gra[i].size() == 1 ){
			C[i] = 2;
			C[ Gra[i][0] ] = 1;
		}
	}

	{//更新
		for(int i=0;i<N;++i){
			if( C[i] != 0 ) continue;
			int size = Gra[i].size();
			bool flag = true;
			for(int j=0;j<size;++j){
				int to = Gra[i][j];
				if( C[to] == 0 || C[to] == 2 ){
					flag = false;
					break;
				}
			}
			if( flag ){
				cout << "First" << endl;
				return;
			}
		}
	}
	bool res = false;
	int pos = 0;
	int count = 0;
	int COL = 0;
	for(int i=0;i<N;++i){
		if( C[i] != 0 ){
			++COL;
		}
	}

	while(true){
		pos = (pos+1)%N;
		if( C[pos] != 0 ) continue;
		int aaa = dfs2(pos);
		if( aaa >= 100 ){
			res = true;break;
		}else if(aaa != 0 ){//1
			//1で2個ぬってるはず
			count = 0;
			COL += 2;
		}else if( aaa == 0 ){
			++count;
		}
		if( N-COL <= count ){
			break;
		}
	}
	if( res ){
		cout << "First" << endl;
	}else{
		cout << "Second" << endl;
	}
}

