	int v;
} list;

int main()
{
	int i, N, u, w, deg[200001] = {};
	list *adj[200001] = {}, e[400001];
	scanf("%d", &N);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj[w];
		adj[u] = &(e[i*2]);
		adj[w] = &(e[i*2+1]);
		deg[u]++;
		deg[w]++;
	}

	int par[200001] = {}, q[200001], head, tail;
	list *p;
	par[1] = 1;
	q[0] = 1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (p = adj[u]; p != NULL; p = p->next) {
			if (par[p->v] == 0) {
				par[p->v] = u;
				q[tail++] = p->v;
			}
		}
	}
	for (head--; head >= 0; head--) {
		u = q[head];
		if (par[u] == -1) continue;
		else if (deg[par[u]] >= 3) break;
		else if (par[u] == 1 && deg[par[u]] >= 2) break;
		else if (u == 1) break;
		deg[par[par[u]]]--;
		par[par[u]] = -1;
	}
	if (head >= 0) printf("First\n");
	else printf("Second\n");
	fflush(stdout);
	return 0;
}

