public class Main {
	static ContestScanner in;
	static Writer out;
	public static void main(String[] args) {
		try {
			in = new ContestScanner();
			out = new Writer();
			new Main().solve();
			in.close();
			out.close();
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	void solve() throws IOException {
		int n = in.nextInt();
		tree = new List[n];
		for(int i = 0; i < n; i++) tree[i] = new ArrayList<>();
		for(int i = 0; i < n - 1; i++) {
			int a = in.nextInt() - 1;
			int b = in.nextInt() - 1;
			tree[a].add(b);
			tree[b].add(a);
		}
		int root = -1;
		for(int i = 0; i < n; i++) {
			if(tree[i].size() == 1) {
				root = i;
				break;
			}
		}
		System.out.println(dfs(root, -1) > 0 ? "First" : "Second");

	}

	List<Integer>[] tree;
	int dfs(int cur, int par) {
		int cnt = 0;
		for(int v: tree[cur]) {
			if(v == par) continue;
			cnt += dfs(v, cur);
		}
		return cnt > 1 ? cnt : (cnt ^ 1);
	}
}


