	ArrayDeque<Integer> leaf;
	boolean[] used;

	public boolean check(){
		for(int i = 0;i < N;i++){
			int count = 0;
			for(int next : graph.get(i)){
				if(graph.get(next).size() == 1){
					count++;
				}
			}

			if(count >= 2){
				return true;
			}
		}

		return false;
	}

	public boolean rec(){

		if(leaf.size() <= 1){
			return leaf.size() != 0;
		}

		ArrayDeque<Integer> tmp = new ArrayDeque<Integer>();

		while(leaf.size() > 0){

			int v = leaf.poll();
			if(!graph.containsKey(v))continue;
			if(graph.get(v).size() != 1)continue;

			int u = graph.get(v).get(0);

			for(int next : graph.get(v)){
				graph.get(next).remove(new Integer(v));
			}
			for(int next : graph.get(u)){
				graph.get(next).remove(new Integer(u));
			}

			for(int next :graph.get(u)){
				if(graph.get(next).size() == 1){
					tmp.add(next);
				}
			}
			graph.remove(v);
			graph.remove(u);
		}
		leaf = tmp;
		return rec();

	}

	public void solve(){
		N = nextInt();
		graph = new HashMap<Integer,ArrayList<Integer>>();
		for(int i = 0;i < N;i++){
			graph.put(i,new ArrayList<Integer>());
		}

		for(int i = 0;i < N-1;i++){
			int a = nextInt()-1;
			int b = nextInt()-1;

			graph.get(a).add(b);
			graph.get(b).add(a);
		}
		used = new boolean[N];
		leaf = new ArrayDeque<Integer>();
		for(int i = 0;i < N;i++){
			if(graph.get(i).size() == 1){
				leaf.add(i);
			}
		}

		if(check()){
			out.println("First");
			return;
		}

		if(rec())out.println("First");
		else out.println("Second");


	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
