        while (queue.size() > 0) {
            int from = queue.poll();
            for (int to : graph[from]) {
                if (used[to]) continue;

                distances[to] = distances[from] + 1;
                parents[to] = from;
                used[to] = true;
                queue.add(to);
            }
        }

        return new int[][] { distances, parents };
