                hasChild = true;
                int a = dfs(to, now);
                if (a == -1) {
                    ok = 1;
                } else if (a == 1) {
                    black++;
                }
            }
        }
        if (!hasChild) {
            return 1;
        }
        if (ok == 1 || black >= 2) {
            return -1;
        } else if (black == 1) {
            return 0;
        } else {
            return par == -1 ? -1 : 1;
        }
    }

    static int[][] graph;

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }

