            int parent = parents[leaf];
            colors[leaf] = BLACK;

            if (parent != -1 && colors[parent] == 0) {
                colors[parent] = WHITE;

                for (int to : graph[parent]) {
                    --neighbourCounts[to];
                    if (neighbourCounts[to] == 1) {
                        queue.add(to);
