  private boolean first(ArrayList<Integer>[] tree) {
    int N = tree.length;
    for (int v = 0; v < N; v++) {
      if (tree[v].size() != 1) {
        continue;
      }

      int parent = tree[v].get(0);
      for (int u : tree[parent]) {
        if (u != v && tree[u].size() == 1) {
          return true;
        }
      }
    }
    return false;
  }

  private void solve(FastScanner in, PrintWriter out) {
    int N = in.nextInt();
    ArrayList<Integer>[] tree = new ArrayList[N];
    for (int i = 0; i < N; i++) {
      tree[i] = new ArrayList<>();
    }

    for (int i = 0; i < N - 1; i++) {
      int a = in.nextInt() - 1;
      int b = in.nextInt() - 1;
      tree[a].add(b);
      tree[b].add(a);
    }

    if (first(tree)) {
      out.println("First");
    } else {
      out.println("Second");
    }
  }

