public class Main {

  private static void solve() {
    int n = ni();
    int[] from = new int[n - 1];
    int[] to = new int[n - 1];
    for (int i = 0; i < n - 1; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int ret = dfs(0, -1, g);
    System.out.println(ret < 0 ? "First" : "Second");
  }


  private static int dfs(int n, int pre, int[][] g) {
    if (pre >= 0 && g[n].length == 1) {
      return 1;
    }

    int sum = 0;
    for (int v : g[n]) {
      if (v == pre)
        continue;

      int x = dfs(v, n, g);
      if (x < 0) {
        return x;
      } else {
        sum += x;
      }
    }

    if (pre >= 0) {
      if (sum == 1) {
        return 0;
      } else if (sum >= 2) {
        return -1;
      } else {
        return 1;
      }
    } else {
      if (sum == 1) {
        return 0;
      } else {
        return -1;
      }
    }
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

