import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.NoSuchElementException;

public class Main {

	int N;
	ArrayList<Integer>[] graph;
	boolean[] used;

	@SuppressWarnings("unchecked")
	public void solve(){
		N = nextInt();
		graph = new ArrayList[N];
		for(int i = 0;i < N;i++){
			graph[i] = new ArrayList<Integer>();
		}

		for(int i = 0;i < N-1;i++){
			int a = nextInt()-1;
			int b = nextInt()-1;

			graph[a].add(b);
			graph[b].add(a);
		}

		for(int i = 0;i < N;i++){
			int count = 0;
			for(int next : graph[i]){
				if(graph[next].size() == 1){
					count++;
				}
			}

			if(count >= 2){
				out.println("First");
				return;
			}
		}
		used = new boolean[N];
		ArrayDeque<Integer> q = new ArrayDeque<Integer>();
		for(int i = 0;i < N;i++){
			if(graph[i].size() == 1){
				q.add(i);
			}
		}

		while(q.size() > 0){

			int v = q.poll();
			int next = -1;
			for(int u : graph[v]){
				if(used[u])continue;
				next = u;
				break;
			}

			if(next == -1)continue;
			used[next] = true;
			used[v] = true;

			for(int u : graph[next]){
				if(used[u])continue;
				q.add(u);
			}
		}


		for(int i = 0;i < N;i++){
			if(!used[i]){
				out.println("First");
				return;
			}
		}
		out.println("Second");


	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.NoSuchElementException;


public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    int[] from = new int[N - 1];
    int[] to = new int[N - 1];
    for (int i = 0; i < N - 1; i++) {
      from[i] = sc.nextInt() - 1;
      to[i] = sc.nextInt() - 1;
    }


    boolean[] live = new boolean[N];
    Arrays.fill(live, true);

    int[][] tree = packU(N, from, to);

    int ret = dfs(0, -1, tree);
    if (ret < 0 || ret == 1) {
      System.out.println("First");
    } else {
      System.out.println("Second");
    }
  }

  private static int dfs(int now, int pre, int[][] tree) {

    int ret = 0;
    for (int next : tree[now]) {
      if (next != pre) {
        int v = dfs(next, now, tree);
        if (v < 0) {
          return v;
        }
        ret += v;
      }
    }

    if (ret >= 2) {
      return -1;
    } else {
      return (ret + 1) % 2;
    }
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }
}


class FastScanner {
  public static String debug = null;

  private final InputStream in = System.in;
  private int ptr = 0;
  private int buflen = 0;
  private byte[] buffer = new byte[1024];
  private boolean eos = false;

  private boolean hasNextByte() {
    if (ptr < buflen) {
      return true;
    } else {
      ptr = 0;
      try {
        if (debug != null) {
          buflen = debug.length();
          buffer = debug.getBytes();
          debug = "";
          eos = true;
        } else {
          buflen = in.read(buffer);
        }
      } catch (IOException e) {
        e.printStackTrace();
      }
      if (buflen < 0) {
        eos = true;
        return false;
      } else if (buflen == 0) {
        return false;
      }
    }
    return true;
  }

  private int readByte() {
    if (hasNextByte())
      return buffer[ptr++];
    else
      return -1;
  }

  private static boolean isPrintableChar(int c) {
    return 33 <= c && c <= 126;
  }

  private void skipUnprintable() {
    while (hasNextByte() && !isPrintableChar(buffer[ptr]))
      ptr++;
  }

  public boolean isEOS() {
    return this.eos;
  }

  public boolean hasNext() {
    skipUnprintable();
    return hasNextByte();
  }

  public String next() {
    if (!hasNext())
      throw new NoSuchElementException();
    StringBuilder sb = new StringBuilder();
    int b = readByte();
    while (isPrintableChar(b)) {
      sb.appendCodePoint(b);
      b = readByte();
    }
    return sb.toString();
  }

  public long nextLong() {
    if (!hasNext())
      throw new NoSuchElementException();
    long n = 0;
    boolean minus = false;
    int b = readByte();
    if (b == '-') {
      minus = true;
      b = readByte();
    }
    if (b < '0' || '9' < b) {
      throw new NumberFormatException();
    }
    while (true) {
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
      b = readByte();
    }
  }

  public int nextInt() {
    return (int) nextLong();
  }

  public long[] nextLongList(int n) {
    return nextLongTable(1, n)[0];
  }

  public int[] nextIntList(int n) {
    return nextIntTable(1, n)[0];
  }

  public long[][] nextLongTable(int n, int m) {
    long[][] ret = new long[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextLong();
      }
    }
    return ret;
  }

  public int[][] nextIntTable(int n, int m) {
    int[][] ret = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ret[i][j] = nextInt();
      }
    }
    return ret;
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.HashSet;
import java.util.NoSuchElementException;
import java.util.Set;


public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    int[] from = new int[N - 1];
    int[] to = new int[N - 1];
    int[] count = new int[N];
    for (int i = 0; i < N - 1; i ++) {
      from[i] = sc.nextInt() - 1;
      to[i] = sc.nextInt() - 1;

      count[from[i]] ++;
      count[to[i]] ++;
    }


    boolean[] live = new boolean[N];
    Arrays.fill(live, true);

    int[][] tree = packU(N, from, to);

    while (true) {
      boolean flg = false;

      Set<Integer> leaf = new HashSet<>();
      for (int i = 0; i < N; i ++) {
        if (count[i] == 1) {
          leaf.add(i);
        }
      }

      int[] leafCount = new int[N];

      for (int i = 0; i < N; i ++) {
        for (int next : tree[i]) {
          if (live[next] && leaf.contains(next)) {
            leafCount[i] ++;
          }
        }

        if (count[i] == 1) {
          live[i] = false;
          flg = true;
        }
      }

      for (int i = 0; i < N; i ++) {
        if (leafCount[i] >= 2) {
          System.out.println("First");
          return;
        } else if (leafCount[i] == 1) {
          live[i] = false;
          flg = true;
        }
      }

      for (int i = 0; i < N; i ++) {
        for (int next : tree[i]) {
          count[next] --;
        }
      }

      if (flg) {
        break;
      }
    }
    System.out.println("Second");

  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
        p[f]++;
    for (int t : to)
        p[t]++;
    for (int i = 0; i < n; i++)
        g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
        g[from[i]][--p[from[i]]] = to[i];
        g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
}
}


