import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final int[][] abs;

  List<List<Integer>> graph;
  boolean[] used;

  Solver(int n, int[][] abs) {
    this.n = n;
    this.abs = abs;
  }

  private boolean isPerfectGraphDfs(int index, int parentIndex) {
    for (int childIndex : graph.get(index)) {
      if (childIndex == parentIndex) {
        continue;
      }
      if (!isPerfectGraphDfs(childIndex, index)) {
        return false;
      }
    }
    if (!used[index]) {
      if (parentIndex < 0 || used[parentIndex]) {
        return false;
      }
      used[index] = true;
      used[parentIndex] = true;
    }
    return true;
  }

  public boolean solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }

    used = new boolean[n + 1];
    return isPerfectGraphDfs(1, -1);
  }
}

public class Main {
  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int[][] abs = reader.nextInt(n - 1, 2);
    out.println(new Solver(n, abs).solve() ? "Second" : "First");
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

