    static class agc014d {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            Set[] g = new Set[n];

            for (int i = 0; i < n; i++) {
                g[i] = new TreeSet();
            }

            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt();
                int b = in.nextInt();

                a--;
                b--;

                g[a].add(b);
                g[b].add(a);
            }

            TreeSet<Integer> leaves = new TreeSet<>();

            for (int i = 0; i < n; i++) {
                int l = 0;
                for (int v : (Set<Integer>) g[i]) {
                    if (g[v].size() == 1) {
                        l++;
                        leaves.add(v);
                    }
                }

                if (l > 1) {
                    out.println("First");
                    return;
                }
            }

//        if (n % 2 == 1) {
//            out.println("First");
//        } else {
//            out.println("Second");
//        }

            Map<Integer, Integer> mp = new HashMap<>();

            int rn = n;

            while (rn > 1) {
                Map<Integer, Integer> nmp = new HashMap<>();

                TreeSet<Integer> nleaves = new TreeSet<>();

                for (int l : leaves) {
                    if (g[l].size() == 1) {
                        int v = ((TreeSet<Integer>) g[l]).first();
                        g[v].remove(l);
                        rn--;
                        nmp.merge(v, 1, (x, y) -> x + y);
                        nleaves.add(v);
                        if (mp.getOrDefault(l, 0) > 1) {
                            out.println("First");
                            return;
                        }
                    }
                }

                leaves = nleaves;
                mp = nmp;
            }

            out.println("Second");
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
