/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            TaskD.Vertex[] vs = new TaskD.Vertex[n];
            for (int i = 0; i < n; ++i) {
                vs[i] = new TaskD.Vertex();
            }
            for (int i = 0; i < n - 1; ++i) {
                TaskD.Vertex a = vs[in.nextInt() - 1];
                TaskD.Vertex b = vs[in.nextInt() - 1];
                a.adj.add(b);
                b.adj.add(a);
            }
            List<TaskD.Vertex> degOne = new ArrayList<>();
            for (TaskD.Vertex v : vs)
                if (v.adj.size() == 1) {
                    degOne.add(v);
                }
            while (!degOne.isEmpty()) {
                Set<TaskD.Vertex> toKill = new HashSet<>();
                for (TaskD.Vertex v : degOne) {
                    toKill.add(v);
                    TaskD.Vertex u = v.adj.iterator().next();
                    if (u.adj.size() > 1) {
                        toKill.add(u);
                        ++u.numOnes;
                        if (u.numOnes > 1) {
                            out.println("First");
                            return;
                        }
                    }
                }
                for (TaskD.Vertex v : toKill) {
                    v.numOnes = 1;
                }
                degOne.clear();
                for (TaskD.Vertex v : toKill) {
                    for (TaskD.Vertex u : v.adj) {
                        if (u.numOnes == 0) {
                            u.adj.remove(v);
                            if (u.adj.size() == 1) degOne.add(u);
                        }
                    }
                }
            }
            out.println("Second");
        }

        static class Vertex {
            int numOnes;
            Set<TaskD.Vertex> adj = new HashSet<>();

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        int[] deg = new int[n];
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
            deg[u]++; deg[v]++;
        }
        boolean[] removed = new boolean[n];
        int[] leaves = new int[n];
        IntDeque q = new IntDeque();
        for (int i = 0; i < n; i++) {
            if (deg[i] == 1) {
                g[i].iterator().forEachRemaining((int j) -> {
                    leaves[j]++;
                });
                q.addLast(i);
            }
        }
        for (int i = 0; i < n; i++) {
            if (leaves[i] > 1) {
                out.writeln("First");
                return;
            }
        }
        while (q.size() > 0) {
            int u = q.removeFirst();
            removed[u] = true;
            var it = g[u].iterator();
            while (it.hasNext()) {
                int v = it.nextInt();
                if (removed[v]) continue;
                if (--deg[v] <= 1) {
                    removed[v] = true;
                    var it2 = g[v].iterator();
                    while (it2.hasNext()) {
                        int x = it2.nextInt();
                        if (removed[x]) continue;
                        if (--deg[x] <= 1) {
                            q.addLast(x);
                        }
                        leaves[x]++;
                        if (leaves[v] > 1) {
                            out.writeln("First");
                            return;
                        }
                    }
                }
            }
        }
        out.writeln("Second");
    }
}


