    }

    static class TaskD {
        Graph graph;
        boolean[] used;
        boolean can = false;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();

            graph = new Graph(n);
            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                graph.addDirectedEdge(a, b);
            }

            used = new boolean[n];
            if (rec(0) == 1) {
                can = true;
            }

            out.println(can ? "First" : "Second");
        }

        int rec(int x) {
            used[x] = true;
            ArrayList<Integer> list = graph.get(x);
            int sum = 0;
            for (int to : list) {
                if (!used[to]) {
                    sum += rec(to);
                }
            }

            if (sum >= 2) {
                can = true;
            }

            return 1 - sum;
        }

    }

