    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = new int[n - 1];
            int[] b = new int[n - 1];
            IOUtils.readIntArrays(in, a, b);
            MiscUtils.decreaseByOne(a, b);
            int[] degree = new int[n];
            for (int i : a) {
                degree[i]++;
            }
            for (int i : b) {
                degree[i]++;
            }
            int[] queue = new int[n];
            int size = 0;
            Graph graph = BidirectionalGraph.createGraph(n, a, b);
            for (int i = 0; i < n; i++) {
                if (degree[i] == 1) {
                    queue[size++] = i;
                }
            }
            for (int i = 0; i < size; i++) {
                int current = queue[i];
                if (degree[current] == 0) {
                    continue;
                }
                degree[current] = 0;
                for (int j = graph.firstOutbound(current); j != -1; j = graph.nextOutbound(j)) {
                    int next = graph.destination(j);
                    if (degree[next] != 0) {
                        degree[next] = 0;
                        for (int k = graph.firstOutbound(next); k != -1; k = graph.nextOutbound(k)) {
                            int other = graph.destination(k);
                            if (degree[other] > 0) {
                                if (degree[other] == 1) {
                                    out.printLine("First");
                                    return;
                                }
                                degree[other]--;
                                if (degree[other] == 1) {
                                    queue[size++] = other;
                                }
                            }
                        }
                    }
                }
            }
            out.printLine("Second");
        }

    }

