	static void solve()
	{
		int n = ni();
		int[] from = new int[n - 1];
		int[] to = new int[n - 1];
		for (int i = 0; i < n - 1; i++) {
			from[i] = ni() - 1;
			to[i] = ni() - 1;
		}
		if(n == 2){
			out.println("Second");
			return;
		}
		int[][] g = packU(n, from, to);
		int[] deg = new int[n];
		for(int i = 0;i < n;i++){
			deg[i] = g[i].length;
		}
		int[] score = new int[n];
		int[] es = new int[n];
		int[] ls = new int[n];
		int lp = 0;
		for(int i = 0;i < n;i++){
			if(deg[i] == 1){
				ls[lp++] = i;
			}
		}
		while(lp > 0){
			int ep = 0;
			for(int i = 0;i < lp;i++){
				int leaf = ls[i];
				deg[leaf] = 0;
				for(int e : g[leaf]){
					if(deg[e] > 0){
						if(++score[e] == 2){
							out.println("First");
							return;
						}else{
							es[ep++] = e;
						}
					}
				}
			}
			lp = 0;
			for(int i = 0;i < ep;i++){
				int e = es[i];
				if(deg[e] > 0){
					deg[e] = 0;
					for(int u : g[e]){
						if(deg[u] > 0){
							if(--deg[u] == 1){
								ls[lp++] = u;
							}
							if(deg[u] == 0){
								out.println("First");
								return;
							}
						}
					}
				}
			}
		}
		out.println("Second");
	}

	public static int[][] parents3(int[][] g, int root) {
		int n = g.length;
		int[] par = new int[n];
		Arrays.fill(par, -1);

		int[] depth = new int[n];
		depth[0] = 0;

		int[] q = new int[n];
		q[0] = root;
		for (int p = 0, r = 1; p < r; p++) {
			int cur = q[p];
			for (int nex : g[cur]) {
				if (par[cur] != nex) {
					q[r++] = nex;
					par[nex] = cur;
					depth[nex] = depth[cur] + 1;
				}
			}
		}
		return new int[][] { par, q, depth };
	}

	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}


