    private class TreeNode
    {
        public int ID;
        public int Depth = -1;
        public TreeNode Parent;
        public List<TreeNode> Items = new List<TreeNode>();
        public void SetDepth() {
            if(this.Depth >= 0) {
                return;
            }
            if(this.Parent == null) {
                this.Depth = 0;
            } else {
                this.Parent.SetDepth();
                this.Depth = this.Parent.Depth + 1;
            }
        }
        public TreeNode(int id)
        {
            this.ID = id;
        }

        public void UpsideDown()
        {
            if (this.Parent.Parent != null)
            {
                this.Parent.Items.Remove(this);
                this.Parent.UpsideDown();
                this.AddItem(this.Parent);
                this.Parent = null;
            }

        }
        public void AddItem(TreeNode t)
        {
            this.Items.Add(t);
            t.Parent = this;
        }
    }

