public class Program
{
    private int N;
    private List<int>[] E;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }


        var q = new Queue<int>();
        int[] f = new int[N];
        f[0] = 1;
        q.Enqueue(0);
        while (q.Count > 0)
        {
            var d = q.Dequeue();
            foreach (int i in E[d])
            {
                if (f[i] != 0) continue;
                f[i] = -f[d];
                q.Enqueue(i);
            }
        }

        if (N % 2 == 0 && N / 2 == f.Count(i => i == 1))
        {
            Console.WriteLine("Second");
        }
        else
        {
            Console.WriteLine("First");
        }
    }

    public static void Main(string[] args) => new Program().Solve();
}

