class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var f = new MaxFlow(N+2);
        if (N % 2 == 1) Fail("First");
        var col = new int[N];
        for(int i = 0; i < N-1; i++)
        {
            int a, b;
            sc.Make(out a, out b);a--;b--;
            if (col[a] == 0 && col[b] == 0)
            {
                col[a] = 1; col[b] = 2;
            }
            else if (col[a] != 0) { col[b] = col[a] ^ 3; }
            else col[a] = col[b] ^ 3;
            if (col[a] == 2) swap(ref a, ref b);
            f.AddDirectedEdge(a, b, 1);
        }
        for (int i = 0; i < N; i++)
            if (col[i] == 1)
                f.AddDirectedEdge(N, i, 1);
            else f.AddDirectedEdge(i, N + 1, 1);
        WriteLine(f.Execute(N, N + 1) == N / 2 ? "Second" : "First");
    }
}

public class MaxFlow
{
    readonly List<Edge>[] G;
    readonly int[] lv, iter;

    public MaxFlow(int V)
    {
        G = new List<Edge>[V];
        lv = new int[V];
        iter = new int[V];
        for (int i = 0; i < G.Length; i++)
            G[i] = new List<Edge>();
    }

    public void AddDirectedEdge(int from, int to, int cap)
        => addEdge(from, to, cap, 0);

    public void AddUndirectedEdge(int from, int to, int cap)
        => addEdge(from, to, cap, cap);

    void addEdge(int f, int t, int c1, int c2)
    {
        var a = new Edge(t, c1);
        var b = new Edge(f, c2);
        Edge.Link(a, b);
        G[f].Add(a);
        G[t].Add(b);
    }

    public int Execute(int src, int sink, int f = -1)
    {
        int flow = 0;
        if (f < 0) f = int.MaxValue;
        while (f > 0)
        {
            bfs(src);
            if (lv[sink] == 0) return flow;
            Array.Clear(iter, 0, iter.Length);
            int df;
            while ((df = dfs(src, sink, f)) > 0) { flow += df; f -= df; }
        }
        return flow;
    }

    void bfs(int s)
    {
        Array.Clear(lv, 0, lv.Length);
        var q = new Queue<int>();
        lv[s] = 1;
        q.Enqueue(s);
        while (q.Count > 0)
        {
            var v = q.Dequeue();
            foreach (var e in G[v])
                if (e.Cap > 0 && lv[e.To] == 0)
                {
                    lv[e.To] = lv[v] + 1;
                    q.Enqueue(e.To);
                }
        }

    }
    int dfs(int v, int t, int f)
    {
        if (v == t) return f;
        int ret = 0;
        for (; iter[v] < G[v].Count; iter[v]++)
        {
            var e = G[v][iter[v]];
            if (e.Cap <= 0 || lv[v] >= lv[e.To]) continue;
            int df = dfs(e.To, t, Math.Min(f, e.Cap));
            if (df <= 0) continue;
            e.Cap -= df;
            e.Rev.Cap += df;
            ret += df; f -= df;
            if (f == 0) break;
        }
        return ret;

    }
    class Edge
    {
        public static void Link(Edge e1, Edge e2)
        {
            e1.Rev = e2; e2.Rev = e1;
        }
        public int To { get; private set; }
        public Edge Rev { get; private set; }
        public int Cap { get; set; }
        public Edge(int t, int c)
        {
            To = t;
            Cap = c;
        }
        public override string ToString()
        {
            return string.Format("to: {0}, cap: {1}", To, Cap);
        }
    }
}
