using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N;
    private List<int>[] Edges;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        Edges = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            Edges[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            Edges[a].Add(b);
            Edges[b].Add(a);
        }

        var q = new Queue<int>();
        var f = new bool[N];
        var w = new bool[N];
        for (int i = 0; i < N; i++)
        {
            if (Edges[i].Count == 1)
            {
                q.Enqueue(i);
                f[i] = true;
                w[i] = true;
            }
        }

        while (q.Count > 0)
        {
            var d = q.Dequeue();
            var flag = !w[d];
            // Console.WriteLine($"{d} {flag}");
            foreach (int to in Edges[d])
            {
                if (f[to]) continue;
                q.Enqueue(to);
                f[to] = true;
                w[to] = flag;
                if (!flag)
                {
                    flag = true;
                }
            }

            if (!flag)
            {
                // Console.WriteLine(d);
                Console.WriteLine("First");
                return;
            }
        }

        Console.WriteLine("Second");
    }

    public static void Main(string[] args) => new Program().Solve();
}

