class Solve{
    List<int>[] G;
    bool b;
    bool[] us;
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        G = new List<int>[N];
        for(int i=0;i<N;i++){
            G[i] = new List<int>();
        }
        for(int i=0;i<N-1;i++){
            string[] str = Console.ReadLine().Split(' ');
            int a = int.Parse(str[0]) - 1;
            int b = int.Parse(str[1]) - 1;
            G[a].Add(b);
            G[b].Add(a);
        }
        us = new bool[N];
        dfs(0,false);
        sb.Append((b ? "First" : "Second")+"\n");
    }
    bool dfs(int v,bool c){
        us[v] = true;
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if(!us[t]){
                if(dfs(t,G[v].Count == 1)){
                    if(c){
                        b = true;
                        return true;
                    }
                    else{
                        c = true;
                    }
                }
            }
        }
        return G[v].Count == 1;
    }
}

