	internal class Template
	{
		private HashSet<int>[] adj = new HashSet<int>[100010];
		private HashSet<int>[] orig = new HashSet<int>[100010];
		private int[] color;

		private void Solve()
		{
			var n = cin.NextInt();
			color = new int[n + 1];
			for (var i = 1; i <= n; i++)
			{
				adj[i] = new HashSet<int>();
			}
			for (var i = 0; i < n - 1; i++)
			{
				var a = cin.NextInt();
				var b = cin.NextInt();
				adj[a].Add(b);
				adj[b].Add(a);
			}
			for (var i = 1; i <= n; i++)
			{
				orig[i] = new HashSet<int>(adj[i]);
			}
			var leaves = new List<int>();
			for (var i = 1; i <= n; i++)
			{
				if (adj[i].Count == 1)
				{
					leaves.Add(i);
				}
			}
			for (var i = 0; i < leaves.Count; i++)
			{
				var idx = leaves[i];
				if (adj[idx].Count == 0)
				{
					color[idx] = 1;
					break;
				}
				if(adj[idx].Count != 1) throw new AccessViolationException();
				color[idx] = 2;
				var next = adj[idx].Single();
				if (color[next] == 1)
				{
					Console.WriteLine("First");
					return;
				}
				color[next] = 1;
				adj[next].Remove(idx);
				if (adj[next].Count == 1 && color[adj[next].Single()] == 0)
				{
					leaves.Add(next);
				}
			}
			var res = Dfs(1, -1);
			var output = res ? "First" : "Second";
			Console.WriteLine(output);
		}

		private bool Dfs(int u, int p)
		{
			if (color[u] == 1)
			{
				var hasBlack = false;
				foreach (var v in orig[u])
				{
					if (color[v] == 2)
					{
						hasBlack = true;
						break;
					}
				}
				if (!hasBlack)
				{
					return true;
				}
			}
			foreach (var v in orig[u])
			{
				if (v != p)
				{
					if (Dfs(v, u))
					{
						return true;
					}
				}
			}
			return false;
		}

