public class Test
{
    public static void Main()
    {
        var N = long.Parse(Console.ReadLine());

        var adj = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            adj[i] = new List<int>();
        }

        for (var i = 0; i < N - 1; i++)
        {
            var line1 = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

            adj[line1[0] - 1].Add(line1[1] - 1);
            adj[line1[1] - 1].Add(line1[0] - 1);
        }

        Queue<Tuple<int, int>> q = new Queue<Tuple<int, int>>();

        int[] type = new int[N];

        for (int i = 0; i < N; i++)
        {
            type[i] = -1;
        }

        for (int i = 0; i < N; i++)
        {
            if (adj[i].Count == 1)
            {
                q.Enqueue(Tuple.Create(i, 0));  /// 0 が × です
            }
        }

        while (q.Count != 0)
        {
            var next = q.Dequeue();

            foreach (var point in adj[next.Item1])
            {
                if (type[point] == -1)
                {
                    type[point] = 1 - next.Item2;
                    q.Enqueue(Tuple.Create(point, 1 - next.Item2));
                }
                else if(type[point] != next.Item2 || adj[point].Count >= 3)
                {
                    Console.WriteLine("First");
                    return;
                }
            }
        }

        Console.WriteLine("Second");
    }
}

