			for (var i = 0; i < N; i++) es[i] = new List<int>();
			foreach (var r in rs)
			{
				int a = r.Item1 - 1, b = r.Item2 - 1;
				es[a].Add(b);
				es[b].Add(a);
			}
			for (var i = 0; i < N; i++)
