using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N;
    private List<int>[] E;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }


        var q = new Queue<int>();
        for (int i = 0; i < N; i++)
        {
            if (E[i].Count == 1) q.Enqueue(i);
        }
        var f = new bool[N];
        while (q.Count > 0)
        {
            int d = q.Dequeue();
            bool flag = false;
            foreach (int i in E[d])
            {
                if(f[i]) continue;
                if (flag) q.Enqueue(i);
                else
                {
                    f[d] = true;
                    f[i] = true;
                    flag = true;
                }
            }

            if (!flag)
            {
                Console.WriteLine("First");
                return;
            }
        }

        Console.WriteLine("Second");
    }

    public static void Main(string[] args) => new Program().Solve();
}

