            int[] b = new int[N - 1];
            for (int i = 0; i < N - 1; ++i)
            {
                io.ReadSplit();
                a[i] = io.Int();
                b[i] = io.Int();
            }

            List<int>[] V = new List<int>[N + 1];
            for (int i = 1; i <= N; ++i)
            {
                V[i] = new List<int>();
            }

            for (int i = 0; i < N - 1; ++i)
            {
                V[a[i]].Add(b[i]);
                V[b[i]].Add(a[i]);
            }

            for (int i = 1; i <= N; ++i)
            {
                int leaf_count = 0;
                foreach (int j in V[i])
                {
                    if (V[j].Count == 1)
                    {
                        leaf_count += 1;
                    }
                }
                if (leaf_count > 1)
                {
                    io.WriteLine("First");
                    return;
                }
            }
            io.WriteLine("Second");
        }
    }
