        static void Method(string[] args)
        {
            int n = ReadInt();
            HashSet<int>[] graph = new HashSet<int>[n];
            for(int i = 0; i < n; i++)
            {
                graph[i] = new HashSet<int>();
            }
            for (int i = 0; i < n - 1; i++)
            {
                int[] ab = ReadInts();
                int a = ab[0] - 1;
                int b = ab[1] - 1;
                graph[a].Add(b);
                graph[b].Add(a);
            }

            var que = new Queue<int>();
            for (int i = 0; i < n; i++)
            {
                if (graph[i].Count == 1)
                {
                    que.Enqueue(i);
                }
            }

            int cnt = 0;
            while (que.Count > 0)
            {
                int now = que.Dequeue();
                if (graph[now].Count != 1)
                {
                    continue;
                }

                int to = graph[now].First();
                if (graph[to].Count <= 2)
                {
                    graph[now].Remove(to);
                    graph[to].Remove(now);
                    cnt += 2;
                    foreach(int to2 in graph[to])
                    {
                        graph[to2].Remove(to);
                        que.Enqueue(to2);
                    }
                    graph[to].Clear();
                }
            }

            if (cnt < n)
            {
                WriteLine("First");
                return;
            }

            WriteLine("Second");
        }

