            G[a].Add(b);
            G[b].Add(a);
        }
        us = new bool[N];
        if(G[0].Count == 1){
            dfs(G[0][0]);
        }
        else{
            dfs(0);
        }
        sb.Append((b ? "First" : "Second")+"\n");
    }
    int dfs(int v){
        us[v] = true;
        if(G[v].Count == 1){
            return 1;
        }
        int state = 0;
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if(!us[t]){
                int j = dfs(t);
                if(state == 0){
                    if(j == 1){
                        state = 1;
                    }
                }
                else{
                    if(j == 1){
                        b = true;
                    }
                }
            }
        }
        if(state == 1){
            return 0;
        }
        else{
            return 1;
        }
    }
