namespace CodeChallenges
{
    using CodeChallenges.Boilerplate;

    class ConcreteSolver: BaseSolver
    {
        private readonly BufferedStreamReader reader;
        private readonly FormattedStreamWriter writer;

        public ConcreteSolver(BufferedStreamReader reader, FormattedStreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        public override void Do()
        {
            var n = reader.ReadInt();
            var nodes = new List<int>[n];
            var was = new bool[n];
            var dead = new bool[n];
            var parent = new int[n];
            for (int i = 0; i < n; ++i)
                nodes[i] = new List<int>();
            for (int i = 0;i < n - 1; ++i)
            {
                var a = reader.ReadInt() - 1;
                var b = reader.ReadInt() - 1;
                nodes[a].Add(b);
                nodes[b].Add(a);
            }
            var st = new Stack<int>();
            st.Push(0);
            was[0] = true;
            while (st.Count > 0)
            {
                var nd = st.Pop();
                foreach (var cn in nodes[nd])
                    if (!was[cn])
                    {
                        was[cn] = true;
                        parent[cn] = nd;
                        st.Push(cn);
                    }
            }
            st.Push(0);
            was = new bool[n];
            was[0] = true;
            while (st.Count > 0)
            {
                var nd = st.Peek();
                foreach (var cn in nodes[nd])
                    if (!was[cn])
                    {
                        was[cn] = true;
                        st.Push(cn);
                    }
                if (nd == st.Peek())
                {
                    st.Pop();
                    int alive = 0;
                    foreach (var cn in nodes[nd])
                        if (cn != parent[nd])
                            alive += dead[cn] ? 0 : 1;
                    if (alive > 1)
                    {
                        writer.WriteLine("First");
                        return;
                    }
                    else if (alive == 1)
                        dead[nd] = true;
                }
            }            
            writer.WriteLine(!dead[0] ? "First" : "Second");
        }
    }
}

