namespace CodeChallenges
{
    using CodeChallenges.Boilerplate;

    class ConcreteSolver: BaseSolver
    {
        private readonly BufferedStreamReader reader;
        private readonly FormattedStreamWriter writer;

        public ConcreteSolver(BufferedStreamReader reader, FormattedStreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        public override void Do()
        {
            var n = reader.ReadInt();
            var nodes = new List<int>[n];
            var ch = new int[n];
            var was = new bool[n];
            var sol = new int[n];
            for (int i = 0; i < n; ++i)
                nodes[i] = new List<int>();
            for (int i = 0;i < n - 1; ++i)
            {
                var a = reader.ReadInt() - 1;
                var b = reader.ReadInt() - 1;
                nodes[a].Add(b);
                nodes[b].Add(a);
                ++ch[a];
                ++ch[b];
            }
            var q = new Queue<int>();
            for (int i = 0; i < n; ++i)
                if (ch[i] == 1)
                {
                    q.Enqueue(i);
                    was[i] = true;
                }
            while (q.Count > 0)
            {
                if (q.Count == 1)
                {
                    writer.WriteLine("First");
                    return;
                }
                var ops = q.Count;                
                while (ops-- > 0)
                {
                    var nd = q.Dequeue();
                    foreach (var chnd in nodes[nd])
                        if (!was[chnd])
                        {
                            ++sol[chnd];
                            --ch[chnd];
                            if (sol[chnd] >= 2)
                            {
                                writer.WriteLine("First");
                                return;
                            }
                        }
                    q.Enqueue(nd);
                }
                ops = q.Count;
                var tempq = new Queue<int>();
                while (q.Count > 0)
                {
                    var nd = q.Dequeue();
                    foreach (var chnd in nodes[nd])
                        if (!was[chnd] && ch[chnd] <= 1)
                        {
                            was[chnd] = true;
                            foreach (var gnd in nodes[chnd])
                                if (!was[gnd])
                                {
                                    --ch[gnd];
                                    tempq.Enqueue(gnd);
                                }
                        }
                }
                while (tempq.Count > 0)
                {
                    var nd = tempq.Dequeue();
                    if (!was[nd] && ch[nd] <= 1)
                    {
                        was[nd] = true;
                        q.Enqueue(nd);
                    }
                }
            }
            writer.WriteLine("Second");
        }
    }
}

