            {
                if (graph[i].Count == 1
                    && !states[graph[i][0]])
                {
                    states[graph[i][0]] = true;
                    que.Enqueue(graph[i][0]);
                    cnt++;
                }
            }

            while (que.Count > 0)
            {
                int now = que.Dequeue();
                if (states[now])
                {
                    continue;
                }

                var que2 = new Queue<int>();
                for(int i = 0; i < graph[now].Count; i++)
                {
                    int to = graph[now][i];
                    if (states[to])
                    {
                        continue;
                    }

                    que2.Enqueue(to);
                }

                while (que2.Count > 0)
                {
                    int to = que2.Dequeue();
                    for(int i = 0; i < graph[to].Count; i++)
                    {
                        int to2 = graph[to][i];
                        if (states[to2])
                        {
                            continue;
                        }

                        states[to2] = true;
                        que.Enqueue(to2);
                        cnt++;
                    }
                }
            }

            if (cnt * 2 < n)
            {
                WriteLine("First");
                return;
            }

            for(int i = 0; i < n; i++)
            {
                if (!states[i])
                {
                    continue;
                }

                int whites = 0;
                for(int j = 0; j < graph[i].Count; j++)
                {
                    if (states[graph[i][j]])
                    {
                        whites++;
                    }
                }
                if (whites == graph[i].Count)
                {
                    WriteLine("First");
                    return;
                }
            }

            WriteLine("Second");
        }

