    class AGC014_D
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            List<int>[] graph = new List<int>[n];
            for (int i = 0; i < n; i++)
            {
                graph[i] = new List<int>();
            }
            for (int i = 0; i < n - 1; i++)
            {
                int[] ab = ReadInts();
                int a = ab[0] - 1;
                int b = ab[1] - 1;
                graph[a].Add(b);
                graph[b].Add(a);
            }

            int[] parents = new int[n];
            var que = new Queue<int>();
            var stk = new Stack<int>();
            que.Enqueue(0);
            stk.Push(0);
            parents[0] = -1;
            while (que.Count > 0)
            {
                int now = que.Dequeue();
                foreach (int to in graph[now])
                {
                    if (to == parents[now])
                    {
                        continue;
                    }

                    parents[to] = now;
                    que.Enqueue(to);
                    stk.Push(to);
                }
            }

            while (stk.Count > 0)
            {
                int now = stk.Pop();
                if (graph[now].Count == 0)
                {
                    continue;
                }

                if (parents[now] == -1 || graph[parents[now]].Count == 0)
                {
                    WriteLine("First");
                    return;
                }

                graph[parents[now]].Clear();
            }

            WriteLine("Second");
        }

