using namespace std;

const int N = 1e6 + 10;
int cnt[N], n, v, u;
bool white[N], allchild[N];
vector<int> g[N];

void dfs(int v, int p){
	for (int u : g[v])
		if(u != p)
			dfs(u, v);
	cnt[v] = 1;
	for (int u : g[v])
		if(u != p)
			cnt[v] += cnt[u];
	if(cnt[v] % 2 == 0)
		white[v] = true;
	bool f = true;
	for (int u : g[v])
		if(u != p)
			if(!white[u])
				f = false;
	allchild[v] = f;
}

