    fn dfs(cur: usize, par: usize, adj: &Vec<Vec<usize>>, mut used: &mut Vec<bool>) {
        for &nxt in &adj[cur] {
            if nxt != par {
                dfs(nxt, cur, adj, used);
            }
        }
        if used[cur] || used[par] {
            return;
        }
        if cur != par {
            used[cur] = true;
            used[par] = true;
        }
    }
    let mut used = vec![false; n];
    dfs(0, 0, &adj, &mut used);
    // println!("{:?}", used);
    println!("{}",
             if used.iter().any(|&x| x == false) {
                 "First"
             } else {
                 "Second"
             });
}

