    let mut is_odd = vec![true; n];
    for &ti in topological_sorted_indexes.iter().rev() {
        for &ci in tree[ti].iter() {
            is_odd[ti] ^= is_odd[ci];
        }
    }

    let mut from_parent = vec![false; n];
    for &ti in topological_sorted_indexes.iter() {
        let mut from_grand_parent = false;
        if ti != 0 {
            from_grand_parent = from_parent[ti];
        }
        for &ci in tree[ti].iter() {
            from_parent[ci] = (is_odd[ti] != is_odd[ci]) ^ from_grand_parent;
