#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Adjacent {
    pub to: usize,
    pub id: usize,
}
impl Adjacent {
    pub fn new(to: usize, id: usize) -> Adjacent {
        Adjacent { to: to, id: id }
    }
}
#[derive(Clone, Debug, Default)]
pub struct Graph {
    pub vsize: usize,
    pub esize: usize,
    pub graph: Vec<Vec<Adjacent>>,
}
impl Graph {
    pub fn new(vsize: usize) -> Graph {
        Graph {
            vsize: vsize,
            esize: 0,
            graph: vec![vec![]; vsize],
        }
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(Adjacent::new(to, self.esize));
        self.esize += 1;
    }
    pub fn add_undirected_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(Adjacent::new(v, self.esize));
        self.graph[v].push(Adjacent::new(u, self.esize));
        self.esize += 1;
    }
    pub fn vertexes(&self) -> std::ops::Range<usize> {
        0..self.vsize
    }
    pub fn adjacency(&self, from: usize) -> &Vec<Adjacent> {
        &self.graph[from]
    }
}
#[derive(Debug)]
pub struct TreeRec {
    pub n: usize,
    pub ans: bool,
    pub dp: Vec<bool>,
}
impl TreeRec {
    pub fn new(n: usize) -> TreeRec {
        TreeRec {
            n: n,
            ans: false,
            dp: vec![false; n],
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        let mut fc = 0;
        for v in graph.adjacency(u) {
            if v.to != p {
                self.dfs(v.to, u, graph);
                if !self.dp[v.to] {
                    fc += 1;
                }
            }
        }
        if fc >= 2 || p == self.n && fc == 0 {
            self.ans = true;
        } else if fc == 1 {
            self.dp[u] = true;
        }
    }
}
fn main() {
    input! { n, ab: [(usize1, usize1); n-1] };
    let mut g = Graph::new(n);
    let mut rec = TreeRec::new(n);
    for &(a, b) in &ab {
        g.add_undirected_edge(a, b);
    }
    rec.dfs(0, n, &g);
    println!("{}", if rec.ans { "First" } else { "Second" });
}

