type Graph = Vec<Vec<usize>>;

fn dfs_cpo(g: &Graph, root: usize) -> (Vec<usize>, Vec<Option<usize>>, Vec<usize>) {
    let n = g.len();
    struct Cpo {
        count: Vec<usize>,
        parent: Vec<Option<usize>>,
        order: Vec<usize>,
        oidx: usize
    };
    let mut cpo = Cpo {
        count: vec![0; n],
        parent: vec![None; n],
        order: vec![0; n],
        oidx: 0
    };

    fn dfs(g: &Graph, now: usize, par: Option<usize>, cpo: &mut Cpo) {
        for &to in &g[now] {
            if Some(to) != par {
                dfs(g, to, Some(now), cpo);
            }
        }
        cpo.count[now] = 1;
        for &to in &g[now] {
            if Some(to) != par {
                cpo.count[now] += cpo.count[to];
            }
        }
        cpo.parent[now] = par;
        cpo.order[cpo.oidx] = now;
        cpo.oidx += 1;

    }
    dfs(&g, root, None, &mut cpo);
    (cpo.count, cpo.parent, cpo.order)
}

fn solve(g: Vec<Vec<usize>>) -> bool {
    let n = g.len();
    let (_, parent, order) = dfs_cpo(&g, 0);


    let mut white_flag = vec![0; n];
    for i in 0..n {
        let now = order[i];
        if white_flag[now] == 0 {
            if let Some(p) = parent[now] {
                white_flag[p] += 1;
            } else {
                return true;
            }
        } else if white_flag[now] >= 2 {
            return true;
        }
    }
    false
}

fn main() {
    input! {
        n: usize,
        edges: [(usize1, usize1); n-1]
    };

    let mut g = vec![vec![]; n];
    for &(u,v) in &edges {
        g[u].push(v);
        g[v].push(u);
    }

    println!("{}", ifv!(solve(g), "First", "Second"));
}

use std::io::Read;
use std::collections::HashMap;

fn check(cnt: [usize; 3]) -> usize {
    if cnt[2] > 0 || cnt[1] >= 2 { 2 }
    else if cnt[1] == 0 { 1 }
    else { 0 }
}

#[derive(Default)]
struct Solver {
    all : HashMap<usize, [usize; 3]>,
    part : HashMap<(usize, usize), usize>
}

impl Solver {
    fn solve_impl(&mut self, g: &Vec::<Vec::<usize>>, pos: usize, prev: usize) -> usize {
        let n = g.len();
        if self.part.contains_key(&(pos, prev)) { return self.part[&(pos, prev)]; }
        if prev != n && self.all.contains_key(&pos){
            let mut cnt = self.all[&pos];
            cnt[self.solve_impl(g, prev, pos)] -= 1;
            let res = check(cnt);
            self.part.insert((pos, prev), res);
            return res;
        }
        let mut cnt = [0; 3];
        for &next in &g[pos] {
            if next == prev { continue; }
            cnt[self.solve_impl(g, next, pos)] += 1;
        }
        let res = check(cnt);
        if prev == n { self.all.insert(pos, cnt); }
        self.part.insert((pos, prev), res);
        res
    }

    pub fn solve(&mut self, g: &Vec::<Vec::<usize>>) -> bool {
        let n = g.len();
        for i in 0..n {
            if self.solve_impl(g, i, n) == 2 { return true; }
        }
        false
    }
}

