        let a = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[a].push(b);
        g[b].push(a);
    }
    let mut s = Solver::default();
    println!("{}", if s.solve(&g) { "First" } else { "Second" });
}

