#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Adjacent {
    pub to: usize,
    pub id: usize,
}
impl Adjacent {
    pub fn new(to: usize, id: usize) -> Adjacent {
        Adjacent { to: to, id: id }
    }
}
#[derive(Clone, Debug, Default)]
pub struct Graph {
    pub vsize: usize,
    pub esize: usize,
    pub graph: Vec<Vec<Adjacent>>,
}
impl Graph {
    pub fn new(vsize: usize) -> Graph {
        Graph {
            vsize: vsize,
            esize: 0,
            graph: vec![vec![]; vsize],
        }
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(Adjacent::new(to, self.esize));
        self.esize += 1;
    }
    pub fn add_undirected_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(Adjacent::new(v, self.esize));
        self.graph[v].push(Adjacent::new(u, self.esize));
        self.esize += 1;
    }
    pub fn vertexes(&self) -> std::ops::Range<usize> {
        0..self.vsize
    }
    pub fn adjacency(&self, from: usize) -> &Vec<Adjacent> {
        &self.graph[from]
    }
}
#[derive(Debug)]
pub struct TreeRec {
    pub n: usize,
    pub ans: bool,
    pub dp: Vec<bool>,
}
impl TreeRec {
    pub fn new(n: usize) -> TreeRec {
        TreeRec {
            n: n,
            ans: false,
            dp: vec![false; n],
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        let mut fc = 0;
        let mut cc = 0;
        for v in graph.adjacency(u) {
            if v.to != p {
                self.dfs(v.to, u, graph);
                cc += 1;
                if !self.dp[v.to] {
                    fc += 1;
                }
            }
        }
        if fc >= 2 || p == self.n && cc - fc == 1 {
            self.ans = true;
        } else if fc == 1 {
            self.dp[u] = true;
        }
    }
}
fn main() {
    input! { n, ab: [(usize1, usize1); n-1] };
    let mut g = Graph::new(n);
    let mut rec = TreeRec::new(n);
    for &(a, b) in &ab {
        g.add_undirected_edge(a, b);
    }
    rec.dfs(0, n, &g);
    println!("{}", if rec.ans { "First" } else { "Second" });
}

use std::io::{self, Stdin};
use std::str::{self, FromStr};
use std::error::Error;

fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let mut degree = vec![0; n];
    let mut adj = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let u = sc.ne::<usize>() - 1;
        let v = sc.ne::<usize>() - 1;
        degree[u] += 1;
        degree[v] += 1;
        adj[u].push(v);
        adj[v].push(u);
    }
    fn win() {
        println!("First");
        std::process::exit(0);
    }
    fn lose() {
        println!("Second");
        std::process::exit(0);
    }
    let mut flag = false;
    for i in 0..n {
        let mut cnt = 0;
        for &v in &adj[i] {
            if degree[v] == 1 {
                cnt += 1;
            }
        }
        if cnt >= 2 {
            win();
        }
    }
    lose();
}

fn main() {
    const STACK: usize = 16 * 1024 * 1024;
    let _ = std::thread::Builder::new()
        .stack_size(STACK)
        .spawn(|| { exec(); })
        .unwrap()
        .join()
        .unwrap();
}

#[allow(dead_code)]
struct Scanner {
    stdin: Stdin,
    id: usize,
    buf: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            id: 0,
            buf: Vec::new(),
        }
    }
    fn next_line(&mut self) -> Option<String> {
        let mut res = String::new();
        match self.stdin.read_line(&mut res) {
            Ok(0) => None,
            Ok(_) => Some(res),
            Err(why) => panic!("error in read_line: {}", why.description()),
        }
    }
    fn next<T: FromStr>(&mut self) -> Option<T> {
        while self.buf.len() == 0 {
            self.buf = match self.next_line() {
                Some(r) => {
                    self.id = 0;
                    r.trim().as_bytes().to_owned()
                }
                None => return None,
            };
        }
        let l = self.id;
        assert!(self.buf[l] != b' ');
        let n = self.buf.len();
        let mut r = l;
        while r < n && self.buf[r] != b' ' {
            r += 1;
        }
        let res = match str::from_utf8(&self.buf[l..r])
                  .ok()
                  .unwrap()
                  .parse::<T>() {
            Ok(s) => Some(s),
            Err(_) => {
                panic!("parse error, {:?}",
                       String::from_utf8(self.buf[l..r].to_owned()))
            }
        };
        while r < n && self.buf[r] == b' ' {
            r += 1;
        }
        if r == n {
            self.buf.clear();
        } else {
            self.id = r;
        }
        res
    }
    fn ne<T: FromStr>(&mut self) -> T {
        self.next::<T>().unwrap()
    }
}

use std::io::Read;
use std::collections::HashMap;

fn check(cnt: [usize; 3]) -> usize {
    if cnt[2] > 0 || cnt[1] >= 2 { 2 }
    else if cnt[1] == 0 { 1 }
    else { 0 }
}

#[derive(Default)]
struct Solver {
    all : HashMap::<usize, [usize; 3]>,
    part : HashMap::<(usize, usize), usize>
}

impl Solver {
    fn solve_impl(&mut self, g: &Vec::<Vec::<usize>>, pos: usize, prev: usize) -> usize {
        let n = g.len();
        if self.part.contains_key(&(pos, prev)) { return self.part[&(pos, prev)]; }
        if prev != n && self.all.contains_key(&pos){
            let mut cnt = self.all[&pos];
            cnt[self.solve_impl(g, prev, pos)] -= 1;
            let res = check(cnt);
            self.part.insert((pos, prev), res);
            return res;
        }
        let mut cnt = [0; 3];
        for &next in &g[pos] {
            if next == prev { continue; }
            cnt[self.solve_impl(g, next, pos)] += 1;
        }
        let res = check(cnt);
        if prev == n { self.all.insert(pos, cnt); }
        self.part.insert((pos, prev), res);
        res
    }

    pub fn solve(&mut self, g: &Vec::<Vec::<usize>>) -> bool {
        let n = g.len();
        for i in 0..n {
            if self.solve_impl(g, i, n) == 2 { return true; }
        }
        false
    }
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).ok();
    let mut it = buf.split_whitespace();
    let n = it.next().unwrap().parse::<usize>().unwrap();
    let mut g = vec![Vec::<usize>::new(); n];
    for _ in 0..n-1 {
        let a = it.next().unwrap().parse::<usize>().unwrap() - 1;
        let b = it.next().unwrap().parse::<usize>().unwrap() - 1;
        g[a].push(b);
        g[b].push(a);
    }
    let mut s = Solver::default();
    println!("{}", if s.solve(&g) { "First" } else { "Second" });
}
